/* eslint-disable */
/* Edge notes, English (draft). The Chinese note in src/data/packs is authoritative;
   English is attached by edge id. basedOn = zhHash of the current note. */
window.MG = window.MG || {};
window.MG.i18nEdgeNotes = {
  "def-link.nthroot-convergence-radius": { note: { en: "AUD-061, category A. Originally recorded as definition; changed to implication because the splitting step really uses the nth-root theorem (existence, uniqueness, multiplicativity) as its engine.", status: 'draft', basedOn: 'v0.9.3#8b43ab0c' } },
  "def-link.nthroot-root-test": { note: { en: "AUD-061, category A. Originally recorded as definition; changed to implication because the source is a theorem and the whole statement of the test presupposes it (it is not definitional notation).", status: 'draft', basedOn: 'v0.9.3#9c5bb4cb' } },
  "def-link.recursion-wellordering": { note: { en: "When proving the well-ordering theorem one uses transfinite recursion to pick elements step by step along a well-order.", status: 'draft', basedOn: 'v0.9.3#2988599c' } },
  "def-link.variations-ac": { note: { en: "AUD-061, category A. Originally recorded as definition; changed to implication because both the statement and the proof rest on $\\nu^{\\pm}$ and $\\lvert\\nu\\rvert$ supplied by the Jordan decomposition.", status: 'draft', basedOn: 'v0.9.3#0e9e6e34' } },
  "dep-dif-egregium": { note: { en: "$K$ is an isometric invariant — this is the other half of \"developable is equivalent to $K = 0$\".", status: 'draft', basedOn: 'v0.9.3#0148292a' } },
  "dep.cantor-uncountable": { note: { en: "The second half, $2^{\\aleph_0} > \\aleph_0$, uses exactly Cantor's theorem ($\\#A < \\#\\mathcal{P}(A)$).", status: 'draft', basedOn: 'v0.9.3#ed4e62df' } },
  "dep.intdiv-wellorder": { note: { en: "**Cross-region bridge (order theory $\\leftrightarrow$ number)**: the existence step uses the well-ordering of $\\mathbb{N}$ (take the least nonnegative remainder). This is a **proof dependency**, not a definitional one — the statement of division with remainder does not mention well-ordering.", status: 'draft', basedOn: 'v0.9.3#20d52d54' } },
  "dep.mf3-dm-pullback": { note: { en: "Chart-independence rests on \"$\\mathrm{d}$ commutes with pullback\" (already proved in the open-set case), which is the engine of the proof.", status: 'draft', basedOn: 'v0.9.3#22ba08d4' } },
  "dep.modulehom-submodule": { note: { en: "This is a criterion (kernel and image lie in submodules), not a definitional dependency: the definition of a module homomorphism does not presuppose submodules.", status: 'draft', basedOn: 'v0.9.3#18c6913e' } },
  "dep.omega-induction": { note: { en: "Both induction and recursive definition come from \"$\\omega$ is the **smallest inductive set**\".", status: 'draft', basedOn: 'v0.9.3#9b6f096d' } },
  "dep.pcp-urysohn-lemma-metrization": { note: { en: "AUD-061, category A. Originally recorded as definition; changed to implication because the separating family of functions is the engine of the whole proof. ⚠ The graph's `thm.urysohn-metrization` has another proof edge via Nagata–Smirnov (source `thm.nagata-smirnov`); this edge corresponds to the embedding proof in the notes, and the two are **different proofs**, not duplicates.", status: 'draft', basedOn: 'v0.9.3#0f930844' } },
  "dep.ringhom-ideal": { note: { en: "This is a criterion (the kernel lies in an ideal), not a definitional dependency: the definition of a ring homomorphism does not presuppose ideals.", status: 'draft', basedOn: 'v0.9.3#6915313f' } },
  "e100.implication": { note: { en: "The group structure explains \"three points determine a transformation\": the group on the left-hand side acts 3-transitively on the extended plane.", status: 'draft', basedOn: 'v0.9.3#d14e3137' } },
  "e101.implication": { note: { en: "This table is the practical core of the chapter on conformal maps.", status: 'draft', basedOn: 'v0.9.3#7afb88f1' } },
  "e105.implication": { note: { en: "After adjoining this one point, \"lines\" and \"circles\", \"entire functions\" and \"meromorphic at $\\infty$\", each merge into a single class.", status: 'draft', basedOn: 'v0.9.3#de8d893f' } },
  "e106.implication": { note: { en: "\"Circles on the sphere $\\to$ circles or lines in the plane\" is the source of circle-preservation.", status: 'draft', basedOn: 'v0.9.3#2412ed45' } },
  "e109.implication": { note: { en: "Chain homotopy is the purely algebraic counterpart of \"homotopy\": when there is no space to deform, one deforms the map itself.", status: 'draft', basedOn: 'v0.9.3#f28b2615' } },
  "e11.implication": { note: { en: "\"Holomorphy is closed under uniform convergence\" — the foundation of normal family theory.", status: 'draft', basedOn: 'v0.9.3#1bd582ab' } },
  "e12.implication": { note: { en: "Equicontinuity upgrades \"pointwise convergence\" to \"uniform convergence\" — exactly what families of holomorphic functions obtain for free.", status: 'draft', basedOn: 'v0.9.3#01f68f68' } },
  "e20.implication": { note: { en: "This is the bridge by which \"winding number\" enters \"counting zeros\": the number of zeros of $f$ becomes the number of turns of $f\\circ\\gamma$ around $0$.", status: 'draft', basedOn: 'v0.9.3#49ddd1b1' } },
  "e23.implication": { note: { en: "Single-valuedness is a direct translation of \"homotopy invariance\" — the same technique as `thm.winding-homotopy`: continuous plus discrete $\\implies$ constant.", status: 'draft', basedOn: 'v0.9.3#4712be22' } },
  "e24.implication": { note: { en: "The reflection principle is the most commonly used move for \"continuation\": taking real values on the boundary lets one cross it.", status: 'draft', basedOn: 'v0.9.3#7864c368' } },
  "e26.implication": { note: { en: "Jensen bounds \"how many zeros lie in R\" by \"how large the maximum modulus is on 2R\".", status: 'draft', basedOn: 'v0.9.3#d51afbb5' } },
  "e27.implication": { note: { en: "This estimate is the entire basis for \"choose p so that the series converges\".", status: 'draft', basedOn: 'v0.9.3#ee28c1bb' } },
  "e3.implication": { note: { en: "This step formally connects \"elementary functions\" to complex analysis: they are not new axioms but power series.", status: 'draft', basedOn: 'v0.9.3#b8e590ab' } },
  "e31.implication": { note: { en: "The great theorem = the little theorem + one change of variable; the deep input is likewise marked as external.", status: 'draft', basedOn: 'v0.9.3#d361312c' } },
  "e4.implication": { note: { en: "A local inverse always exists — what is missing is only \"whether it can be patched together globally\", which `prop.single-valued-branch` answers.", status: 'draft', basedOn: 'v0.9.3#11317117' } },
  "e54.implication": { note: { en: "All four items rely on \"reparametrization $+$ the pasting lemma\"; at the level of paths, none of them is an equality.", status: 'draft', basedOn: 'v0.9.3#d5a5e363' } },
  "e56.implication": { note: { en: "There is only one key sentence: $f$ commutes with \"concatenation\". This also explains why $f_{*}$ is a **homomorphism** rather than an arbitrary map.", status: 'draft', basedOn: 'v0.9.3#ff6f846d' } },
  "e57.implication": { note: { en: "\"Differing by an inner automorphism\" is the precise meaning of **not canonical**; only when $\\pi_{1}$ is abelian is it really independent of the path.", status: 'draft', basedOn: 'v0.9.3#de66fc15' } },
  "e6.implication": { note: { en: "Replacing a geometric quantity by an integral is the technical precondition for counting zeros later via the argument principle.", status: 'draft', basedOn: 'v0.9.3#d0736227' } },
  "e62.implication": { note: { en: "Note the role of this edge: `prop.covering-index` is enough only for equipotence, and homomorphicity must be recomputed using **uniqueness of lifts**.", status: 'draft', basedOn: 'v0.9.3#38e42b17' } },
  "e63.implication": { note: { en: "A one-line group-theoretic \"cannot\", backed by the single input $\\pi_{1}(S^{1}) \\ne 1$.", status: 'draft', basedOn: 'v0.9.3#269f2385' } },
  "e7.implication": { note: { en: "The first hinge between complex analysis and topology: the contour integral sees only the homotopy class.", status: 'draft', basedOn: 'v0.9.3#b98a39d4' } },
  "e8.implication": { note: { en: "This is the common precondition for the \"identity theorem\" and for \"the argument principle counts zeros with multiplicity\".", status: 'draft', basedOn: 'v0.9.3#a9b44a6b' } },
  "e85.implication": { note: { en: "The whole argument uses only one fact: \"$\\partial$ applied to a path gives the difference of its two endpoints\".", status: 'draft', basedOn: 'v0.9.3#adfbb4a1' } },
  "e94.implication": { note: { en: "The cross-ratio is worth defining precisely because it is the only invariant under $\\operatorname{PGL}(2,\\mathbb{C})$.", status: 'draft', basedOn: 'v0.9.3#b51028d7' } },
  "e95.implication": { note: { en: "Translate \"concyclic\" into \"whether a complex number is real\" — the basic move of complex geometry.", status: 'draft', basedOn: 'v0.9.3#2db4f508' } },
  "e96.implication": { note: { en: "\"Three points determine a transformation\" gives both existence and an algorithm.", status: 'draft', basedOn: 'v0.9.3#07fe84dc' } },
  "e97.implication": { note: { en: "In the extended plane, \"preserves circles\" is one sentence: lines count as circles too.", status: 'draft', basedOn: 'v0.9.3#0b7d5e82' } },
  "e98.implication": { note: { en: "Symmetry $\\ne$ equal distance to the centre; symmetry is inversion, and the **product** of the distances is fixed.", status: 'draft', basedOn: 'v0.9.3#858d2ea3' } },
  "imp.abel-dirichlet": { note: { en: "Summation by parts is the engine of this family: it replaces \"the tail of $\\sum a_n b_n$\" by \"$A_k$ and the increments of $b$\", so that **bounded partial sums** ($A$) and **monotone convergence to zero** ($b$) each play their part once. The Leibniz test follows by taking $a_n = (-1)^{n}$.", status: 'draft', basedOn: 'v0.9.3#b564c662' } },
  "imp.absolute-implies": { note: { en: "There is **no hypothesis about signs anywhere** in the proof — which is why it holds simultaneously for real and complex series.", status: 'draft', basedOn: 'v0.9.3#1ce4abe8' } },
  "imp.adjoint-criterion": { note: { en: "This reduces \"constructing a right adjoint\" to \"finding a representing object for each $Y$\". The Yoneda lemma does the key step here: **$G(g)$ on the morphism level is read off from the natural transformation**, with no need to assemble it by hand.", status: 'draft', basedOn: 'v0.9.3#e176775e' } },
  "imp.adjoint-ff": { note: { en: "This replaces \"the functor is bijective on both Hom-sets\" by \"a natural transformation is invertible everywhere\" — far less to check.", status: 'draft', basedOn: 'v0.9.3#d9b78719' } },
  "imp.banach-fixed-point": { note: { en: "⭐ The structure is worth memorizing: **build a Cauchy sequence $\\to$ pass to the limit using completeness $\\to$ verify the fixed point using continuity $\\to$ get uniqueness from $1 - q > 0$**. The four properties used are exactly the four hypotheses, no more and no less.", status: 'draft', basedOn: 'v0.9.3#ca06f334' } },
  "imp.bernstein-approximation": { note: { en: "The only external input is \"continuous on a compact set $\\implies$ uniformly continuous\"; the binomial moments and Markov's inequality are computed on the edge itself.", status: 'draft', basedOn: 'v0.9.3#3c98f2cc' } },
  "imp.bounded-evt": { note: { en: "Both limits in step 3 must exist before \"uniqueness of limits\" can be used: the existence of the left-hand one comes from continuity, that of the right-hand one from the definition of $\\sup$. Compactness is used only once, in step 2.", status: 'draft', basedOn: 'v0.9.3#2eab3379' } },
  "imp.bounded-operators-banach-proof": { note: { en: "The complete proof is on this edge; the node's notes retain only the motivation and the gaps.", status: 'draft', basedOn: 'v0.9.3#01128554' } },
  "imp.burali-forti": { note: { en: "\"The class of all ordinals\" **is not a set** — so the Separation schema cannot be applied to it. This is exactly ZFC's uniform way of handling Russell's paradox and the Burali–Forti paradox.", status: 'draft', basedOn: 'v0.9.3#a1a817c4' } },
  "imp.bw-cauchy": { note: { en: "Step 1 (a Cauchy sequence is bounded) is the most easily overlooked step, yet it must be written out — without it Bolzano–Weierstrass cannot be applied.", status: 'draft', basedOn: 'v0.9.3#a6b5e6e3' } },
  "imp.bw-heineborel": { note: { en: "Both hypotheses are indispensable: **completeness** of $\\mathbb{R}^{n}$ (Bolzano–Weierstrass) gives \"bounded $\\implies$ a convergent subsequence\", while the **general facts** about metric spaces give \"compact $\\iff$ sequentially compact\" and \"compact $\\implies$ closed\".", status: 'draft', basedOn: 'v0.9.3#0c3292a1' } },
  "imp.by-parts": { note: { en: "The step \"a product of integrable functions is integrable\" deserves attention: integration by parts **transfers** the integrability of $FG'$ to $F'G$ — so the real use of the formula is to swap in a partner that is easier to integrate.", status: 'draft', basedOn: 'v0.9.3#8c5f5547' } },
  "imp.cauchy-complete": { note: { en: "The role of this edge is to align two languages: on $\\mathbb{R}$, \"the least-upper-bound principle\" on the **order** side and \"completeness\" on the **metric** side say the same thing.", status: 'draft', basedOn: 'v0.9.3#db8af526' } },
  "imp.cauchy-condensation": { note: { en: "The factor $\\frac{1}{2}$ shows why the constants on the two sides do not matter — boundedness cares only whether something is bounded, not by how much.", status: 'draft', basedOn: 'v0.9.3#5d8c4975' } },
  "imp.cauchy-in-measure": { note: { en: "The key in ② is $\\sum 2^{-k} < \\infty$ — precisely this makes the tail union of the \"bad sets\" tend to zero, which is the spirit of Borel–Cantelli.", status: 'draft', basedOn: 'v0.9.3#8828f073' } },
  "imp.cauchy-mvt": { note: { en: "The auxiliary function $h$ is a generalization of the \"chord\": when $g(x) = x$, $h$ is a constant multiple of the $g$ in the Lagrange version.", status: 'draft', basedOn: 'v0.9.3#21da511c' } },
  "imp.cauchy-schwarz": { note: { en: "The key to the proof is \"**nonnegative for every $t$**\": this gives a quadratic function of $t$ that is always nonnegative, so its discriminant is $\\le 0$ — and that is precisely Cauchy–Schwarz.", status: 'draft', basedOn: 'v0.9.3#afd48255' } },
  "imp.cayley-hamilton": { note: { en: "Step 3, \"all the middle terms cancel\", is the entire trick: the string of identities is designed to telescope (of the form $A^{k} B_k - A^{k+1}B_{k-1}$), so after summing only the two ends remain.", status: 'draft', basedOn: 'v0.9.3#b6bbf92b' } },
  "imp.change-of-basis": { note: { en: "**No computation is performed anywhere in the proof**: it only writes a change of basis as a composite of three maps and then uses multiplicativity of matrix representations — the biggest dividend of building matrix theory in the language of linear maps.", status: 'draft', basedOn: 'v0.9.3#9275ee06' } },
  "imp.cn-normal": { note: { en: "An inference \"strong $\\implies$ weak\": using a stronger separation axiom to prove a weaker one. If it participated in layering it would invert the layer numbers against the definition edge (regular L18 versus T3.5 L6). It is treated as a **corollary edge**: the implication is genuinely valid, but it is not the construction order.", status: 'draft', basedOn: 'v0.9.3#7cf9afc0' } },
  "imp.coherent-duality": { note: { en: "⚠ This edge's proof is conditional on `prop.open-immersion-shriek` (`prop.open-immersion-shriek` is still a skeleton).", status: 'draft', basedOn: 'v0.9.3#121af8e9' } },
  "imp.compact-complete": { note: { en: "The key lemma is \"a Cauchy sequence with a convergent subsequence $\\implies$ convergence\", and it holds in every metric space.", status: 'draft', basedOn: 'v0.9.3#01836e82' } },
  "imp.compact-hausdorff-locallycompact": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.compact-hausdorff-normal": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.compact-locally-compact": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.comparison-test": { note: { en: "The dependence of the comparison test on \"nonnegativity\" is essential: convergence of $b_n$ gives boundedness of $\\{B_N\\}$, and boundedness of $\\{A_N\\}$ is equivalent to convergence only when it is monotone (that is, $a_n \\ge 0$).", status: 'draft', basedOn: 'v0.9.3#3b58c761' } },
  "imp.completeness-cycle": { note: { en: "This is exactly the meaning of a \"strongly connected block\": **take any one as an axiom and the other five become theorems**. So the question is not \"which one is right\", but \"which formulation is most convenient in the current context\" — later, in a general complete metric space only (6) remains, and in a complete lattice (such as $\\overline{\\mathbb{R}}$) only (1) remains.", status: 'draft', basedOn: 'v0.9.3#c2a24605' } },
  "imp.constant-derivative": { note: { en: "$I$ must be an interval (the segment between any two points lies in $I$) — exactly what is needed to apply the mean value theorem on $[x, y]$ in the proof.", status: 'draft', basedOn: 'v0.9.3#e56f9245' } },
  "imp.convergence-radius": { note: { en: "Note why $\\limsup$ rather than $\\lim$ is necessary: the root test itself is stated with $\\limsup$, so this formula holds for every power series (including those whose coefficients have no limit).", status: 'draft', basedOn: 'v0.9.3#e71f5101' } },
  "imp.convex-criterion": { note: { en: "The whole chain is \"convexity (geometry) $\\iff$ monotone slopes (order) $\\iff f'$ increasing (analysis) $\\iff f'' \\ge 0$ (algebra)\" — each step is just a change of clothes.", status: 'draft', basedOn: 'v0.9.3#3edde2e3' } },
  "imp.cr-regular": { note: { en: "An inference \"strong $\\implies$ weak\": using a stronger separation axiom to prove a weaker one. If it participated in layering it would invert the layer numbers against the definition edge (regular L18 versus T3.5 L6). It is treated as a **corollary edge**: the implication is genuinely valid, but it is not the construction order.", status: 'draft', basedOn: 'v0.9.3#7cf9afc0' } },
  "imp.cramer": { note: { en: "The organization of the proof is worth remembering: **Laplace expansion + displaced expansion = adjugate**, so Cramer's rule is just \"$A^{-1} = \\operatorname{adj}A / \\det A$\" written out in components.", status: 'draft', basedOn: 'v0.9.3#a702fe47' } },
  "imp.darboux-criterion": { note: { en: "Of the two directions, (i) is the real technical work: an **arbitrary** fine partition must be compared with one **fixed** refinement, and the discrepancy consists of those intervals crossing the partition points — their total length is controlled by $\\|Q\\|$.", status: 'draft', basedOn: 'v0.9.3#16385cb9' } },
  "imp.derived-average-limit": { note: { en: "The definition itself says only \"how to average\", not \"what the average converges to\"; the latter half is the content of the theorem, and it is exactly the Lebesgue differentiation theorem.", status: 'draft', basedOn: 'v0.9.3#7e06cd89' } },
  "imp.derived-charpoly-splits": { note: { en: "This holds only over $K = \\mathbb{C}$: over $\\mathbb{R}$ the characteristic polynomial need not split (a plane rotation has no real eigenvalue), and the $n$ roots can be collected only in an extension field.", status: 'draft', basedOn: 'v0.9.3#8d2ea717' } },
  "imp.derived-cif-from-residue": { note: { en: "In other words: Cauchy's integral formula is the special case of the residue theorem with \"a single simple pole\". Both routes are legitimate; the residue route just takes one extra step through a Laurent coefficient.", status: 'draft', basedOn: 'v0.9.3#4f8d8d1c' } },
  "imp.derived-det-volume": { note: { en: "This replaces the \"geometric reading of the determinant\" from a direct volume axiom by an integral: $|\\det|$ is the volume scaling factor because $n$-forms are the only things that integrate naturally.", status: 'draft', basedOn: 'v0.9.3#bcc19bd8' } },
  "imp.derived-implicit-from-rank": { note: { en: "The short textbook route is \"apply the inverse function theorem to $\\Phi(x,y) = (x, F(x,y))$\" (the black edge `imp.implicit-function`); here we take the **submersion case** of the rank theorem. The route is longer, but it makes clear that \"the implicit function theorem is also one square of the rank theorem\". ⚠ ④ uses the inverse function theorem once — this forms a cycle with the black edge, which the rules for pink edges allow (the black edges already ensure that the skeleton is acyclic).", status: 'draft', basedOn: 'v0.9.3#24aae6b8' } },
  "imp.derived-inverse-from-rank": { note: { en: "The black edge `imp.rank-theorem` runs the other way (inverse function theorem $+$ implicit function theorem $\\implies$ rank theorem) — both are present, which exactly draws the picture \"the rank theorem is the whole package, and the inverse function theorem is the case $r=n=m$\". Pink edges do not enter layering and do not form cycles.", status: 'draft', basedOn: 'v0.9.3#145ce7e2' } },
  "imp.derived-lagrange-mvt-from-cauchy": { note: { en: "The real gain of the Cauchy version is \"the two increments use the same $\\xi$\" — that is the doorway to L'Hôpital's rule; taking $g = x$ removes this gain and returns Lagrange.", status: 'draft', basedOn: 'v0.9.3#c4fcc812' } },
  "imp.derived-low-degree-exact": { note: { en: "So the \"low-degree exact sequence\" needs no separate proof: the second row consists of the first terms of the long exact sequence, and the first row is a direct reading of the definitions of $H^{0}$ and $H^{1}$.", status: 'draft', basedOn: 'v0.9.3#7f245c32' } },
  "imp.derived-mean-value-poisson": { note: { en: "At $z = 0$ the Poisson weight function is identically $1$, so the fact that \"the kernel is a partition of unity\" degenerates at the centre into the most elementary average.", status: 'draft', basedOn: 'v0.9.3#9f2f6c85' } },
  "imp.derived-multilinear-tensor-dual": { note: { en: "This shows that a \"multilinear form\" is not a separate species: it is an element of the dual of a tensor power, so multilinear problems can be moved wholesale into linear algebra.", status: 'draft', basedOn: 'v0.9.3#06d7e6e8' } },
  "imp.derived-mvt-from-taylor": { note: { en: "$n = 0$ is the lowest case of Taylor's formula, so the mean value theorem needs no separate place: it is a degenerate member of the same family.", status: 'draft', basedOn: 'v0.9.3#f32e7b40' } },
  "imp.derived-schwarz-from-pick": { note: { en: "The black edge `imp.schwarz-pick` runs the other way (Schwarz lemma $+$ disk automorphisms $\\implies$ Pick). Both coexist: one is a proof route, the other records that \"the lemma is just the case of Pick at the origin\".", status: 'draft', basedOn: 'v0.9.3#4a676640' } },
  "imp.det-as-exterior": { note: { en: "The move in step 3 is worth remembering: **first define the coefficient on a one-dimensional space, then use existence and uniqueness to identify it with the determinant** — thus there is no need actually to compute that coefficient.", status: 'draft', basedOn: 'v0.9.3#efdfe522' } },
  "imp.det-exists-unique": { note: { en: "**Prove uniqueness first, verify existence afterwards**: this is the standard way of defining an object by a universal property — first force every object satisfying the conditions into an explicit formula, then take that formula back and check that it really satisfies them.", status: 'draft', basedOn: 'v0.9.3#12bbb731' } },
  "imp.det-laplace": { note: { en: "The sign $(-1)^{i+j}$ comes from **the number of swaps needed to move $e_i$ to the first position** — which is also the geometric explanation of the \"checkerboard\" signs.", status: 'draft', basedOn: 'v0.9.3#489766c7' } },
  "imp.det-multiplicative": { note: { en: "Step 3, \"differs only by a constant factor\", is the most elegant use of the **uniqueness theorem**: no computation is needed, since a new function satisfying the same axioms is automatically proportional.", status: 'draft', basedOn: 'v0.9.3#a1108f59' } },
  "imp.diagonalizable": { note: { en: "The substantive parts of the proof are **(4) $\\iff$ (3)** (geometric versus algebraic multiplicity) and the last pair (**condition (5) is the square-free criterion**). The first three items merely translate \"diagonalizable\" into \"has $n$ independent eigenvectors\".", status: 'draft', basedOn: 'v0.9.3#f1cd1d0a' } },
  "imp.dif-cgc": { note: { en: "This edge records the dependency only for the step (3) $\\iff$ (4); the equivalences among (1), (2), (3) are given by direct computation and do not pass through the classification of constant curvature.", status: 'draft', basedOn: 'v0.9.3#0d32638c' } },
  "imp.differentiation-general": { note: { en: "All the difficulty is absorbed by \"writing the definition of L_f as $\\int|f(y) - f(x)|$\" — which also explains why the definition is written that way.", status: 'draft', basedOn: 'v0.9.3#cf00d1f2' } },
  "imp.dimension": { note: { en: "The point of this edge is that **\"dimension\" is not defined, it is proved**. It gets its own node in the graph precisely to preserve this proof — rather than burying it in a sentence of the notes for `def.vs`.", status: 'draft', basedOn: 'v0.9.3#c6e7a0a5' } },
  "imp.divisible-quotient": { note: { en: "Compare: a **subgroup** of a divisible group need not be divisible ($\\mathbb{Z} \\subseteq \\mathbb{Q}$). So \"divisible\" is closed under quotients but not under subgroups.", status: 'draft', basedOn: 'v0.9.3#bd13b39d' } },
  "imp.division-algorithm": { note: { en: "The word \"field\" is used once in the existence step ($b_n^{-1}$) and once in the uniqueness step (additivity of degree in an integral domain). Both uses are essential.", status: 'draft', basedOn: 'v0.9.3#9fb43ce0' } },
  "imp.equiv-criterion": { note: { en: "This replaces \"category equivalence\", which looks as if it requires constructing functors, by two conditions that can be **checked pointwise**: a bijection on Hom-sets plus an isomorphism on objects. In practice one almost always uses this edge.", status: 'draft', basedOn: 'v0.9.3#d829daa1' } },
  "imp.exact-couple-spectral": { note: { en: "The whole mechanism of the spectral sequence is two sentences: the derived couple is again an exact couple (so one can iterate), and each derivation by $j$ raises the bidegree by $(1,-1)$ (so the differential shifts one square outward at a time).", status: 'draft', basedOn: 'v0.9.3#ddd8f4fb' } },
  "imp.f-shriek-base-change": { note: { en: "⚠ This edge's proof is conditional on `prop.open-immersion-shriek` (`prop.open-immersion-shriek` is still a skeleton).", status: 'draft', basedOn: 'v0.9.3#121af8e9' } },
  "imp.fa-ascoli": { note: { en: "⚠️ This passage is a **skeleton**: the third passage, \"the construction of $\\Phi$\" (extending values at mesh points by the nearest mesh value), is written differently in different books. The direction is right; the details are not spelled out verbatim.", status: 'draft', basedOn: 'v0.9.3#4a8c9584' } },
  "imp.fa-baire-characterizations": { note: { en: "⚠️ In (2), \"second category\" applies to a **nonempty open set**, not to an arbitrary set.", status: 'draft', basedOn: 'v0.9.3#6953ab13' } },
  "imp.fa-baire-opensubset": { note: { en: "The lecture notes only write \"$O_n' := O_n \\cup \\Omega^c$ is dense in $X$\"; what remains is this complement argument.", status: 'draft', basedOn: 'v0.9.3#806a657f' } },
  "imp.fa-ck-banach": { note: { en: "These three steps (pointwise limit $\\to$ uniform convergence $\\to$ preservation of continuity) are the universal template of the \"uniform convergence\" language.", status: 'draft', basedOn: 'v0.9.3#ec772252' } },
  "imp.fa-closedsubalg-sw": { note: { en: "⚠️ The lecture notes use two finite subcovers here ($U^c_{x,y}$ and $V_x^\\varepsilon$); the same logic is compressed here into \"push up first, then push down\".", status: 'draft', basedOn: 'v0.9.3#b883e9f7' } },
  "imp.fa-equi-uniform": { note: { en: "\"Finite\" is used twice: once for boundedness, and once to conclude that the minimum is still $>0$ — the infimum of infinitely many positive numbers can be 0, which is exactly where compactness is used.", status: 'draft', basedOn: 'v0.9.3#c4d27301' } },
  "imp.fa-findim-riesz": { note: { en: "Only \"finite dimension $\\implies$ equivalence of norms\" is needed; everything else is Heine–Borel.", status: 'draft', basedOn: 'v0.9.3#fa5c6b3f' } },
  "imp.fa-locallycompact-baire": { note: { en: "This corresponds verbatim to the proof for complete metrics, with the single replacement \"radius $\\to 0$\" $\\to$ \"finite intersection property of compact sets\". This also shows that Baire category does not depend on a metric at all.", status: 'draft', basedOn: 'v0.9.3#afb831f7' } },
  "imp.fa-openmap": { note: { en: "⚠️ Step ② is where it is easiest to skip (many notes write only \"Baire gives density, the rest is standard\"). The skeleton here also does not spell out the alignment of the constants verbatim — that is Rudin 2.11's treatment.", status: 'draft', basedOn: 'v0.9.3#38715048' } },
  "imp.fa-sw-complex": { note: { en: "The counterexample (the disk algebra $\\mathrm{Alg}(z)$) lacks precisely \"closed under conjugation\": if polynomials $p_n \\to \\bar z$ uniformly, then $\\int_{S^{1}} p_n(z)\\,z\\,dz = 0$ (Cauchy), but the limit gives $\\int_{S^{1}} \\bar z\\,z\\,dz = 2\\pi i \\ne 0$.", status: 'draft', basedOn: 'v0.9.3#7342ea70' } },
  "imp.fa-uniform-eq-pointwise": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering. The converse fails (see the counterexample in `def.uniformly-equicontinuous`); compactness is the tool that recovers the converse.", status: 'draft', basedOn: 'v0.9.3#f6335339' } },
  "imp.factor-theorem": { note: { en: "This proof has only one line of substance, but it yields a bonus: **the remainder is the value of the function** — this is also the bridge between a polynomial as a \"function\" and as a \"formal object\".", status: 'draft', basedOn: 'v0.9.3#7d155a59' } },
  "imp.fatou": { note: { en: "Fatou's lemma is what remains of the MCT when monotonicity is dropped: monotonicity is replaced by the liminf.", status: 'draft', basedOn: 'v0.9.3#ac2e19a3' } },
  "imp.fermat": { note: { en: "\"Interior point\" is used so that $h$ can take both signs: if $x_0$ is an endpoint, only a one-sided difference quotient makes sense, and the conclusion fails ($f(x) = x$ at an endpoint of $[0, 1]$).", status: 'draft', basedOn: 'v0.9.3#4fc0fec3' } },
  "imp.first-iso-vs": { note: { en: "The order of the four steps is worth remembering: **well defined first, then linear, then injective, then surjective**. Every proof that constructs a map after passing to a quotient has this skeleton — groups, rings, modules, and topological spaces with the quotient topology are all the same.", status: 'draft', basedOn: 'v0.9.3#f5294df4' } },
  "imp.flat-equivalences": { note: { en: "Item 4 is the only criterion that can really be computed by hand: there are fewer ideals than submodules, and the multiplication map $I \\otimes N \\to N$ can often be written explicitly.", status: 'draft', basedOn: 'v0.9.3#d3d591c7' } },
  "imp.flat-torsionfree": { note: { en: "Counterexample (over a general integral domain): in $R = k[x, y]$ the ideal $I = (x, y)$ is torsion-free but not flat — $x \\otimes y - y \\otimes x \\ne 0$ while its image is $xy - yx = 0$.", status: 'draft', basedOn: 'v0.9.3#3eb57aca' } },
  "imp.found-to-noself": { note: { en: "Applying the same argument to any finite $\\in$-cycle $A_{0} \\ni A_{1} \\ni \\cdots \\ni A_{n} = A_{0}$, and taking the set $\\{A_{0}$ …$A_{n-1}\\}$ (formed by repeated use of Pairing), also yields a contradiction.", status: 'draft', basedOn: 'v0.9.3#bf1abb09' } },
  "imp.free-flat": { note: { en: "This makes \"projective resolutions are also flat resolutions\" hold, so $\\operatorname{Tor}$ can be computed from a shorter flat resolution.", status: 'draft', basedOn: 'v0.9.3#d6f2d67e' } },
  "imp.ftc": { note: { en: "This theorem closes the whole \"bounded variation / absolute continuity\" cluster: it welds together the function side, the integral side and the derivative side.", status: 'draft', basedOn: 'v0.9.3#2d493739' } },
  "imp.ftc-part1": { note: { en: "The proof of (b) uses only continuity of $f$ at the **same point** — the values of the integral elsewhere play no role at all.", status: 'draft', basedOn: 'v0.9.3#be39adb0' } },
  "imp.ftc-part2": { note: { en: "The proof does not use the mean value theorem for integrals (that is **another** common proof); the point here is **telescoping**: the value taken by the derivative at the mean point connects all the increments. This also explains why $F'$ must be assumed integrable — otherwise the Riemann sums on the right have no limit.", status: 'draft', basedOn: 'v0.9.3#3b776b96' } },
  "imp.fundamental-algebra": { note: { en: "Where the analysis is used in the proof: step 1 (a continuous function on a compact set attains its minimum) and the $O(t^{k+1})$ estimate in step 2. Algebra handles only steps 4 and 5. This also explains why the theorem is neither purely algebraic nor as \"soft\" as a general analysis theorem.", status: 'draft', basedOn: 'v0.9.3#f3cdb916' } },
  "imp.gauss-egregium": { note: { en: "This edge connects two packages: the curvature-form route **does not need** coordinate computations with Christoffel symbols, only the first and second structure equations together with $\\omega^{3}=0$.", status: 'draft', basedOn: 'v0.9.3#c945e4f5' } },
  "imp.gleason": { note: { en: "The two directions use two faces of the **same projectivity**: one is \"glue the object back from its two pieces\" ($U \\sqcup F \\to S$ has a section), the other is \"every surjection has a section\".", status: 'draft', basedOn: 'v0.9.3#c245ff45' } },
  "imp.goursat-triangle-proof": { note: { en: "The bisection argument uses only \"$f$ is complex differentiable\" and does not require $f'$ to be continuous — precisely the improvement of Goursat over Cauchy.", status: 'draft', basedOn: 'v0.9.3#d8790581' } },
  "imp.gram-schmidt": { note: { en: "Step 1, \"eliminate one at a time\", is exactly subtracting from $v_j$ its component in each direction already constructed — the literal meaning of the word \"orthogonalization\". Step 2 uses linear independence to ensure that nothing collapses to zero.", status: 'draft', basedOn: 'v0.9.3#bad7bc39' } },
  "imp.h1-crossed": { note: { en: "The classification meaning of first cohomology is not added from outside; it is a direct consequence of writing out terms $1$ and $2$ of the standard complex.", status: 'draft', basedOn: 'v0.9.3#537223dd' } },
  "imp.heineborel-bounded": { note: { en: "The direction of this edge is \"general $\\implies$ special case\": the proposition is the version for compact metric spaces, and $[a, b]$ is one instance. It is marked on the graph because elementary calculus always uses this special case.", status: 'draft', basedOn: 'v0.9.3#c85b6420' } },
  "imp.hom-tensor-adjunction-mod": { note: { en: "Both sources are indispensable: `prop.module-tensor-universal` supplies the half \"bilinear = linear\" (stated over $\\mathbb{Z}$ and over fields), and `def.tensor-module` supplies the form of the balancing relation over a general $R$.", status: 'draft', basedOn: 'v0.9.3#2fdd1a2e' } },
  "imp.implicit-function": { note: { en: "⭐ There is **no new analytic technique anywhere in the proof** — everything is packaged in the construction of $\\Phi$. This is the exact meaning of \"the implicit function theorem is the inverse function theorem in disguise\": the same thing written differently, with the hypotheses translated accordingly ($D\\Phi$ invertible $\\iff$ $D_yF$ invertible).", status: 'draft', basedOn: 'v0.9.3#58eeab15' } },
  "imp.integrable-examples": { note: { en: "Item ① uses exactly \"continuous on a compact set $\\implies$ uniformly continuous\" — the only place outside ② where compactness is needed, while ② relies on **monotonicity** (the oscillation telescopes along the partition points automatically).", status: 'draft', basedOn: 'v0.9.3#5cb073b9' } },
  "imp.integral-linear": { note: { en: "\"Subadditivity of oscillation\" is the main engine of this whole package: every algebraic property of integrability (sum, scalar multiple, product, additivity over intervals) is a corollary of it.", status: 'draft', basedOn: 'v0.9.3#1c14b317' } },
  "imp.integral-order": { note: { en: "$\\omega(|f|) \\le \\omega(f)$ is proved piecewise: $\\sup |f| - \\inf |f| \\le \\sup f - \\inf f$ (the reverse triangle inequality).", status: 'draft', basedOn: 'v0.9.3#6c61d055' } },
  "imp.integral-test": { note: { en: "The left and right inequalities are two uses of the same monotonicity: on an interval the maximum of $f$ is at the left endpoint and the minimum at the right endpoint.", status: 'draft', basedOn: 'v0.9.3#c9537af7' } },
  "imp.inverse-function": { note: { en: "⭐ Step 2's reduction (turning $Df(a)$ into $I$) is where all the technique lies: **once the derivative is the identity, $x - f(x)$ becomes a contraction**, so \"solving the equation\" becomes \"finding a fixed point\". Step 6 then shows that \"the derivative of the inverse is the inverse of the derivative\" is a natural product of the definition, not an extra conclusion.", status: 'draft', basedOn: 'v0.9.3#6a6a305c' } },
  "imp.ivt": { note: { en: "In the proof $S$ is defined by \"$f \\le c$\" rather than \"$f < c$\": this lets step 2 use order-preservation directly, without first proving that the point attaining the supremum still lies in $S$.", status: 'draft', basedOn: 'v0.9.3#695a856c' } },
  "imp.jacobson": { note: { en: "The proof cites the same-layer fact \"a subquotient of a semisimple module is semisimple\"; the layer numbers are equal, so the layering check is explicitly switched off.", status: 'draft', basedOn: 'v0.9.3#1c9dcd51' } },
  "imp.jordan-canonical-form": { note: { en: "Step 2 (choosing bases layer by layer for a nilpotent operator) is the only **constructive** part of the theorem; the other two halves simply assemble known decompositions. This also explains why computing a Jordan form is essentially \"finding several kernel chains\".", status: 'draft', basedOn: 'v0.9.3#83d7430e' } },
  "imp.jordan-uniqueness": { note: { en: "The idea is to **first build an invariant, then show that it separates all classes** — the standard pattern of every classification theorem (exactly as in \"the cardinality of a basis is unique\").", status: 'draft', basedOn: 'v0.9.3#7c7ca412' } },
  "imp.kan-unifies": { note: { en: "After these two edges, the earlier definitions line up into a single thread: **limits and colimits are extensions \"along a functor to the terminal category\", and adjunctions are extensions \"along the identity functor\".**", status: 'draft', basedOn: 'v0.9.3#a61f0d99' } },
  "imp.kummer": { note: { en: "**Telescoping** is the common mechanism of this family of tests: $K_n$ is designed so that $c_n a_n - c_{n+1}a_{n+1}$ collapses into a telescoping sum. (Taking $c_n$ to be $1, n, n\\ln n$ yields d'Alembert, Raabe and Bertrand respectively.)", status: 'draft', basedOn: 'v0.9.3#82728a3b' } },
  "imp.lagrange": { note: { en: "⭐ The proof uses nothing about group structure except the two subgroup conditions $H$ is closed under multiplication and contains inverses. So Lagrange is a **purely counting** theorem.", status: 'draft', basedOn: 'v0.9.3#0de72e1d' } },
  "imp.lebesgue-set": { note: { en: "⭐ The step \"reduce the uncountable condition to a countable one\" is a typical move in countability arguments, in the same spirit as Borel–Cantelli.", status: 'draft', basedOn: 'v0.9.3#280d6051' } },
  "imp.lhopital": { note: { en: "Note that $\\xi$ in the proof **depends** on $x$ — but this does not prevent taking the limit, because as $x \\to x_0$, $\\xi$ is squeezed between $x_0$ and $x$ and hence also tends to $x_0$.", status: 'draft', basedOn: 'v0.9.3#84677bec' } },
  "imp.limit-arithmetic": { note: { en: "Why the order-preserving statement concludes $\\le$ rather than $<$, is clear from the last step of the proof: the contradiction argument rules out only $A > B$.", status: 'draft', basedOn: 'v0.9.3#bff54c35' } },
  "imp.linear-system-solutions": { note: { en: "The second paragraph is **pure set theory**: the solution set is one particular solution plus all homogeneous solutions. It holds for any group homomorphism and any ring homomorphism — \"inhomogeneous solution = particular solution + homogeneous solution\" is the general form of this trick.", status: 'draft', basedOn: 'v0.9.3#dcaa8c13' } },
  "imp.lusin": { note: { en: "The route is \"Egorov plus approximation by simple functions\".", status: 'draft', basedOn: 'v0.9.3#e172f30d' } },
  "imp.matrix-linear-map": { note: { en: "The \"well defined\" step uses **uniqueness of coordinates** (that is, the definition of a basis). This is precisely the foundation of the whole theorem — if the basis were not a basis, $T$ could not be defined this way.", status: 'draft', basedOn: 'v0.9.3#683c8c7d' } },
  "imp.matrix-ring": { note: { en: "Step 5, \"$c(AB) = A(cB)$\", is the only non-trivial item in the definition of a $K$-algebra — it says that a scalar can be pulled out of either factor.", status: 'draft', basedOn: 'v0.9.3#d5cf2e2f' } },
  "imp.maximal-prime": { note: { en: "This is a genuine implication; since $M$ is more special and its layer number is not lower than that of a prime ideal, it is marked `layer:false` under the layer-direction rule.", status: 'draft', basedOn: 'v0.9.3#4017f034' } },
  "imp.mct": { note: { en: "\"First push a simple function up against $f$ from below, then let the $E_{n}$ climb\" — the same pattern is used again in Fatou's lemma.", status: 'draft', basedOn: 'v0.9.3#aeec43d5' } },
  "imp.mean-value-integral": { note: { en: "Step 4 uses exactly the **intermediate value theorem** — the only place in the mean value family that needs \"$f$ takes all intermediate values\".", status: 'draft', basedOn: 'v0.9.3#01c9bc71' } },
  "imp.mean-value-multi": { note: { en: "⭐ The inequality form is the one actually used later: `thm.inverse-function` and `thm.inverse-function-banach` rely on it to make $\\Phi_y$ a contraction.", status: 'draft', basedOn: 'v0.9.3#36c748bf' } },
  "imp.metric-continuity-open-preimage": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering. The converse (topological continuity $\\implies$ $\\varepsilon$-$\\delta$ continuity) is just as direct: $B_Y(f(x_0), \\varepsilon)$ is open, and openness of its preimage supplies $\\delta$.", status: 'draft', basedOn: 'v0.9.3#5d155394' } },
  "imp.metric-pn": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.minimal-poly-divisor": { note: { en: "Steps 3 and 4 together form a **two-sided squeeze**: one must show that every root of $\\mu_T$ is an eigenvalue, and first prove that those kernels are nonzero — which looks obvious but is in fact a consequence of \"$\\mu_T(T) = 0$ while $T$ is non-trivial\".", status: 'draft', basedOn: 'v0.9.3#5dfd8c8f' } },
  "imp.minkowski": { note: { en: "⭐ Note the cancellation step: it is precisely $1/p + 1/q = 1$ that guarantees $p - p/q = 1$; otherwise a stubborn exponent would remain.", status: 'draft', basedOn: 'v0.9.3#5a8fde48' } },
  "imp.mixed-partials": { note: { en: "⚠ Continuity is used only in the last step (taking the limit). This also explains why dropping continuity allows counterexamples — the two intermediate points $(\\xi, \\eta)$ and $(\\xi', \\eta')$ **differ**, and without continuity one cannot bring values at two different points together.", status: 'draft', basedOn: 'v0.9.3#93c840c0' } },
  "imp.monotone-inverse": { note: { en: "The proof uses only \"strict monotonicity plus the intermediate value theorem\"; it does **not** use uniform continuity — continuity of the inverse follows from a hypothesis weaker than \"$f$ is uniformly continuous\".", status: 'draft', basedOn: 'v0.9.3#195a43c3' } },
  "imp.monotone-nested": { note: { en: "Note that step 3 uses the hypothesis \"lengths tend to zero\", while steps 4 and 5 use \"closed\".", status: 'draft', basedOn: 'v0.9.3#b5802220' } },
  "imp.morera": { note: { en: "Continuity is used only in the step \"limit of the difference quotient\" — exactly where Morera is weaker than Cauchy's theorem: it assumes the continuity needed for the conclusion, yet does not require differentiability in advance.", status: 'draft', basedOn: 'v0.9.3#a450bf41' } },
  "imp.mvt": { note: { en: "The device \"subtract the chord\" (find an auxiliary function satisfying Rolle's hypotheses) is standard throughout the mean value family; the Cauchy version below uses the same move.", status: 'draft', basedOn: 'v0.9.3#37d8bbf5' } },
  "imp.nested-bw": { note: { en: "In $\\mathbb{R}^{n}$ one applies the theorem coordinate by coordinate: the $i$-th coordinate of a bounded sequence is a bounded real sequence; first take a convergent subsequence, then pass to a subsequence for the next coordinate, and repeat $n$ times.", status: 'draft', basedOn: 'v0.9.3#88934b60' } },
  "imp.nilpotent-solvable": { note: { en: "$\\gamma_i \\subseteq G^{(i)}$ is the key: the lower central series is sandwiched between the derived series and $G$.", status: 'draft', basedOn: 'v0.9.3#3d7c9749' } },
  "imp.norm-equiv-finite-dim-proof": { note: { en: "Equivalence of norms in finite dimension is a basic result; the proof reduces it to compactness via Heine–Borel, so this edge does not participate in layering.", status: 'draft', basedOn: 'v0.9.3#209373c7' } },
  "imp.normal-completely-regular": { note: { en: "An inference \"strong $\\implies$ weak\": using a stronger separation axiom to prove a weaker one. If it participated in layering it would invert the layer numbers against the definition edge (regular L18 versus T3.5 L6). It is treated as a **corollary edge**: the implication is genuinely valid, but it is not the construction order.", status: 'draft', basedOn: 'v0.9.3#7cf9afc0' } },
  "imp.nt-lagrange-euler": { note: { en: "Only one step in this proof is group theory (Lagrange's theorem gives $|H|\\mid|G|$); the rest is a translation into congruence language. Writing $H=\\langle[a]\\rangle$ explicitly merely turns this step into the form of a subgroup.", status: 'draft', basedOn: 'v0.9.3#db49dcf0' } },
  "imp.operator-algebra-proof": { note: { en: "The complete proof is on this edge; the node's notes retain only the motivation and the gaps.", status: 'draft', basedOn: 'v0.9.3#01128554' } },
  "imp.ordinal-trichotomy": { note: { en: "② is the whole key: \"between ordinals, $\\subset$ is $\\in$\". It reduces comparison of ordinals to membership between sets.", status: 'draft', basedOn: 'v0.9.3#4839a922' } },
  "imp.pcp-metric-metrizable": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.pn-cn": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.polarization-proof": { note: { en: "The complete proof is on this edge; the node's notes retain only the motivation and the gaps.", status: 'draft', basedOn: 'v0.9.3#01128554' } },
  "imp.poly-ufd": { note: { en: "Of the four steps, **only the second uses something special about a field** (essentially the Bézout identity supplied by division with remainder); the other three hold in any integral domain. This is also the standard proof of the chain \"Euclidean domain $\\implies$ UFD\".", status: 'draft', basedOn: 'v0.9.3#98d4544d' } },
  "imp.power-series-analytic": { note: { en: "Step 2 is the key to the whole theorem: **differentiation does not change the radius of convergence**. If the radius shrank, repeated differentiation would eat up the domain of convergence, and the $C^{\\infty}$ conclusion would be out of reach.", status: 'draft', basedOn: 'v0.9.3#a5f33dd4' } },
  "imp.primary-decomposition": { note: { en: "Step 1 (turning $V$ into a $K[x]$-module) is the hinge of the whole chain: once it is a module, \"split according to irreducible factors\" is supplied automatically by **$K[x]$ being a UFD together with Bézout**, with no need to improvise inside the vector space.", status: 'draft', basedOn: 'v0.9.3#8f0dab0e' } },
  "imp.product": { note: { en: "This proof shows a standard pattern: first use the power set to build a container large enough, then use the Separation schema to sift out exactly what is wanted.", status: 'draft', basedOn: 'v0.9.3#5895cb5d' } },
  "imp.product-incomplete": { note: { en: "⚠ Only a skeleton is given here for the step \"$G \\notin \\mathfrak{B} \\otimes \\mathfrak{B}$\" (how to recover $N$ from a section); for a rigorous version the recommended route is \"diagonal argument plus Fubini's theorem to derive a contradiction\".", status: 'draft', basedOn: 'v0.9.3#58f546dc' } },
  "imp.projection-formula": { note: { en: "The two facts \"$v - P_Uv \\perp U$\" and \"$P_Uv - u' \\in U$\" are the entire reason Pythagoras applies — and also what makes orthogonal projection better than a general projection.", status: 'draft', basedOn: 'v0.9.3#348ad75e' } },
  "imp.quotient-universal-vs": { note: { en: "Uniqueness uses only one fact: **$\\pi$ is surjective** (so every coset has a representative available). This is the common way of finishing a theorem of \"universal property\" type.", status: 'draft', basedOn: 'v0.9.3#2fa61c6b' } },
  "imp.rank-nullity": { note: { en: "The \"independence\" half in step 2 is the one most easily missed: **carrying independence from a basis of $V$ to the image** uses the fact that a basis of $\\ker T$ has already been listed separately as part of the basis.", status: 'draft', basedOn: 'v0.9.3#586ba749' } },
  "imp.rank-row-col": { note: { en: "This proof reduces \"row rank = column rank\" to the dimension formula for annihilators in the duality section — that is, **transposition does not change rank**, and that is a joint consequence of annihilators and rank-nullity.", status: 'draft', basedOn: 'v0.9.3#ed710f30' } },
  "imp.rank-theorem": { note: { en: "⚠ Step 3 uses \"connected neighbourhood + zero derivative $\\implies$ constant\"; here one may take a ball neighbourhood (convex and connected) to avoid the discussion. ⭐ The whole proof is **three changes of coordinates**: turn $f'$ into coordinates, express $\\widehat f$ as independent of $y''$, and straighten $h$.", status: 'draft', basedOn: 'v0.9.3#b15514fd' } },
  "imp.rearrangement": { note: { en: "Step 2, \"apply the same argument once more to $\\sigma^{-1}$\", is the key trick: the sum of a nonnegative series is defined as a supremum, and the phrase \"finite part\" makes sense in both directions.", status: 'draft', basedOn: 'v0.9.3#efdf10e2' } },
  "imp.recursion-wellorder": { note: { en: "① is uniqueness; ② and ③ are existence. The proof uses **only** well-ordering, the Replacement schema and the Separation schema — neither the Axiom of Choice nor the Power Set axiom. ② remains valid even when $G$ is a **proper-class function**: collecting $y = G(f)$ uses the Replacement schema, not \"the power set of the union of the range of $G$\" — a proper-class function has no such range.", status: 'draft', basedOn: 'v0.9.3#8b157c34' } },
  "imp.regular-value": { note: { en: "⭐ Here \"submanifold\" is defined operationally as \"locally the graph of a $C^{1}$ function\" — the theorem incidentally shows that several conditions are equivalent: locally a graph, locally defined by independent equations, locally homeomorphic to an open ball. ⚠ The $C^{1}$ in the conclusion uses only $f \\in C^{1}$; for a \"smooth submanifold\" one raises $f$ to $C^{\\infty}$.", status: 'draft', basedOn: 'v0.9.3#4e5fa60a' } },
  "imp.repl-to-sep": { note: { en: "In ZF, Replacement together with the existence of one set already suffices; textbooks keep Separation because it makes statements and proofs convenient.", status: 'draft', basedOn: 'v0.9.3#c2662615' } },
  "imp.riemann-criterion": { note: { en: "The practical value of the criterion lies entirely in the weak requirement \"there exists a partition\" — to prove integrability one need only **construct one** good partition, not face all partitions.", status: 'draft', basedOn: 'v0.9.3#ee5bcf75' } },
  "imp.right-adjoint-limits": { note: { en: "The proof uses only two things: **the adjunction isomorphism** and **the universal property of limits**. That is why this theorem needs almost no extra hypotheses.", status: 'draft', basedOn: 'v0.9.3#74a7d633' } },
  "imp.ring-bezout-gcd": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.ring-euclid-pid": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.ring-pid-ufd": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.ring-ufd-gcd": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.rolle": { note: { en: "Step 3 is the entire trick: \"equal values at the two ends\" ensures that the extreme value cannot be attained at both endpoints, so one extreme value is attained at an interior point — compactness (supplied by the extreme value theorem) and differentiability (used by Fermat's lemma) meet exactly here.", status: 'draft', basedOn: 'v0.9.3#abcce672' } },
  "imp.root-bound": { note: { en: "Careful with the induction: **multiplicities are divided out one step at a time**, rather than first taking distinct roots and then counting degrees — the latter would miss the case where the same root occurs several times.", status: 'draft', basedOn: 'v0.9.3#b18bda39' } },
  "imp.root-test": { note: { en: "The branch $\\alpha > 1$ does not actually need the comparison test — it uses only the necessary condition \"the general term must tend to zero\".", status: 'draft', basedOn: 'v0.9.3#a0d46e7f' } },
  "imp.rouche": { note: { en: "The proof uses only one thing: the number of zeros varies continuously with the parameter and can take only integer values. Thus, apart from \"$|g| < |f|$ keeps the denominator nonzero\", there is no quantitative estimate at all.", status: 'draft', basedOn: 'v0.9.3#3c6e02d2' } },
  "imp.saft": { note: { en: "This theorem is the watershed of the first half of the picture: **from the checkable condition \"preserves limits\" it directly constructs a left adjoint**. The price is requiring $\\mathcal{D}$ to be small and complete (otherwise that limit need not exist).", status: 'draft', basedOn: 'v0.9.3#6216d6fd' } },
  "imp.schwarz": { note: { en: "The point is that \"when $f(0) = 0$, the quotient $f/z$ is still holomorphic\" — this relies entirely on the removable-singularity side: the Taylor expansion of $f$ starts at $z^1$, and after dividing by $z$ it is still a power series.", status: 'draft', basedOn: 'v0.9.3#f85bcd53' } },
  "imp.sep-to-empty": { note: { en: "Strictly speaking, \"the domain is nonempty\" is a convention of first-order logic, not an axiom of ZF. If one dislikes the convention, one can first extract a set from the Axiom of Infinity and then apply Separation.", status: 'draft', basedOn: 'v0.9.3#38a73e08' } },
  "imp.seqcompact-complete": { note: { en: "This is the same argument as for \"compact $\\implies$ complete\", with compactness replaced by its immediate consequence, sequential compactness.", status: 'draft', basedOn: 'v0.9.3#8c8bd62c' } },
  "imp.series-cauchy": { note: { en: "The **only** external input in this criterion is completeness of the reals — in other words, testing convergence of series is essentially using the fact that $\\mathbb{R}$ has no holes.", status: 'draft', basedOn: 'v0.9.3#5cc524f1' } },
  "imp.skyscraper-injective": { note: { en: "Injectivity in a category of sheaves can be checked \"pointwise\": this edge uses only the stalk adjunction and exactness.", status: 'draft', basedOn: 'v0.9.3#4d0a1aef' } },
  "imp.skyscraper-stalks": { note: { en: "The \"skyline\" stands only on a closed set: over a $T_{1}$ space it is a single point, while over a general space it may be an entire closed set.", status: 'draft', basedOn: 'v0.9.3#5d60be5c' } },
  "imp.smith-normal-form": { note: { en: "The key step is to choose, in the equivalence class, a matrix whose $(1,1)$ ideal is maximal; the Noetherian property of a PID guarantees that such a matrix exists.", status: 'draft', basedOn: 'v0.9.3#1738dfc9' } },
  "imp.sn-solvable": { note: { en: "⭐ The key is to turn \"$A_5$ is simple\" into a finite computation that can be checked item by item: the conjugacy class sizes are only $1, 15, 20, 12, 12$; a normal subgroup is a union of classes and its order divides $60$ — enumerating $2^{4} = 16$ combinations leaves only $1$ and $60$ feasible.\n\nThis is far more reliable than arguing simplicity abstractly, and it avoids the heavier task of proving that $A_n$ ($n \\ge 5$) is simple: to see that $S_n$ is not solvable one needs only $A_5$.\n\n⚠ Step 4 uses a small fact: $A_5 \\le A_n$ ($n \\ge 5$) — fix the last $n-5$ points and permute the first $5$ evenly.\n\nIt is a subgroup of $A_n$, and solvability passes to subgroups (part (a) of `thm.solvable-quotients`).", status: 'draft', basedOn: 'v0.9.3#027e1b88' } },
  "imp.solvable-quotients": { note: { en: "⭐ All three proofs use only \"$H \\le G \\implies H^{(k)} \\le G^{(k)}$\" and \"a surjective homomorphism carries the derived series to the derived series\" — the derived series is **functorial**, which is why solvability behaves so well.", status: 'draft', basedOn: 'v0.9.3#ad7b165d' } },
  "imp.spectral-normal": { note: { en: "Step 2, \"normal $\\iff$ $AB$ commute\", is the heart of the corollary: **a complex normal operator is a pair of commuting self-adjoint operators**, so the problem reduces to the real spectral theorem.", status: 'draft', basedOn: 'v0.9.3#9789bf3c' } },
  "imp.spectral-theorem": { note: { en: "Step 1 is the **analytic input** (a continuous function on a compact set attains its extreme values); step 2 is the only place where **self-adjointness** is used. This also explains why the real case must require symmetry: without self-adjointness, $U^{\\perp}$ need not be invariant, and the induction breaks.", status: 'draft', basedOn: 'v0.9.3#a27d30f8' } },
  "imp.squeeze": { note: { en: "The squeeze theorem has no \"existence\" content at all: its two hypotheses already supply the limit $L$, so the definition suffices — which is also why it holds in any completion of the reals.", status: 'draft', basedOn: 'v0.9.3#aee353c6' } },
  "imp.steinitz": { note: { en: "The entire trick of the exchange lemma is in step 2: **replace one vector in the spanning set by one from the independent set without losing the spanning property**. Being able to repeat this is exactly where \"independent vectors can be inserted into a spanning set\" comes from.", status: 'draft', basedOn: 'v0.9.3#6f41117e' } },
  "imp.stone-cech": { note: { en: "There are only two key points: **Tychonoff's theorem** supplies compactness, and the **$T_{3.5}$ property** guarantees that $e_{K}$ is injective (otherwise the step \"falling back into $K$\" would be meaningless).", status: 'draft', basedOn: 'v0.9.3#a20940d3' } },
  "imp.subalgebra-lattice-proof": { note: { en: "The complete proof is on this edge; the node's notes retain only the motivation and the gaps.", status: 'draft', basedOn: 'v0.9.3#01128554' } },
  "imp.subspace-criterion": { note: { en: "Step 3 is the whole content of \"the span equals the set of all finite combinations\": **\"smallest\" and \"finite combinations\" describe the same thing**, one from above (taking intersections) and one from below (constructing).", status: 'draft', basedOn: 'v0.9.3#37d5b0bc' } },
  "imp.substitution": { note: { en: "Both directions of change of variable (\"absorbing the differential\" and \"substituting the variable\") live in this one formula, since the two sides can be read either way: reading from left to right is substitution, from right to left is replacement.", status: 'draft', basedOn: 'v0.9.3#3e89514c' } },
  "imp.sup-monotone": { note: { en: "This step is the **only entrance** to the whole chain of equivalences: the next five all start from it, and finally return to it (see \"six equivalent forms of completeness\").", status: 'draft', basedOn: 'v0.9.3#2ce1fc89' } },
  "imp.svd": { note: { en: "There is only one key observation: **$A^{\\mathsf{T}}A$ is positive semidefinite** — so the spectral theorem gives an orthonormal eigenbasis, and $A$ sends that basis to an orthogonal set (up to the scalings $\\sigma_i$). The whole content of the SVD is this observation written in coordinates.", status: 'draft', basedOn: 'v0.9.3#f59c5042' } },
  "imp.taylor": { note: { en: "The step \"$\\Phi^{(n+1)}$ has a zero\" uses Rolle's theorem in iterated form: if a function has $m$ zeros, its derivative has one zero between each pair of adjacent zeros — each iteration lowers the count by one.", status: 'draft', basedOn: 'v0.9.3#638e873d' } },
  "imp.taylor-multi": { note: { en: "⭐ The key is step 3: **between a $j$-linear form and a multi-index derivative there is a combinatorial factor $j!/\\alpha!$** — precisely the bridge that translates \"$D^{j}f$ is a multilinear form\" into \"$\\sum_{|\\alpha|\\le k}\\frac{D^{\\alpha}f}{\\alpha!}h^{\\alpha}$\".", status: 'draft', basedOn: 'v0.9.3#ff1e9fad' } },
  "imp.tensor-functor-properties": { note: { en: "Combining \"commutes with direct sums\" with \"unit\" yields the sentence used repeatedly later: $(-) \\otimes_{R} N$ preserves colimits.", status: 'draft', basedOn: 'v0.9.3#ed8dc395' } },
  "imp.tensor-hom-adjunction": { note: { en: "The proof never uses finite-dimensionality of $V$ (this is a purely categorical fact); it uses only the universal property of the tensor product.", status: 'draft', basedOn: 'v0.9.3#99984f73' } },
  "imp.tensor-right-exact": { note: { en: "This edge splits \"right exact\" from \"flat\": right exactness comes for free from the adjunction, while left exactness is the property that must be studied.", status: 'draft', basedOn: 'v0.9.3#477be5f6' } },
  "imp.tensor-universal-property": { note: { en: "The final word \"natural\" is the doorway to **adjunction**: precisely because the isomorphism is natural in $U$ (as well as in $V, W$), the tensor product is a genuine construction at the level of functors, not merely \"some particular quotient space\".", status: 'draft', basedOn: 'v0.9.3#9111e6c1' } },
  "imp.triangle-rotation": { note: { en: "The pattern of the proof is fixed: **first arrange the triangle into the shape of a mapping cone, then compute with matrices**. Every theorem about triangles in the homotopy category comes about this way.", status: 'draft', basedOn: 'v0.9.3#9a27ab4b' } },
  "imp.trig-series-radius": { note: { en: "Only coefficient estimates are needed here, not complex function theory; hence $\\cos$ and $\\sin$ are entire functions.", status: 'draft', basedOn: 'v0.9.3#edeaf55e' } },
  "imp.tu-surface-riemannian": { note: { en: "The source is a special case or a stronger condition, while the target is an independent general definition; this edge records logical inclusion only and does not affect layering.", status: 'draft', basedOn: 'v0.9.3#32940b3e' } },
  "imp.uniform-compact": { note: { en: "The skeleton of this proof is \"translate failure of uniformity into two sequences of points\", exactly the form compactness handles best — the same pattern recurs in \"a continuous function on a compact set attains its extreme values\" and in \"compact operators\".", status: 'draft', basedOn: 'v0.9.3#748c2c76' } },
  "imp.uniform-limit-continuous": { note: { en: "The reason step 1 can use a single $n$ to control both $x$ and $x_0$ is the entire content of **uniform** convergence — with pointwise convergence, step 1 would produce two different $n$ and the proof would break immediately.", status: 'draft', basedOn: 'v0.9.3#ab763aac' } },
  "imp.uniform-limit-derivative": { note: { en: "Step 1 is the key preparation: **assuming $f_n'$ converges uniformly gives uniform convergence of $f_n$ for free**. This also explains why this theorem is \"more expensive\" than the integral version — one extra convergence point $x_0$ is needed to pin down the free constant.", status: 'draft', basedOn: 'v0.9.3#74f5e25c' } },
  "imp.yoneda-embedding": { note: { en: "Both conclusions come from one source: **an arrow from $h_{X}$ to somewhere is an element at $X$**.", status: 'draft', basedOn: 'v0.9.3#0659b11a' } },
  "imp.zero-point": { note: { en: "The step \"attained strictly between the endpoints\" is precisely the extra content that the zero-point theorem has over the intermediate value theorem.", status: 'draft', basedOn: 'v0.9.3#c9121369' } },
  "imp.zorn-choice": { note: { en: "\"Take a maximal element under inclusion, then show it cannot grow any further\" — this is the standard way of producing existence objects with Zorn's lemma.", status: 'draft', basedOn: 'v0.9.3#b629f94d' } },
  "imp.zorn-to-basis": { note: { en: "The same pattern proves that every ring has a maximal ideal, that over every field every module has a maximal linearly independent set, and that every partially ordered set has a maximal antichain.", status: 'draft', basedOn: 'v0.9.3#be80cad4' } },
  "dep.topology-closed": { note: { en: "A closed set is defined as the complement of an **open set**; the properties of closed sets are obtained by translating those of open sets through De Morgan’s laws.", status: 'draft', basedOn: 'v0.9.3#4edb9235' } },
  "imp.inverse-function-banach": { note: { en: "⭐ The difference between finite and infinite dimensions comes down to one sentence. **In finite dimensions, invertibility and topological invertibility coincide. In infinite dimensions, they can differ.** This dependency edge records that distinction in the graph.", status: 'draft', basedOn: "v0.9.3#7e14aac8" } },
  "imp.lambek": { note: { en: "Reducing “all ideals” to “finitely generated ideals” is a substantial simplification. The former collection is often enormous, while the latter can be countable or even finite in familiar rings. ⚠️ Reducing further to principal ideals gives only torsion-freeness.", status: 'draft', basedOn: "v0.9.3#2d2ebcd7" } },
  "imp.injective-splitting": { note: { en: "Corollary. An injective module cannot occur as a **proper** submodule of any module. The route through a “larger module” is closed to $I$, which is where the term “injective” comes from.", status: 'draft', basedOn: "v0.9.3#6646dbc9" } },
  "imp.baer-criterion": { note: { en: "The entire proof uses only the fact that $R$ is a ring and Zorn’s lemma, with no smallness or finiteness assumptions. It therefore holds for **every** ring, which makes it more robust than Lambek’s criterion for flatness.", status: 'draft', basedOn: "v0.9.3#018a135c" } },
  "dep.mf-bundlemetric-pu": { note: { en: "Take a convex combination of the local inner products, using the smooth partition of unity as weights. Positive definiteness follows because the weights are nonnegative and sum to $1$.", status: 'draft', basedOn: "v0.9.3#40f09445" } },
  "dep.spivak-partition-changevars": { note: { en: "A partition of unity subordinate to an orientation-preserving atlas breaks the integral over the manifold into chartwise $\\mathbb{R}^{n}$ integrals. Without it, the theorem can only be stated chart by chart, with no way to assemble a global formula.", status: 'draft', basedOn: "v0.9.3#d9082757" } },
  "imp.derived-lagrange-from-sylow": { note: { en: "This argument uses only parts (1) and (2) of Sylow’s theorem and skips the counting in (3). It also explains why the converse of Lagrange’s theorem cannot be obtained by reversing the argument. Divisibility gives only a necessary condition, and Sylow supplies the $p$-part.", status: 'draft', basedOn: "v0.9.3#2d2042ab" } },
  "imp.derived-h0-from-de-rham": { note: { en: "There is no formal computation here. The entire conclusion for $H^{0}$ comes from de Rham’s theorem, and the Poincaré lemma machinery is needed only for $k \\ge 1$. ⚠ The proof of this edge is conditional on `thm.de-rham` (which is still a skeleton, `thm.de-rham`).", status: 'draft', basedOn: "v0.9.3#90455a0f" } },
  "e14.implication": { note: { en: "The open mapping property means that a nonconstant holomorphic function cannot flatten an open set.", status: 'draft', basedOn: "v0.9.3#1be0b40a" } },
  "e17.implication": { note: { en: "The node statement makes the distinction explicit. The continuous version requires the fundamental group, while complex analysis alone gives only the holomorphic version.", status: 'draft', basedOn: "v0.9.3#e929bd79" } },
  "e18.implication": { note: { en: "Borsuk–Ulam and Brouwer are two sides of the same coin. This argument uses degree.", status: 'draft', basedOn: "v0.9.3#29fa97d1" } },
  "e21.implication": { note: { en: "Pink edge. The implication is valid, although the reverse direction is more natural, so this serves only as a supplementary connection.", status: 'draft', basedOn: "v0.9.3#33f6ccd4" } },
  "imp.runge": { note: { en: "Runge’s theorem, the Mittag-Leffler theorem, and Weierstrass products are closely related in spirit. They concern approximation, constructing principal parts, and prescribing zeros, respectively. This analogy gives no theorem dependency, so Mittag-Leffler is omitted from sources.", status: 'draft', basedOn: "v0.9.3#fccb3511" } },
  "e28.implication": { note: { en: "Weierstrass products allow the zeros to be prescribed arbitrarily. The remaining freedom is exactly $e^{g}$.", status: 'draft', basedOn: "v0.9.3#bd88e137" } },
  "e30.implication": { note: { en: "The proof covers only the finite-order case. As noted, the general case requires Bloch’s theorem or modular functions.", status: 'draft', basedOn: "v0.9.3#456750d0" } },
  "imp.lebesgue-differentiation": { note: { en: "⭐ This is one of the most elegant standard arguments in analysis. **Use the density of continuous functions to reduce to a well-behaved case, then use the maximal inequality to control the error.** Together these steps force the exceptional set to have measure zero.", status: 'draft', basedOn: "v0.9.3#160dd294" } },
  "imp.dct-average-continuous": { note: { en: "Everything apart from this step consists of elementary estimates involving balls and indicator functions: splitting terms, establishing a.e. convergence, and finding a dominating function. **The DCT is the only external theorem**, and it resolves the lack of pointwise information in $L^1_{loc}$ in one step.", status: 'draft', basedOn: "v0.9.3#dae948de" } },
  "e61.implication": { note: { en: "⚠️ This gives only a bijection of **sets**. To call it an isomorphism, one must separately prove the degree homomorphism property.", status: 'draft', basedOn: "v0.9.3#d39ba9f1" } },
  "e65.implication": { note: { en: "This edge fills a gap in the graph. The existing proof of `thm.brouwer-fixed-point` uses Rouché’s theorem to establish only the **holomorphic** case and labels the continuous case as an external input. The two-dimensional continuous case now has its own proof in the graph.", status: 'draft', basedOn: "v0.9.3#e2c5c33b" } },
  "e86.implication": { note: { en: "The definition of a relative cycle ensures precisely that $\\partial c$ lands in $S_{p-1}(A)$. This is what forces the connecting homomorphism.", status: 'draft', basedOn: "v0.9.3#665925ff" } },
  "e88.implication": { note: { en: "⭐ The second step is where all the difficulty lies. Without subdivision, there is no bridge between “locally in $U$ or $V$” and “globally homologous.”", status: 'draft', basedOn: "v0.9.3#ad1fd93e" } },
  "e89.implication": { note: { en: "This chain uses homotopy invariance, stated in `def.singular-homology`, and the Mayer–Vietoris proof skeleton. Both are explicitly noted.", status: 'draft', basedOn: "v0.9.3#296eaf82" } },
  "e92.implication": { note: { en: "Without this result, $\\chi$ would merely be the result of counting simplices in a particular triangulation, and a different triangulation might give a different value.", status: 'draft', basedOn: "v0.9.3#b0d46578" } },
  "dep.qr-gs": { note: { en: "QR decomposition is Gram–Schmidt in matrix form. This step is all there is to understanding QR.", status: 'draft', basedOn: "v0.9.3#1ae7eb2e" } },
  "imp.lu-decomposition-proof": { note: { en: "The full proof is on this edge. The node note retains only the motivation and the gap.", status: 'draft', basedOn: "v0.9.3#01128554" } },
  "imp.darboux": { note: { en: "The proof, including the linear algebra step involving a symplectic basis, is in the node’s notes. This edge records only two external dependencies: the Poincaré lemma on a contractible chart and the local flow of a time-dependent vector field. `thm.symplectic-normal-form` provides only an outline of the linear version and is excluded from the dependencies.", status: 'draft', basedOn: "v0.9.3#c5587286" } },
  "imp.riesz-lp-pink": { note: { en: "This is a corollary going back from the framework to the example (bundled, with no independent proof), and it does not affect layering. The target theorem is the $L^{p}$ special case of (c). The proof of (c) uses only the Radon–Nikodym theorem and does not depend on the target theorem.", status: 'draft', basedOn: "v0.9.3#2469e43c" } },
  "dep.eulerchar-classification": { note: { en: "To distinguish nonhomeomorphic surfaces, use $\\chi$ as an invariant ($\\chi$ is invariant under homeomorphism). This edge relies on a **theorem**: `thm.euler-characteristic` equates the simplex count with the Betti-number count, giving both combinatorial and homological ways to compute $\\chi$.", status: 'draft', basedOn: "v0.9.3#6692216d" } },
  "dep.eulerchar-eulerchargenus": { note: { en: "The theorem says precisely that the two ways of computing $\\chi$ (counting simplices / counting Betti numbers) agree.", status: 'draft', basedOn: "v0.9.3#a77e96cb" } },
  "dep.eulerchar-eulercharnonor": { note: { en: "The combinatorial computation of $\\chi$ ($V - E + F$) is the other half of this argument.", status: 'draft', basedOn: "v0.9.3#fe39eb92" } },
  "imp.eulerchar-inputs": { note: { en: "⚠ This edge records dependencies and carries no logical implication. It registers the three external inputs used in the proof so readers can see which missing input would prevent the proposition from following.", status: 'draft', basedOn: "v0.9.3#d2a1dacc" } },
  "dep.solvablequotients-radical": { note: { en: "Both directions require solvability to be closed under quotients or subgroups, respectively. The quotient group at each step of the series is solvable $\\iff$ the whole group is solvable.", status: 'draft', basedOn: "v0.9.3#24c6d846" } },
  "imp.pcpu-urysohn": { note: { en: "Urysohn’s lemma is used to construct each individual $g_{i}$. The refinement itself ensures that normalization by the sum works and that the family is locally finite.", status: 'draft', basedOn: "v0.9.3#80c8a6a3" } },
  "def-dep.exacttopo-abtopabcond": { note: { en: "The left-exactness step relies entirely on the fact that $\\mathbf{AbTop} \\to \\mathrm{AbCond}$ preserves all limits.", status: 'draft', basedOn: "v0.9.3#0a0f98fb" } },
  "dep.dualspace-dualbasis": { note: { en: "The dual basis is the set of elements of the dual space **designated** by the original basis (defined by $\\delta_{ij}$).", status: 'draft', basedOn: "v0.9.3#8fede847" } },
  "dep.sym-product-def-rel": { note: { en: "A relation is defined as a subset of a Cartesian product, so it presupposes the binary product", status: 'draft', basedOn: "v0.9.3#54c1de80" } },
  "eq.ac-wo": { note: { en: "This is the starting point of the most important chain of equivalences in the entire galaxy map. AC supplies a way to choose, and a well-order supplies a least element. They are two sides of the same coin.", status: 'draft', basedOn: "v0.9.3#64d65d28" } },
  "eq.hausdorff-tukey": { note: { en: "This pair of proofs is typical. Once we see that the concept of a chain itself has finite character, we can trade the Hausdorff principle for Tukey's lemma, which is easier to apply.", status: 'draft', basedOn: "v0.9.3#907c766e" } },
  "eq.compact-seqcompact": { note: { en: "In a metric space, every open cover having a finite subcover and every sequence having a convergent subsequence are equivalent. The two directions are proved separately and together establish the equivalence.", status: 'draft', basedOn: "v0.9.3#180e0835" } },
  "def-link.compact-theorem": { note: { en: "The statement of the three equivalent characterizations of compactness uses the definition of compactness.", status: 'draft', basedOn: "v0.9.3#7c07a3b3" } },
  "def-link.seqcompact-theorem": { note: { en: "As above, this uses sequential compactness.", status: 'draft', basedOn: "v0.9.3#c28d1cce" } },
  "def-link.complete-theorem": { note: { en: "As above, this uses completeness.", status: 'draft', basedOn: "v0.9.3#bad2d53d" } },
  "def-link.compact-closed": { note: { en: "The proposition that compact subsets are closed uses the definition of compactness.", status: 'draft', basedOn: "v0.9.3#f6087e22" } },
  "def-link.compact-subset-equiv": { note: { en: "The characterization of compactness for subsets uses the definition of compactness.", status: 'draft', basedOn: "v0.9.3#1e24cd8f" } },
  "def-link.complete-subset-equiv": { note: { en: "⚠ The **hypothesis** of this proposition is that $X$ is complete, so it invokes the definition of completeness.", status: 'draft', basedOn: "v0.9.3#f6e905e6" } },
  "def-link.mc-metric": { note: { en: "Continuity is expressed using $d$ and $\\rho$ of the two metric spaces.", status: 'draft', basedOn: "v0.9.3#2fb61886" } },
  "def-link.sigmaalgebra-ringmonotone": { note: { en: "The criterion concludes that $\\mathfrak{A}$ is a $\\sigma$-ring. If $\\mathfrak{A}$ also contains $X$, it is a $\\sigma$-algebra as well.", status: 'draft', basedOn: "v0.9.3#fb4ed53e" } },
  "def-link.sigmaalgebra-monotonethm": { note: { en: "Starting from $\\mathcal{E}$, the monotone class theorem has on one side the $\\sigma$-algebra $\\mathcal{M}(\\mathcal{E})$ it generates, and on the other the monotone class $\\mathfrak{m}(\\mathcal{E})$.", status: 'draft', basedOn: "v0.9.3#d2cc579a" } },
  "def-link.sigmaalgebra-borel": { note: { en: "The $Borel \\sigma$-algebra is the $\\sigma$-algebra generated by the open sets.", status: 'draft', basedOn: "v0.9.3#1ee11453" } },
  "def-link.sigmaalgebra-product": { note: { en: "The product $\\sigma$-algebra is simply a $\\sigma$-algebra with rectangles as the generators.", status: 'draft', basedOn: "v0.9.3#84d08c74" } },
  "def-link.premeasure-outer": { note: { en: "The formula for the induced outer measure uses the premeasure.", status: 'draft', basedOn: "v0.9.3#dbcff605" } },
  "def-link.outer-carath-thm": { note: { en: "Carathéodory's theorem starts from an outer measure.", status: 'draft', basedOn: "v0.9.3#4a005b56" } },
  "def-link.carathmeasurable-thm": { note: { en: "In the theorem, $\\mathcal{M}$ is the collection of all $\\mu^{*}$-measurable sets.", status: 'draft', basedOn: "v0.9.3#4584fbfc" } },
  "def-link.measure-completion": { note: { en: "The construction of the completion depends entirely on the measure and its null sets.", status: 'draft', basedOn: "v0.9.3#c4ce7538" } },
  "def-link.borel-ls": { note: { en: "The theorem concludes that the measure is a Borel measure.", status: 'draft', basedOn: "v0.9.3#8d903c95" } },
  "def-link.null-completion": { note: { en: "The definition in the completion theorem uses null sets throughout.", status: 'draft', basedOn: "v0.9.3#7691e99c" } },
  "def-link.measure-basic-props": { note: { en: "These properties are all direct consequences of the defining property of a measure, countable additivity.", status: 'draft', basedOn: "v0.9.3#74dde356" } },
  "def-link.lplus-simple-approx": { note: { en: "The approximation theorem concludes that a measurable function is the limit of a sequence of simple functions.", status: 'draft', basedOn: "v0.9.3#dfbd5140" } },
  "def-link.measurable-simple": { note: { en: "The definition of a simple function includes measurability.", status: 'draft', basedOn: "v0.9.3#19b9f3af" } },
  "def-link.lebesgue-measurable-def": { note: { en: "Lebesgue and Borel measurability just specialize $(\\mathcal{M}, \\mathcal{N})$ to two specific pairs.", status: 'draft', basedOn: "v0.9.3#f8569b3a" } },
  "def-link.borel-lebesgue-measurable": { note: { en: "Borel measurability uses $\\mathfrak{B}_\\mathbb{R}$ and $\\mathfrak{B}_\\mathbb{C}$.", status: 'draft', basedOn: "v0.9.3#fd037143" } },
  "dep.sym-complex-def-lebesgue-measurable": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.sym-complex-def-simple-function": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.sym-complex-thm-simple-approximation": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.sym-real-def-lebesgue-measurable": { note: { en: "The statement concerns the real numbers $\\mathbb{R}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#0453d27b" } },
  "dep.continuousmeasurable-borel": { note: { en: "Continuous maps are measurable with respect to the Borel σ-algebras", status: 'draft', basedOn: "v0.9.3#000e822e" } },
  "def-link.simple-integral-def": { note: { en: "The integral of a simple function is computed as a weighted sum using its defining representation.", status: 'draft', basedOn: "v0.9.3#d0d621e7" } },
  "def-link.nonneg-simple": { note: { en: "The integral of a nonnegative function is defined as the supremum of a family of integrals of simple functions.", status: 'draft', basedOn: "v0.9.3#23f8e685" } },
  "def-link.mct-nonneg": { note: { en: "MCT is built around this definition.", status: 'draft', basedOn: "v0.9.3#8a00eacf" } },
  "def-link.lplus-mct": { note: { en: "MCT requires every term of the sequence to lie in $L^{+}$.", status: 'draft', basedOn: "v0.9.3#05d81406" } },
  "def-link.lplus-complex": { note: { en: "The integral of a complex-valued function is computed by integrating its positive and negative parts back in $L^{+}$.", status: 'draft', basedOn: "v0.9.3#850f3a17" } },
  "def-link.lplus-integrable": { note: { en: "Integrable $\\iff \\int |f| < \\infty$, whereas $|f| \\in L^{+}$.", status: 'draft', basedOn: "v0.9.3#16a83a81" } },
  "def-link.integrable-dct": { note: { en: "Both the hypotheses and the conclusion of DCT are in $L^{1}$.", status: 'draft', basedOn: "v0.9.3#1f72c8d8" } },
  "def-link.lplus-dct": { note: { en: "The proof of DCT applies Fatou's lemma once to each of the positive and negative parts, bringing us back to $L^{+}$.", status: 'draft', basedOn: "v0.9.3#f91e05d1" } },
  "def-link.nullset-zeromeasure": { note: { en: "In “the integral is zero $\\iff$ the function is zero almost everywhere,” a.e. is understood in terms of null sets.", status: 'draft', basedOn: "v0.9.3#6592decd" } },
  "def-link.premeasure-termwise": { note: { en: "Term-by-term integration ultimately rests on the countable additivity of the measure.", status: 'draft', basedOn: "v0.9.3#4f6a006a" } },
  "def-link.integrable-approx": { note: { en: "The approximation theorem is stated in $L^{1}$ (using the quantity $\\int |f - \\varphi |$).", status: 'draft', basedOn: "v0.9.3#86319992" } },
  "def-link.simple-approx-L1": { note: { en: "The approximation uses simple functions.", status: 'draft', basedOn: "v0.9.3#aaf2f94c" } },
  "e1.definition": { note: { en: "To integrate over a set, multiply by its indicator function and use the nonnegative integral. In the integrable case, split into positive and negative parts.", status: 'draft', basedOn: "v0.9.3#85bb3114" } },
  "dep.vs-subspace": { note: { en: "The definition of a subspace uses only the three vector space axioms for operations (addition, scalar multiplication, and the zero element) and does not involve a basis.", status: 'draft', basedOn: "v0.9.3#c8a7fcc6" } },
  "dep.subspace-criterion": { note: { en: "The criterion compresses the three conditions in the definition of a subspace into one operation $cu + v$. The spanning version invokes the subspace directly.", status: 'draft', basedOn: "v0.9.3#fc782716" } },
  "dep.vs-coordinate": { note: { en: "Coordinates are well-defined by the definition of a basis (linear independence + spanning = unique representation), which is given in `def.vs`.", status: 'draft', basedOn: "v0.9.3#0a9dee8d" } },
  "dep.vs-linearmap": { note: { en: "The definition of a linear map uses vector addition and scalar multiplication. The same wording applies in a different category, such as modules.", status: 'draft', basedOn: "v0.9.3#f09d0b86" } },
  "dep.linearmap-isomorphism": { note: { en: "An isomorphism is a bijective linear map. The linear part comes from here, and the bijective part comes from set theory.", status: 'draft', basedOn: "v0.9.3#422b0a28" } },
  "dep.linearmap-kernelimage": { note: { en: "The kernel is defined as $T^{-1}(0)$ and the image as $T(V)$, both using only the linearity of $T$ (in fact, the definitions require no linearity. Linearity only ensures that they are subspaces).", status: 'draft', basedOn: "v0.9.3#5ed1752d" } },
  "dep.kernelimage-rank": { note: { en: "Rank is defined as the dimension of the image, and dimension relies on the result that dimension is well-defined.", status: 'draft', basedOn: "v0.9.3#c53cfd1e" } },
  "dep.kernelimage-nullity": { note: { en: "Nullity is defined as the dimension of the kernel, using the same notion of dimension.", status: 'draft', basedOn: "v0.9.3#6abc2452" } },
  "dep.rank-nullity": { note: { en: "The two terms in the theorem are rank and nullity. The theorem says that their sum equals the dimension of the domain.", status: 'draft', basedOn: "v0.9.3#ac0c0bb8" } },
  "dep.linearmap-dualspace": { note: { en: "The dual space is obtained by taking the $W = K$ of $\\operatorname{Hom}(V, K)$. A linear functional is a linear map into a one-dimensional space.", status: 'draft', basedOn: "v0.9.3#477a95c1" } },
  "dep.dualspace-annihilator": { note: { en: "The annihilator is the subspace of $V^{\\ast}$ cut out by the condition of vanishing on $U$.", status: 'draft', basedOn: "v0.9.3#bc5cf473" } },
  "dep.dualmap-dualspace": { note: { en: "The source and target of a dual map are both dual spaces", status: 'draft', basedOn: "v0.9.3#8e49be77" } },
  "dep.dualmap-linearmap": { note: { en: "The dual map is induced by the linear map T", status: 'draft', basedOn: "v0.9.3#e3b60ff8" } },
  "dep.dualmap-transpose": { note: { en: "In finite dimensions, once bases are chosen, the matrix of the dual map is the transpose matrix. This describes a property and a representation. The definition is independent of this representation (dual maps also exist in infinite dimensions)", status: 'draft', basedOn: "v0.9.3#9b3bf576" } },
  "ana.dualmap-conjtranspose": { note: { en: "The dual map and conjugate transpose describe the same phenomenon in two languages. They agree over the reals and differ by conjugation over the complexes", status: 'draft', basedOn: "v0.9.3#381d06e1" } },
  "dep.dualfunctor-functor": { note: { en: "The dual functor is a covariant functor out of the opposite category", status: 'draft', basedOn: "v0.9.3#b1912cdb" } },
  "dep.dualfunctor-cvect": { note: { en: "The domain is the opposite of the category of vector spaces", status: 'draft', basedOn: "v0.9.3#28b6a6f6" } },
  "dep.dualfunctor-dualmap": { note: { en: "The dual functor acts on morphisms by taking their dual maps", status: 'draft', basedOn: "v0.9.3#0173291b" } },
  "dep.vs-matrix": { note: { en: "The entries of a matrix lie in the field $K$, and the row and column index sets are finite. The definition uses only a field and finite index sets.", status: 'draft', basedOn: "v0.9.3#5054bd9b" } },
  "dep.matrix-ops": { note: { en: "Addition, scalar multiplication, and multiplication are all given by formulas for matrix entries, so they presuppose matrices.", status: 'draft', basedOn: "v0.9.3#48f32473" } },
  "dep.linearmap-matrix": { note: { en: "The two sides of the theorem are $\\operatorname{Hom}_K(V, W)$ and the set of matrices, and the elements on the left are linear maps.", status: 'draft', basedOn: "v0.9.3#cd973e40" } },
  "dep.matrix-elementary": { note: { en: "An elementary matrix is obtained by applying one elementary row operation to the identity matrix.", status: 'draft', basedOn: "v0.9.3#6172af74" } },
  "dep.matrixops-invertible": { note: { en: "Invertibility is stated using multiplication ($AB = BA = I_n$), so multiplication is a prerequisite.", status: 'draft', basedOn: "v0.9.3#bf6a97d9" } },
  "dep.equivmat-elementary": { note: { en: "The second characterization of matrix equivalence, by finitely many elementary row or column operations, uses elementary matrices. Left multiplication acts on rows, and right multiplication acts on columns.", status: 'draft', basedOn: "v0.9.3#f9b0b816" } },
  "dep.equivmat-invertible": { note: { en: "$P,Q$ must be invertible matrices ($P \\in GL_m(K)$, $Q \\in GL_n(K)$), so the definition directly uses invertible matrices and the general linear group.", status: 'draft', basedOn: "v0.9.3#d984cfdc" } },
  "dep.equivmat-rank": { note: { en: "Rank is a complete invariant for matrix equivalence classes over a field. The normal form is written as $\\operatorname{diag}(I_r,0)$, where $r=\\operatorname{rank}A$.", status: 'draft', basedOn: "v0.9.3#2fc36538" } },
  "ana.equivmat-similarity": { note: { en: "Similarity $B=P^{-1}AP$ is the special case of matrix equivalence $B=PAQ$ obtained by taking $Q=P^{-1}$, and applies only to square matrices of the same size. Similarity preserves eigenvalues, while matrix equivalence preserves only rank.", status: 'draft', basedOn: "v0.9.3#ca6d2969" } },
  "dep.multilinear-alternating": { note: { en: "Alternation is an **additional condition** imposed on a multilinear form (swapping arguments changes the sign), so multilinearity comes first.", status: 'draft', basedOn: "v0.9.3#7a4322e3" } },
  "dep.alternating-det": { note: { en: "The determinant is the particular alternating $n$-linear form on $V = K^{n}$ (with an explicit formula in terms of permutation signs).", status: 'draft', basedOn: "v0.9.3#e94ef797" } },
  "dep.detexists-determinant": { note: { en: "The existence and uniqueness theorem guarantees that the unique $D$ actually exists, making the definition of the determinant well-founded.", status: 'draft', basedOn: "v0.9.3#52bffe91" } },
  "dep.rank-rowcol": { note: { en: "The theorem says that row rank and column rank both equal $\\operatorname{rank} A$, whose definition comes from the associated map.", status: 'draft', basedOn: "v0.9.3#407c821d" } },
  "dep.rank-linearsystems": { note: { en: "Both the existence of solutions and the dimension of the solution space are expressed in terms of $\\operatorname{rank} A$.", status: 'draft', basedOn: "v0.9.3#15aaa0df" } },
  "dep.vs-multilinearform": { note: { en: "A multilinear form on a $K$-vector space $V$ is a map $V^{n} \\to K$, so the definition presupposes vector spaces.", status: 'draft', basedOn: "v0.9.3#7b5b017f" } },
  "dep.rowspace-matrix": { note: { en: "The row space is spanned by the row vectors of the matrix.", status: 'draft', basedOn: "v0.9.3#668594a4" } },
  "dep.rowspace-rank": { note: { en: "Row rank is defined as the dimension of the row space and equals the rank of the matrix.", status: 'draft', basedOn: "v0.9.3#593ca151" } },
  "dep.rowspace-transpose": { note: { en: "The row space equals the column space of the transpose matrix.", status: 'draft', basedOn: "v0.9.3#40aab7a9" } },
  "dep.colspace-matrix": { note: { en: "The column space is spanned by the column vectors of the matrix.", status: 'draft', basedOn: "v0.9.3#b3822eba" } },
  "dep.colspace-linearmap": { note: { en: "The column space is the image of the linear map $x \\mapsto Ax$.", status: 'draft', basedOn: "v0.9.3#756f25ae" } },
  "dep.colspace-rank": { note: { en: "Column rank equals the rank of the matrix.", status: 'draft', basedOn: "v0.9.3#ef04bd9f" } },
  "ana.rowspace-colspace": { note: { en: "The row space and column space have the same dimension (both equal to the rank) and lie in $K^n$ and $K^m$, respectively. Transposition interchanges them.", status: 'draft', basedOn: "v0.9.3#32e85020" } },
  "dep.rref-matrix": { note: { en: "Row echelon form is obtained by applying elementary row operations to a matrix.", status: 'draft', basedOn: "v0.9.3#efb72943" } },
  "dep.rref-elementary": { note: { en: "Reduction to row echelon form uses elementary row operations (left multiplication by elementary matrices).", status: 'draft', basedOn: "v0.9.3#15b39ad2" } },
  "dep.smith-pid": { note: { en: "Smith normal form requires the base ring to be a principal ideal domain.", status: 'draft', basedOn: "v0.9.3#3236268d" } },
  "dep.smith-matrix": { note: { en: "The theorem is stated for $m \\times n$ matrices over a ring.", status: 'draft', basedOn: "v0.9.3#eba1bb96" } },
  "dep.smith-elementary": { note: { en: "The proof uses elementary row and column operations to carry out equivalence transformations.", status: 'draft', basedOn: "v0.9.3#a386625c" } },
  "dep.smith-equivalent": { note: { en: "Smith normal form is a normal form under matrix equivalence.", status: 'draft', basedOn: "v0.9.3#fb7011b1" } },
  "dep.ring-polyring": { note: { en: "$K[x]$ is a concrete example of a ring. Addition is coefficientwise, multiplication is convolution, and the axioms being verified are the ring axioms.", status: 'draft', basedOn: "v0.9.3#1ecf01bd" } },
  "dep.polynomial-polyring": { note: { en: "The elements of $K[x]$ are polynomials, and the ring structure is defined on them.", status: 'draft', basedOn: "v0.9.3#175e2205" } },
  "dep.polyring-division": { note: { en: "Division with remainder is an operation between two elements of $K[x]$, so it presupposes this ring.", status: 'draft', basedOn: "v0.9.3#77cf74b6" } },
  "dep.field-polynomial": { note: { en: "Polynomials are defined over a coefficient field $K$ (the definition also works over a general commutative ring, but the division properties of $K[x]$ rely on having a field).", status: 'draft', basedOn: "v0.9.3#a23762aa" } },
  "dep.linearmap-invariant": { note: { en: "Invariance means $T(U) \\subseteq U$, and the only fact used about $T$ is that it is a map.", status: 'draft', basedOn: "v0.9.3#ee959c9f" } },
  "dep.invariant-eigenvalue": { note: { en: "An eigenvector corresponds to a one-dimensional invariant subspace: $T(\\langle v \\rangle) \\subseteq \\langle v \\rangle$ and $v \\ne 0$.", status: 'draft', basedOn: "v0.9.3#4e09295b" } },
  "dep.determinant-charpoly": { note: { en: "The characteristic polynomial is $\\det(xI - A)$. This is the first use of the determinant in a setting where the variable is a matrix.", status: 'draft', basedOn: "v0.9.3#3aa995be" } },
  "dep.polyring-charpoly": { note: { en: "The result of $\\det(xI - A)$ lies in $K[x]$ and is an element of the polynomial ring.", status: 'draft', basedOn: "v0.9.3#01ee3538" } },
  "dep.charpoly-trace": { note: { en: "The trace is a coefficient of the characteristic polynomial $x^{n-1}$ up to sign. The two edges explain each other, and this edge says that the trace is defined by the characteristic polynomial.", status: 'draft', basedOn: "v0.9.3#4dcea09a" } },
  "dep.changeofbasis-similarity": { note: { en: "The definition of similarity, $B = P^{-1}AP$, is the change-of-basis formula written in matrix form.", status: 'draft', basedOn: "v0.9.3#488c14d0" } },
  "dep.charpoly-minimal": { note: { en: "The set $I_T$ used to define the minimal polynomial is nonempty by Cayley–Hamilton (that is, $\\chi_T \\in I_T$).", status: 'draft', basedOn: "v0.9.3#ccb117e4" } },
  "dep.minimal-primary": { note: { en: "In the algebraic version of primary decomposition, the factors of $\\chi_T$ and the minimal polynomial both arise from the same ideal theory.", status: 'draft', basedOn: "v0.9.3#cce1adf0" } },
  "def-link.quotient-jordan": { note: { en: "The induction step takes place in the quotient space $V/\\ker(T-\\lambda I)$. The definition and universal property of the quotient space enter the proof directly.", status: 'draft', basedOn: "v0.9.3#3049b9a1" } },
  "dep.minpoly-algebraicclosure": { note: { en: "The minimal polynomial splits over the algebraic closure.", status: 'draft', basedOn: "v0.9.3#ac5a83b8" } },
  "dep.cyclic-linearmap": { note: { en: "The cyclic subspace is generated by iterating $T$.", status: 'draft', basedOn: "v0.9.3#ca0ff966" } },
  "dep.companion-matrix": { note: { en: "The companion matrix is a concrete matrix in $M_m(K)$.", status: 'draft', basedOn: "v0.9.3#53d833b5" } },
  "dep.elemdiv-invariant": { note: { en: "The elementary divisors are obtained from the prime-power factorizations of the invariant factors.", status: 'draft', basedOn: "v0.9.3#dc581fff" } },
  "dep.pidfg-module": { note: { en: "The structure theorem concerns finitely generated modules.", status: 'draft', basedOn: "v0.9.3#dfd0b594" } },
  "dep.pidfg-pid": { note: { en: "A principal ideal domain ensures that each ideal is generated by a single element.", status: 'draft', basedOn: "v0.9.3#6d4564eb" } },
  "ana.jcf-rcf": { note: { en: "These are two canonical forms for the same classification problem up to similarity. Jordan form requires the characteristic polynomial to split and further decomposes cyclic blocks into Jordan blocks. Rational canonical form works over any field and uses companion matrices of the invariant factors as blocks. Over a splitting field, Jordan form refines rational canonical form according to the elementary divisors $(x-\\lambda)^s$.", status: 'draft', basedOn: "v0.9.3#a65ba5c0" } },
  "dep.vs-innerproduct": { note: { en: "An inner product is an **additional structure** on a vector space. The first of its three axioms is linearity in the first argument, which uses the operations of $V$.", status: 'draft', basedOn: "v0.9.3#216ee0fe" } },
  "dep.innerproduct-inducednorm": { note: { en: "The norm is defined as $\\sqrt{\\langle v, v\\rangle}$, and its validity follows from the positive definiteness of the inner product.", status: 'draft', basedOn: "v0.9.3#56119ea0" } },
  "dep.metric-inducednorm": { note: { en: "The norm of an inner product space gives the distance $d(u,v) = \\|u - v\\|$, so it is automatically a metric space and the tools from analysis apply.", status: 'draft', basedOn: "v0.9.3#804dc438" } },
  "dep.innerproduct-orthogonality": { note: { en: "Orthogonality means that the inner product is zero. The definition uses only the inner product.", status: 'draft', basedOn: "v0.9.3#83d4db14" } },
  "dep.orthogonality-orthocomplement": { note: { en: "The orthogonal complement is the set of vectors orthogonal to every element of $U$, so it presupposes orthogonality.", status: 'draft', basedOn: "v0.9.3#cee01561" } },
  "dep.orthocomplement-projection": { note: { en: "The definition of projection uses the direct sum decomposition $V = U \\oplus U^{\\perp}$, which uses the orthogonal complement.", status: 'draft', basedOn: "v0.9.3#17b042cf" } },
  "dep.innerproduct-operatoradjoint": { note: { en: "The adjoint operator is defined by an inner product identity. Its existence and uniqueness rely on completeness with respect to the inner product (Riesz representation).", status: 'draft', basedOn: "v0.9.3#a43346a4" } },
  "dep.operatoradjoint-normal": { note: { en: "Normal, self-adjoint, and unitary operators are all defined in terms of the adjoint ($T^{\\ast}T = TT^{\\ast}$ and so on).", status: 'draft', basedOn: "v0.9.3#7d8fa76c" } },
  "dep.innerproduct-isometry": { note: { en: "An isometry is defined by preservation of the inner product (equivalently, preservation of the norm).", status: 'draft', basedOn: "v0.9.3#5c549f8c" } },
  "dep.bilinearform-quadraticform": { note: { en: "The symmetric bilinear form $B$ and the quadratic form $q$ determine each other through the polarization identity ($2B(u, v) = q(u + v) - q(u) - q(v)$), so a quadratic form is the diagonal expression of a symmetric bilinear form.", status: 'draft', basedOn: "v0.9.3#8ba61123" } },
  "dep.sym-complex-def-inner-product": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.multilinearform-bilinear": { note: { en: "A bilinear form is a multilinear form with $n = 2$ arguments (with the added generality that the two spaces may differ and the codomain need not be $K$).", status: 'draft', basedOn: "v0.9.3#6dce2714" } },
  "dep.bilinear-tensor": { note: { en: "The universal property of the tensor product turns bilinear maps into linear maps. The maps it applies to are bilinear.", status: 'draft', basedOn: "v0.9.3#27d0abae" } },
  "dep.tensor-exterior": { note: { en: "The exterior algebra is a quotient of the tensor algebra $V^{\\otimes\\bullet}$ (quotienting out elements of the form $v \\otimes v$).", status: 'draft', basedOn: "v0.9.3#4af90993" } },
  "dep.tensor-symmetric": { note: { en: "The symmetric algebra is likewise a quotient of the tensor algebra (quotienting out $v \\otimes w - w \\otimes v$).", status: 'draft', basedOn: "v0.9.3#81475056" } },
  "dep.alternating-exteriorpower": { note: { en: "The alternating property of exterior powers ($v \\wedge v = 0$) and that of alternating forms express the same condition. One concerns multiplication in the algebra, and the other concerns the values of multilinear forms.", status: 'draft', basedOn: "v0.9.3#3d4834c1" } },
  "dep.complete-banach-space": { note: { en: "A Banach space is a normed space with metric completeness. The definition directly invokes completeness.", status: 'draft', basedOn: "v0.9.3#17b7f132" } },
  "dep.derivative-partial-derivative": { note: { en: "A partial derivative is a one-variable derivative. Hold the other coordinates fixed and differentiate only with respect to coordinate $j$.", status: 'draft', basedOn: "v0.9.3#6b4b0199" } },
  "dep.matrix-jacobian": { note: { en: "The Jacobian matrix is a $m \\times n$ matrix (`def.matrix` provides the concept of a matrix itself).", status: 'draft', basedOn: "v0.9.3#1147c2f1" } },
  "dep.metric-contraction": { note: { en: "A contraction is defined on a metric space (it uses only distance and requires no linear structure).", status: 'draft', basedOn: "v0.9.3#731ce9c1" } },
  "dep.banachspace-inverse-banach": { note: { en: "The Banach-space version of the inverse function theorem is set in Banach spaces.", status: 'draft', basedOn: "v0.9.3#68e33e36" } },
  "dep.subgroup-lagrange": { note: { en: "Lagrange's theorem relates the order of a subgroup $H$ to the order of the group.", status: 'draft', basedOn: "v0.9.3#53f65787" } },
  "dep.normal-simple": { note: { en: "\"Simple\" is defined using normal subgroups. There are only the two trivial normal subgroups.", status: 'draft', basedOn: "v0.9.3#4232d2ff" } },
  "dep.subgroup-solvable": { note: { en: "Solvability is defined using a chain of subgroups.", status: 'draft', basedOn: "v0.9.3#95376f07" } },
  "dep.quotient-solvable": { note: { en: "In a solvable chain, the quotient $G_i/G_{i-1}$ is required to be abelian.", status: 'draft', basedOn: "v0.9.3#9d7b7680" } },
  "dep.stabilizer-subgroup": { note: { en: "The stabilizer is shown to be a subgroup.", status: 'draft', basedOn: "v0.9.3#56d571f3" } },
  "dep.orbit-os": { note: { en: "The statement of the orbit–stabilizer theorem uses the orbit.", status: 'draft', basedOn: "v0.9.3#31bb3f95" } },
  "dep.stabilizer-os": { note: { en: "The statement of the orbit–stabilizer theorem uses the stabilizer.", status: 'draft', basedOn: "v0.9.3#05b833af" } },
  "dep.normalizer-subgroup": { note: { en: "The normalizer is a subgroup containing the given subgroup.", status: 'draft', basedOn: "v0.9.3#18ed294f" } },
  "dep.normalizer-sylow": { note: { en: "The Sylow count $n_p=[G:N_G(P)]$ is expressed in terms of the normalizer.", status: 'draft', basedOn: "v0.9.3#fbaf63b1" } },
  "dep.sylow-pgroup": { note: { en: "Sylow subgroups are the $p$-subgroups of largest order.", status: 'draft', basedOn: "v0.9.3#c5ae6516" } },
  "dep.sylow-order": { note: { en: "The order $p^a$ of a Sylow subgroup is determined by $|G|=p^a m$.", status: 'draft', basedOn: "v0.9.3#a5a2b4a5" } },
  "dep.sylow-thm": { note: { en: "The Sylow theorems concern the existence, conjugacy, and counting of Sylow subgroups.", status: 'draft', basedOn: "v0.9.3#9df4d41b" } },
  "dep.pgroup-lemma": { note: { en: "The lemma concerns finite $p$-groups.", status: 'draft', basedOn: "v0.9.3#69ae6e8d" } },
  "def-link.cauchy-thm": { note: { en: "The theorem upgrades the Cauchy property in measure to convergence in measure plus an a.e. convergent subsequence.", status: 'draft', basedOn: "v0.9.3#d10ee44b" } },
  "def-link.integrable-measure": { note: { en: "The definition of convergence in $L^{1}$ uses $\\int |f_{n} - f|$.", status: 'draft', basedOn: "v0.9.3#14d3360f" } },
  "def-link.measure-egorov": { note: { en: "Step ③ of the proof relies on continuity from above of the measure, a consequence of countable additivity.", status: 'draft', basedOn: "v0.9.3#eccd0f76" } },
  "dep.sym-real-thm-geometric-series": { note: { en: "The statement concerns the real numbers $\\mathbb{R}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#0453d27b" } },
  "def-link.abs-seq-limit": { note: { en: "The definition of convergence is precisely $|x_n - x| < \\varepsilon$. This statement cannot be written without absolute value.", status: 'draft', basedOn: "v0.9.3#87264126" } },
  "def-dep.subset-outer-measure": { note: { en: "An outer measure is defined on **all subsets**: $\\mu^* : \\mathcal{P}(X) \\to [0, +\\infty]$.", status: 'draft', basedOn: "v0.9.3#b110697f" } },
  "def-dep.outer-carath": { note: { en: "“Let $\\mu^*$ be an **outer measure** on $X$.” Measurability is determined entirely by $\\mu^*$ alone.", status: 'draft', basedOn: "v0.9.3#049118df" } },
  "def-dep.sigma-algebra-measurable-fn": { note: { en: "A measurable space $(X, \\mathcal{M})$ is a set $+$ equipped with a $\\sigma$-algebra. Measurability means that preimages belong to $\\mathcal{M}$.", status: 'draft', basedOn: "v0.9.3#920bd23c" } },
  "def-dep.measurable-fn-lplus": { note: { en: "$L^+$ is the set of all **measurable** functions taking values in $[0, +\\infty]$.", status: 'draft', basedOn: "v0.9.3#601e8a85" } },
  "def-dep.measure-lplus": { note: { en: "To speak of $L^+$, one must **first fix a measure space** $(X, \\mathcal{M}, \\mu)$.", status: 'draft', basedOn: "v0.9.3#49e1d1a8" } },
  "def-dep.measure-integral-simple": { note: { en: "In the weighted sum $\\sum_j a_j \\, \\mu(E_j)$, $\\mu$ is a **measure**.", status: 'draft', basedOn: "v0.9.3#30a672c1" } },
  "def-dep.lplus-integral-nonneg": { note: { en: "The definition is written as $\\int f := \\sup \\{ \\int \\varphi : 0 \\le \\varphi \\le f \\}$, where $f \\in L^+$.", status: 'draft', basedOn: "v0.9.3#c1d3fda1" } },
  "def-dep.nonneg-integral-complex": { note: { en: "The integrals $\\int f^+$ and $\\int f^-$ of the positive and negative parts both use **integration of nonnegative functions**.", status: 'draft', basedOn: "v0.9.3#7821091d" } },
  "def-dep.nonneg-integral-integrable": { note: { en: "The integrability criterion $\\int |f| < \\infty$ is an integral of a nonnegative function.", status: 'draft', basedOn: "v0.9.3#dba95258" } },
  "def-dep.integral-complex-integrable": { note: { en: "In the real-valued case, first split the function into its positive and negative parts (integration of complex functions), then require both integrals to be finite.", status: 'draft', basedOn: "v0.9.3#43a8de23" } },
  "def-dep.measurable-fn-cauchy-in-measure": { note: { en: "Being Cauchy in measure is a property of a **sequence of measurable functions**.", status: 'draft', basedOn: "v0.9.3#eb7b3688" } },
  "def-dep.measure-cauchy-in-measure": { note: { en: "In the definition, $\\mu(\\{\\cdots\\})$ is a measure.", status: 'draft', basedOn: "v0.9.3#e6c0892a" } },
  "def-dep.measure-product-measure": { note: { en: "$\\mu \\times \\nu$ is constructed from two **measures**, $\\mu$ and $\\nu$.", status: 'draft', basedOn: "v0.9.3#fc7c4faa" } },
  "def-dep.outer-product-measure": { note: { en: "In the extension step, $\\mu_{0}$ **induces an outer measure on $X \\times Y$**, which is then restricted to the product $\\sigma$-algebra.", status: 'draft', basedOn: "v0.9.3#5dcb26a4" } },
  "def-dep.subset-section": { note: { en: "The section $E_x = \\{ y : (x, y) \\in E \\}$ is a **subset** ($E \\subseteq X \\times Y$).", status: 'draft', basedOn: "v0.9.3#3ce9a758" } },
  "def-dep.null-set-absolute-continuity": { note: { en: "The definition of $\\nu \\ll \\mu$ is that every $\\mu$-**null set** is a $\\nu$-null set.", status: 'draft', basedOn: "v0.9.3#6a855be1" } },
  "def-dep.sigma-algebra-complex-measure": { note: { en: "A complex measure is likewise defined on a **measurable space** $(X, \\mathcal{M})$.", status: 'draft', basedOn: "v0.9.3#18ce681b" } },
  "def-dep.measure-complex-measure": { note: { en: "A complex measure is defined by changing the values in the definition of a **measure**, as in $\\nu : \\mathcal{M} \\to \\mathbb{C}$.", status: 'draft', basedOn: "v0.9.3#1ca660a2" } },
  "def-dep.measure-average-operator": { note: { en: "In the average, $m(B(x, r))$ is **Lebesgue measure**.", status: 'draft', basedOn: "v0.9.3#8f4109aa" } },
  "def-dep.borel-shrinks-nicely": { note: { en: "$\\{ E_r \\}$ is required to be a family of **Borel subsets** so that $m(E_r)$ makes sense.", status: 'draft', basedOn: "v0.9.3#586a5bd8" } },
  "def-dep.subset-shrinks-nicely": { note: { en: "The first condition is $E_r \\subseteq B(x, r)$, a **subset** relation.", status: 'draft', basedOn: "v0.9.3#ff05d4ca" } },
  "def-dep.poset-real": { note: { en: "The real number system is a **totally ordered** field. The total order in the order axioms is a partial order with comparability.", status: 'draft', basedOn: "v0.9.3#6aad74b7" } },
  "def-dep.borel-nbv": { note: { en: "The two conditions are imposed to obtain a one-to-one correspondence with **complex Borel measures** on $\\mathbb{R}$.", status: 'draft', basedOn: "v0.9.3#6402121b" } },
  "def-dep.measure-essential-sup": { note: { en: "The expression $\\mu(\\{ |f| > a \\}) = 0$ in the definition uses a **measure**.", status: 'draft', basedOn: "v0.9.3#b24200a1" } },
  "def-dep.null-set-essential-sup": { note: { en: "“Ignore all values of $f$ on **null sets**.” This is precisely what an essential upper bound means.", status: 'draft', basedOn: "v0.9.3#fb9a50c2" } },
  "def-dep.measurable-fn-essential-sup": { note: { en: "The elements of $L^\\infty$ are **measurable** functions with finite essential supremum.", status: 'draft', basedOn: "v0.9.3#69195d86" } },
  "def-dep.conjugate-duality-map": { note: { en: "“Let $p, q$ be **conjugate**, with $g \\in L^q$.” Conjugate exponents are a hypothesis of this definition.", status: 'draft', basedOn: "v0.9.3#7542896e" } },
  "def-dep.integral-complex-duality-map": { note: { en: "$\\varphi_g(f) = \\int f g \\, d\\mu$ is itself an **integral**.", status: 'draft', basedOn: "v0.9.3#d42eedc8" } },
  "def-dep.essential-sup-duality-map": { note: { en: "The $g \\in L^\\infty$ endpoint ($p = 1$) uses the essential supremum.", status: 'draft', basedOn: "v0.9.3#da47584d" } },
  "def-dep.function-measurable-function": { note: { en: "Measurability is a property of a **function** $f : X \\to Y$. A function is needed before one can say that the preimage of every measurable set is measurable.", status: 'draft', basedOn: "v0.9.3#8888e966" } },
  "def-dep.metric-shrinks-nicely": { note: { en: "In “$E_r \\subseteq B(x, r)$”, $B(x, r)$ is a ball in a **metric space**.", status: 'draft', basedOn: "v0.9.3#c5048a66" } },
  "def-dep.measure-shrinks-nicely": { note: { en: "In “$m(E_r) > \\alpha \\cdot m(B(x, r))$”, $m$ is a **measure**.", status: 'draft', basedOn: "v0.9.3#827284ca" } },
  "def-dep.lplus-integral-simple": { note: { en: "The standard form says “$\\varphi \\in L^+$ is a simple function”, with domain contained in $L^+$.", status: 'draft', basedOn: "v0.9.3#adeb392d" } },
  "def-dep.pair-graph": { note: { en: "The quadruple $(V, E, s, t)$ is a **nested ordered pair**. Ordered pairs provide its underlying representation and are needed to write the quadruple.", status: 'draft', basedOn: "v0.9.3#3fb99922" } },
  "def-dep.function-graph": { note: { en: "The source and target maps $s, t : E \\to V$ are two **functions**.", status: 'draft', basedOn: "v0.9.3#7f71a00f" } },
  "def-dep.graph-graph-morphism": { note: { en: "A graph morphism goes **between graphs**, so it presupposes graphs as objects.", status: 'draft', basedOn: "v0.9.3#f0b5ade0" } },
  "def-dep.function-graph-morphism": { note: { en: "A graph morphism consists of a **pair of functions** $(\\varphi_1, \\varphi_2)$ together with two commutativity equations.", status: 'draft', basedOn: "v0.9.3#64d9aa82" } },
  "def-dep.graph-category": { note: { en: "A category is a sextuple in which $(\\mathcal{O}, M, s, t)$ **is a graph**. The graph is the underlying structure of the category, with composition and identities added.", status: 'draft', basedOn: "v0.9.3#56d46adf" } },
  "def-dep.product-category": { note: { en: "Composition $\\circ$ starts from a portion of $M \\times M$, so the **Cartesian product** is needed first.", status: 'draft', basedOn: "v0.9.3#cfa1e550" } },
  "def-dep.subset-category": { note: { en: "$M \\times_{s,t} M = \\{ (f,g) \\in M \\times M : s(f) = t(g) \\}$ is a **subset** of $M \\times M$.", status: 'draft', basedOn: "v0.9.3#aa752739" } },
  "def-dep.category-section": { note: { en: "Sections and retractions describe a relationship between **morphisms and identity morphisms** in a category and presuppose a category.", status: 'draft', basedOn: "v0.9.3#5e94c7d2" } },
  "def-dep.category-functor": { note: { en: "The domain and target of a functor are both **categories**. Objects map to objects and morphisms map to morphisms.", status: 'draft', basedOn: "v0.9.3#4e75e6ea" } },
  "def-dep.function-functor": { note: { en: "A functor gives one **function** on objects and one on morphisms.", status: 'draft', basedOn: "v0.9.3#e5d9a61b" } },
  "def-dep.functor-nat": { note: { en: "A natural transformation is **between two functors**, so two functors are needed first.", status: 'draft', basedOn: "v0.9.3#b1f1d64c" } },
  "def-dep.category-nat": { note: { en: "Each component $\\alpha_X : F(X) \\to G(X)$ of a natural transformation is a **morphism** in the category, and the naturality square commutes in that category as well.", status: 'draft', basedOn: "v0.9.3#9dc01523" } },
  "def-dep.functor-ff": { note: { en: "Faithfulness and fullness are properties of **the map the functor induces** on the $\\operatorname{Hom}$ sets.", status: 'draft', basedOn: "v0.9.3#4c2b66aa" } },
  "def-dep.functor-eso": { note: { en: "Essential surjectivity describes how much of the target the functor's image covers **on objects**.", status: 'draft', basedOn: "v0.9.3#66cd23ca" } },
  "def-dep.functor-equivalence": { note: { en: "Being an equivalence of categories is a property of a **functor**. A functor is needed before one can ask whether it is an equivalence.", status: 'draft', basedOn: "v0.9.3#c3e93938" } },
  "def-dep.nat-equivalence": { note: { en: "An equivalence requires the two composites to be **naturally isomorphic** to the identity functors. The “$\\cong$” can only be expressed using natural transformations.", status: 'draft', basedOn: "v0.9.3#1ea6268c" } },
  "def-dep.functor-diagram": { note: { en: "A diagram is a **functor** $D : I \\to \\mathcal{C}$ whose domain is the indexing category $I$.", status: 'draft', basedOn: "v0.9.3#cb64c3ec" } },
  "def-dep.category-diagram": { note: { en: "The indexing category and the target are both **categories**. The entire notion of a diagram is built on categories.", status: 'draft', basedOn: "v0.9.3#3f3403f9" } },
  "def-dep.function-cone": { note: { en: "A cone is a **family** of morphisms $p_i : X \\to D(i)$, and the family is underlain by a function whose domain consists of the objects of $I$.", status: 'draft', basedOn: "v0.9.3#acb8e396" } },
  "def-dep.nat-cone": { note: { en: "A cone is a **natural transformation** from the constant diagram to $D$, denoted $\\Delta X \\implies D$. The compatibility condition is precisely the naturality square.", status: 'draft', basedOn: "v0.9.3#c19103c9" } },
  "def-dep.diagram-limit": { note: { en: "A limit is the limit of a **diagram**. A diagram is needed before one can speak of its universal cone.", status: 'draft', basedOn: "v0.9.3#c56205d2" } },
  "def-dep.cone-limit": { note: { en: "A limit is defined as a “**universal cone**”. The cone is the starting object, and the universal property is the criterion it must satisfy.", status: 'draft', basedOn: "v0.9.3#fe11f563" } },
  "def-dep.category-limit": { note: { en: "The **uniqueness** in the universal cone property is uniqueness in the category, and the factorization $p_i \\circ g = g_i$ is likewise an equation in the category.", status: 'draft', basedOn: "v0.9.3#1e1aea2b" } },
  "def-dep.limit-product": { note: { en: "A product is a limit over a **discrete category**. The indexing category has no nonidentity morphisms, so the compatibility conditions disappear automatically.", status: 'draft', basedOn: "v0.9.3#955502d6" } },
  "def-dep.product-set": { note: { en: "In $\\mathbf{Set}$, the categorical product is the **Cartesian product**. These are two names for the same thing.", status: 'draft', basedOn: "v0.9.3#d73ca4ac" } },
  "def-dep.limit-fibered": { note: { en: "A fiber product is the limit of a diagram of shape $X_1 \\to X_0 \\leftarrow X_2$.", status: 'draft', basedOn: "v0.9.3#3876ce6d" } },
  "def-dep.limit-equalizer": { note: { en: "An equalizer is the limit of a **parallel pair** $f, g : X \\rightrightarrows Y$.", status: 'draft', basedOn: "v0.9.3#3f5f2492" } },
  "def-dep.fibered-mono": { note: { en: "The equivalent condition $Y \\cong Y \\times_X Y$ for a monomorphism uses precisely the **fiber product** over $i$.", status: 'draft', basedOn: "v0.9.3#04e75dbc" } },
  "def-dep.functor-presheaf": { note: { en: "A presheaf is by definition a **contravariant functor** $T : \\mathcal{C}^{\\mathrm{op}} \\to \\mathbf{Set}$.", status: 'draft', basedOn: "v0.9.3#bf41dda1" } },
  "def-dep.category-presheaf": { note: { en: "$\\mathcal{C}^{\\mathrm{op}}$ and $\\mathbf{Set}$ are both **categories**, and contravariance means that the order of composition is reversed.", status: 'draft', basedOn: "v0.9.3#4d534942" } },
  "def-dep.functor-representable": { note: { en: "The object being represented, $F$, is itself a **functor** $\\mathcal{C} \\to \\mathbf{Set}$.", status: 'draft', basedOn: "v0.9.3#918e369b" } },
  "def-dep.category-representable": { note: { en: "$\\operatorname{Hom}_{\\mathcal{C}}(X, -)$ is the Hom functor for the **category** $\\mathcal{C}$.", status: 'draft', basedOn: "v0.9.3#9802d64f" } },
  "def-dep.function-representable": { note: { en: "Both $\\exists! f : X \\to Y$ and $F(f)(s) = t$ in the universal condition are statements at the level of **functions**.", status: 'draft', basedOn: "v0.9.3#d697abbf" } },
  "def-dep.nat-representable": { note: { en: "The second definition is written as $F \\cong \\operatorname{Hom}_{\\mathcal{C}}(X, -)$, where $\\cong$ is a **natural isomorphism**.", status: 'draft', basedOn: "v0.9.3#f917ff96" } },
  "def-dep.functor-adjoint": { note: { en: "An adjunction is a relation between **two functors**, one in each direction.", status: 'draft', basedOn: "v0.9.3#c74ad100" } },
  "def-dep.category-adjoint": { note: { en: "$\\operatorname{Hom}_{\\mathcal{D}}(F(X), Y)$ and $\\operatorname{Hom}_{\\mathcal{C}}(X, G(Y))$ are Hom sets taken in two **categories**.", status: 'draft', basedOn: "v0.9.3#c7181460" } },
  "def-dep.function-adjoint": { note: { en: "The adjunction isomorphism gives a **bijection** for each pair of objects, and its underlying map is a function.", status: 'draft', basedOn: "v0.9.3#e55d4499" } },
  "def-dep.adjoint-unit": { note: { en: "The unit and counit are obtained by evaluating the adjunction isomorphism $\\Phi$ at two **identity morphisms**. They presuppose the adjunction.", status: 'draft', basedOn: "v0.9.3#e0468d31" } },
  "def-dep.nat-unit": { note: { en: "The unit and counit are themselves **natural transformations**, and the triangle identities are assembled from naturality squares.", status: 'draft', basedOn: "v0.9.3#c399a828" } },
  "def-dep.function-comma": { note: { en: "An object of the comma category is $(Y, f)$, where $f : X \\to G(Y)$ is a **map**.", status: 'draft', basedOn: "v0.9.3#9b9b5409" } },
  "def-dep.functor-comma": { note: { en: "$G$ is a **functor**, and $X \\downarrow G$ is built around it.", status: 'draft', basedOn: "v0.9.3#302fc352" } },
  "def-dep.adjoint-kan": { note: { en: "The left Kan extension is defined by saying that “$p_{!}$ is **left adjoint** to the precomposition functor”, an adjunction isomorphism.", status: 'draft', basedOn: "v0.9.3#380b18bf" } },
  "def-dep.functor-kan": { note: { en: "$p$, $F$, $p_{!}F$, and $G$ are all **functors**.", status: 'draft', basedOn: "v0.9.3#f876ff86" } },
  "def-dep.nat-kan": { note: { en: "$\\alpha : F \\implies p_{!}F \\circ p$ and $\\gamma$ are both **natural transformations**.", status: 'draft', basedOn: "v0.9.3#e49db7f4" } },
  "def-dep.compact-chaus": { note: { en: "A compact Hausdorff space is a **compact** space that also satisfies the Hausdorff condition.", status: 'draft', basedOn: "v0.9.3#1e4f61e9" } },
  "def-dep.hausdorff-chaus": { note: { en: "The “Hausdorff” half comes from the separation axioms.", status: 'draft', basedOn: "v0.9.3#96709d29" } },
  "def-dep.category-chaus": { note: { en: "They form a **category** with spaces as objects and continuous maps as morphisms.", status: 'draft', basedOn: "v0.9.3#bed361d9" } },
  "def-dep.mono-projective": { note: { en: "Projectivity requires lifts along **epimorphisms**, and injectivity dually requires extensions along **monomorphisms**. Both are expressed entirely in terms of arrows.", status: 'draft', basedOn: "v0.9.3#1c5517b0" } },
  "def-dep.fibered-free-presentation": { note: { en: "$R := F \\times_{S} F$ is a **fiber product**.", status: 'draft', basedOn: "v0.9.3#edeb95ee" } },
  "def-dep.chaus-free-presentation": { note: { en: "A free presentation is a surjective triple in $\\mathbf{CHaus}$.", status: 'draft', basedOn: "v0.9.3#4451c254" } },
  "def-dep.connected-stone": { note: { en: "“**Totally disconnected**” means that every connected component is a singleton.", status: 'draft', basedOn: "v0.9.3#0958c6ea" } },
  "def-dep.clopen-stone": { note: { en: "“**Extremally disconnected**” means that the closure of every open set is clopen.", status: 'draft', basedOn: "v0.9.3#bbe86702" } },
  "def-dep.chaus-stone": { note: { en: "Stone spaces and Stonean spaces are, respectively, totally disconnected and extremally disconnected spaces that are also **compact Hausdorff**.", status: 'draft', basedOn: "v0.9.3#81dcda38" } },
  "def-dep.limit-profinite": { note: { en: "A profinite space is a **limit** of finite discrete spaces over a directed system.", status: 'draft', basedOn: "v0.9.3#01ded46b" } },
  "def-dep.presheaf-sieve": { note: { en: "A sieve is a subfunctor of the **presheaf** $h_{X}$.", status: 'draft', basedOn: "v0.9.3#1795270d" } },
  "def-dep.functor-sieve": { note: { en: "“Subfunctor” is itself functorial terminology. $R \\subseteq h_{X}$ must also be compatible on morphisms.", status: 'draft', basedOn: "v0.9.3#935f08cb" } },
  "def-dep.category-pretopology": { note: { en: "A pretopology is a collection of data on a **category**, specifying a collection of covering families for each object.", status: 'draft', basedOn: "v0.9.3#ae9c9ca8" } },
  "def-dep.fibered-pretopology": { note: { en: "In the second condition, “stability under pullback”, $X_{i} \\times_{X} Y$ is a **fiber product**.", status: 'draft', basedOn: "v0.9.3#c071225b" } },
  "def-dep.sieve-topology": { note: { en: "A Grothendieck topology assigns to each $X$ a collection of **covering sieves** $J(X)$.", status: 'draft', basedOn: "v0.9.3#f3e302c9" } },
  "def-dep.presheaf-topology": { note: { en: "$f^{*}(R) = R \\times_{h_{X}} h_{Y}$ is a pullback at the level of **presheaves**.", status: 'draft', basedOn: "v0.9.3#59c1d4ef" } },
  "def-dep.pretopology-topology": { note: { en: "A pretopology gives a topology by generating covering sieves from covering families. Conversely, a topology need not come from a pretopology.", status: 'draft', basedOn: "v0.9.3#3c1e1e9c" } },
  "def-dep.topology-sheaf": { note: { en: "In the definition of a sheaf, $J(X)$ is the collection of **covering sieves**. The topology specifies what “covering” means.", status: 'draft', basedOn: "v0.9.3#403cdb4a" } },
  "def-dep.presheaf-sheaf": { note: { en: "A sheaf is a **presheaf** satisfying an additional condition.", status: 'draft', basedOn: "v0.9.3#f3d0ee6c" } },
  "def-dep.limit-sheaf": { note: { en: "“$F(X) \\cong \\varprojlim_{Y \\in \\mathcal{C}/R} F(Y)$” uses a **limit**.", status: 'draft', basedOn: "v0.9.3#7d7452ae" } },
  "def-dep.sheaf-cech": { note: { en: "The Čech functor is the construction that takes a presheaf a step toward becoming a **sheaf**.", status: 'draft', basedOn: "v0.9.3#4b382daf" } },
  "def-dep.mono-regular-epi": { note: { en: "A regular epimorphism is a **coequalizer**, a more constrained kind of epimorphism.", status: 'draft', basedOn: "v0.9.3#e4bd5921" } },
  "def-dep.equalizer-regular-epi": { note: { en: "“The coequalizer of some parallel pair” uses a **coequalizer**.", status: 'draft', basedOn: "v0.9.3#9f96bb1b" } },
  "def-dep.equalizer-effective": { note: { en: "$\\overline{X} := \\operatorname{coker}(R \\rightrightarrows X)$ is a **coequalizer**.", status: 'draft', basedOn: "v0.9.3#5d7ffc51" } },
  "def-dep.fibered-effective": { note: { en: "Effectiveness concerns $R \\cong X \\times_{\\overline{X}} X$, a **fiber product**.", status: 'draft', basedOn: "v0.9.3#f51a31ff" } },
  "def-dep.ff-generator": { note: { en: "A generating set is defined by requiring the combined functor to be **faithful**.", status: 'draft', basedOn: "v0.9.3#6ee12f55" } },
  "def-dep.topology-qc": { note: { en: "Quasi-compactness means that every family generating a **covering sieve** has a finite subfamily that still generates a covering sieve.", status: 'draft', basedOn: "v0.9.3#9167b7bc" } },
  "def-dep.fibered-qs": { note: { en: "Quasi-separatedness means that the **fiber product** of two quasi-compact objects is again quasi-compact.", status: 'draft', basedOn: "v0.9.3#556e3805" } },
  "def-dep.qc-qs": { note: { en: "Quasi-compactness is built into the notion of quasi-separatedness.", status: 'draft', basedOn: "v0.9.3#efed2b3e" } },
  "def-dep.sheaf-condensed-ab": { note: { en: "It is a **sheaf valued in abelian groups**.", status: 'draft', basedOn: "v0.9.3#bd5eb599" } },
  "def-dep.fibered-mapping-cone": { note: { en: "The mapping cone takes $K^{n+1} \\oplus L^{n}$ termwise, a **biproduct** in an additive category.", status: 'draft', basedOn: "v0.9.3#cec4e725" } },
  "def-dep.mapping-cone-triangle": { note: { en: "A derived triangle is defined to be isomorphic to a **mapping cone** triangle.", status: 'draft', basedOn: "v0.9.3#ccc2f474" } },
  "def-dep.fibered-abelian": { note: { en: "The definition of the “direct sum $M_{1} \\oplus M_{2}$” uses $p_{k} i_{k} = 1$ and $i_{1}p_{1} + i_{2}p_{2} = 1_{M}$. **Finite products and finite coproducts coincide**.", status: 'draft', basedOn: "v0.9.3#73ddf5cb" } },
  "def-dep.equalizer-abelian": { note: { en: "In a preabelian category, every morphism has a **kernel and a cokernel**. An abelian category additionally requires all monomorphisms and epimorphisms to be regular.", status: 'draft', basedOn: "v0.9.3#62e34c2f" } },
  "def-dep.mono-abelian": { note: { en: "One criterion for an abelian category is that every **monomorphism** is regular.", status: 'draft', basedOn: "v0.9.3#ec949eb8" } },
  "def-dep.producttopo-topology": { note: { en: "The product topology is a construction on a family of **topological spaces**.", status: 'draft', basedOn: "v0.9.3#44e0b956" } },
  "def-dep.producttopo-base": { note: { en: "The product topology takes as a **basis** the family of products in which only finitely many factors are proper open subsets.", status: 'draft', basedOn: "v0.9.3#bf96ba3b" } },
  "def-dep.group-function": { note: { en: "The group operation is $G \\times G \\to G$, a **function**.", status: 'draft', basedOn: "v0.9.3#60735c1a" } },
  "def-dep.subgroup-group": { note: { en: "A subgroup is a substructure of a **group**, with the restricted operation.", status: 'draft', basedOn: "v0.9.3#5b0506cd" } },
  "def-dep.normal-group": { note: { en: "A normal subgroup must first be a subgroup of a **group**.", status: 'draft', basedOn: "v0.9.3#0d4f1d7c" } },
  "def-dep.grouphom-group": { note: { en: "A homomorphism is a map between two **groups**.", status: 'draft', basedOn: "v0.9.3#8baaf832" } },
  "def-dep.grouphom-kernel": { note: { en: "The kernel is a **normal** subgroup.", status: 'draft', basedOn: "v0.9.3#e5dc577f" } },
  "def-dep.firstiso-hom": { note: { en: "The input to the theorem is a **group homomorphism**, whose kernel and image are used.", status: 'draft', basedOn: "v0.9.3#fb4ad3d7" } },
  "def-dep.field-group": { note: { en: "A field is two **abelian groups** plus distributivity. The definition of a field is built on the definition of a group.", status: 'draft', basedOn: "v0.9.3#7ec66f99" } },
  "def-dep.normal-hausdorff": { note: { en: "Normality strengthens $T_{1}$ by requiring that closed sets can be separated.", status: 'draft', basedOn: "v0.9.3#d587c256" } },
  "def-dep.normal-closed": { note: { en: "Normality means that **disjoint closed sets** can be separated by open sets.", status: 'draft', basedOn: "v0.9.3#2af9ced8" } },
  "def-dep.urysohn-continuous": { note: { en: "The lemma yields a **continuous function** $f : X \\to [0,1]$.", status: 'draft', basedOn: "v0.9.3#79c37e3e" } },
  "def-dep.urysohn-normal": { note: { en: "The lemma says precisely that such a function exists for normal $\\iff$.", status: 'draft', basedOn: "v0.9.3#99cdf55a" } },
  "def-dep.topoab-group": { note: { en: "A topological abelian group is an **abelian group** equipped with a topology.", status: 'draft', basedOn: "v0.9.3#3ba06769" } },
  "def-dep.topoab-topology": { note: { en: "The statement that the operations are continuous requires a **topology**.", status: 'draft', basedOn: "v0.9.3#9fa51b7b" } },
  "def-dep.abtopabcond-topoab": { note: { en: "The domain of the functor is **topological abelian groups**.", status: 'draft', basedOn: "v0.9.3#22711227" } },
  "def-dep.abtopabcond-condab": { note: { en: "The target of the functor is **condensed abelian groups**.", status: 'draft', basedOn: "v0.9.3#a38a5ed3" } },
  "def-dep.conthom-topoab": { note: { en: "The proposition concerns continuous homomorphisms between two **topological abelian groups**.", status: 'draft', basedOn: "v0.9.3#0bcc731b" } },
  "def-dep.lcab-abeliancat": { note: { en: "The conclusion is that the category is preabelian but **not abelian**.", status: 'draft', basedOn: "v0.9.3#4d6a0b49" } },
  "def-dep.pontryagin-topoab": { note: { en: "The objects of the duality are **topological abelian groups**.", status: 'draft', basedOn: "v0.9.3#71f5fb11" } },
  "def-dep.pvk-topoab": { note: { en: "The theorem concerns the category of **locally compact Hausdorff abelian groups**.", status: 'draft', basedOn: "v0.9.3#c98cb4ca" } },
  "def-dep.pvk-dual": { note: { en: "The theorem says that the **dual functor** is an autoequivalence.", status: 'draft', basedOn: "v0.9.3#b9f2fd41" } },
  "def-dep.pvk-equivalence": { note: { en: "The conclusion is “autoequivalence”.", status: 'draft', basedOn: "v0.9.3#92ba6ac0" } },
  "def-dep.ring-group": { note: { en: "The additive part of a ring is an **abelian group**.", status: 'draft', basedOn: "v0.9.3#9d13838a" } },
  "def-dep.ideal-ring": { note: { en: "An ideal is a subset of a **ring** that absorbs multiplication.", status: 'draft', basedOn: "v0.9.3#06dbf802" } },
  "def-dep.ideal-quotientgroup": { note: { en: "$(I,+)$ is an additive **subgroup**. To form the quotient ring, first form the additive **quotient group**.", status: 'draft', basedOn: "v0.9.3#fb60438d" } },
  "def-dep.module-group": { note: { en: "The underlying structure of a module is an **abelian group**.", status: 'draft', basedOn: "v0.9.3#456c8868" } },
  "def-dep.module-ring": { note: { en: "A module is an action of a **ring** on an abelian group.", status: 'draft', basedOn: "v0.9.3#a6c00ab2" } },
  "def-dep.subcategory-category": { note: { en: "A subcategory takes a selection of the objects and a selection of the morphisms of a **category**.", status: 'draft', basedOn: "v0.9.3#4b10ab3d" } },
  "def-dep.preslim-limit": { note: { en: "“Preserving limits” describes the relationship between a functor and **limits**.", status: 'draft', basedOn: "v0.9.3#8831e07d" } },
  "def-dep.preslim-functor": { note: { en: "The object under discussion is a **functor**.", status: 'draft', basedOn: "v0.9.3#6244578a" } },
  "def-dep.exact-preslim": { note: { en: "Left/right exactness restricts “preserving limits” to **finite** diagrams.", status: 'draft', basedOn: "v0.9.3#59d2c4d8" } },
  "def-dep.splitexact-zeroobj": { note: { en: "A split exact sequence is the **direct sum** sequence.", status: 'draft', basedOn: "v0.9.3#5fdbd3b2" } },
  "def-dep.mono-section": { note: { en: "The definition of an isomorphism uses **sections and retractions**. A monomorphism with a section (or an epimorphism with a retraction) is an isomorphism.", status: 'draft', basedOn: "v0.9.3#1c16bbfb" } },
  "def-dep.tykhonov-compact": { note: { en: "The theorem concerns products of **compact** spaces.", status: 'draft', basedOn: "v0.9.3#65e07b32" } },
  "def-dep.tykhonov-product": { note: { en: "The product **carries the product topology**.", status: 'draft', basedOn: "v0.9.3#83282ffd" } },
  "def-dep.cechcoh-cech": { note: { en: "Čech cohomology uses the **Čech functor**.", status: 'draft', basedOn: "v0.9.3#0c0fb396" } },
  "def-dep.cartanleray-cech": { note: { en: "The first page of the spectral sequence is **Čech cohomology**.", status: 'draft', basedOn: "v0.9.3#f3717855" } },
  "def-dep.seminorm-group": { note: { en: "A seminormed abelian group is an **abelian group** equipped with a seminorm.", status: 'draft', basedOn: "v0.9.3#1585c01d" } },
  "def-dep.banach-seminorm": { note: { en: "A Banach abelian group is a **seminormed** abelian group that is separated and complete.", status: 'draft', basedOn: "v0.9.3#85155f00" } },
  "def-dep.banach-complete": { note: { en: "The “Banach” part means **complete**.", status: 'draft', basedOn: "v0.9.3#dab505c9" } },
  "def-dep.kbexact-seminorm": { note: { en: "$K$-bounded exactness is defined for complexes of **seminormed** abelian groups.", status: 'draft', basedOn: "v0.9.3#d608b348" } },
  "def-dep.kbcomp-banach": { note: { en: "The completion is a **Banach** abelian group.", status: 'draft', basedOn: "v0.9.3#61ffc92d" } },
  "def-dep.kbcomp-kbexact": { note: { en: "Both sides concern **$K$-bounded exactness**.", status: 'draft', basedOn: "v0.9.3#4190378c" } },
  "def-dep.kbimpl-kbexact": { note: { en: "The hypothesis is **$K$-bounded exactness** at both adjacent positions.", status: 'draft', basedOn: "v0.9.3#1196e159" } },
  "def-dep.kbimpl-banach": { note: { en: "Each term of the complex is a **Banach** abelian group (completeness is used to take limits of series).", status: 'draft', basedOn: "v0.9.3#7cbdfadc" } },
  "def-dep.kacyc-kbexact": { note: { en: "The hypothesis is **$K$-bounded acyclicity**.", status: 'draft', basedOn: "v0.9.3#38d7e717" } },
  "def-dep.kacyc-banach": { note: { en: "This holds only for **Banach** complexes.", status: 'draft', basedOn: "v0.9.3#b9d9f677" } },
  "def-dep.banstone-banach": { note: { en: "The coefficients are **Banach** abelian groups.", status: 'draft', basedOn: "v0.9.3#839d500c" } },
  "def-dep.banstone-stone": { note: { en: "The space is a **Stone** space.", status: 'draft', basedOn: "v0.9.3#b4d3efa9" } },
  "def-dep.tietze-normal": { note: { en: "The hypothesis is that $X$ is **normal**.", status: 'draft', basedOn: "v0.9.3#9ecaff82" } },
  "def-dep.tietze-compact": { note: { en: "The subset $K$ must be **compact**.", status: 'draft', basedOn: "v0.9.3#deec7a96" } },
  "def-dep.tietze-cont": { note: { en: "This concerns the restriction map for **continuous maps**.", status: 'draft', basedOn: "v0.9.3#63bb54bb" } },
  "def-dep.realbanach-chaus": { note: { en: "The space is **compact Hausdorff**.", status: 'draft', basedOn: "v0.9.3#95c0da5d" } },
  "def-dep.realbanach-banach": { note: { en: "The coefficients form a **real Banach space**.", status: 'draft', basedOn: "v0.9.3#b9eece8e" } },
  "def-dep.extsec-stone": { note: { en: "The formula holds only for **Stonean** spaces ($\\mathbb{Z}[S]$ is projective).", status: 'draft', basedOn: "v0.9.3#7d1ec3cf" } },
  "def-dep.bd-condab": { note: { en: "The object being decomposed is an **abelian group** in a topos ($\\mathrm{CondAb}$ is one example).", status: 'draft', basedOn: "v0.9.3#a3eb8feb" } },
  "def-dep.bdss-stone": { note: { en: "The version with test space $S$ requires $S$ to be **Stonean**.", status: 'draft', basedOn: "v0.9.3#17d78517" } },
  "def-dep.rbnd-banach": { note: { en: "The source is a **finite-dimensional real Banach space**.", status: 'draft', basedOn: "v0.9.3#13af2ed6" } },
  "def-dep.lcstr-lc": { note: { en: "This concerns **locally compact** abelian groups.", status: 'draft', basedOn: "v0.9.3#8bb5b3d7" } },
  "def-dep.lcstr-hausdorff": { note: { en: "It must also be **Hausdorff**.", status: 'draft', basedOn: "v0.9.3#aff6b558" } },
  "def-dep.lcstr-chaus": { note: { en: "The compact factor $K$ in the decomposition is a **compact Hausdorff** abelian group.", status: 'draft', basedOn: "v0.9.3#f98fed9f" } },
  "def-dep.pdcd-dual": { note: { en: "This concerns the **Pontryagin duality** functor.", status: 'draft', basedOn: "v0.9.3#17751d47" } },
  "def-dep.pdcd-chaus": { note: { en: "Duality interchanges “discrete” and “**compact Hausdorff**”.", status: 'draft', basedOn: "v0.9.3#c185532f" } },
  "def-dep.pts-dual": { note: { en: "This again concerns **Pontryagin duality**.", status: 'draft', basedOn: "v0.9.3#f71e3652" } },
  "def-dep.pts-stone": { note: { en: "The dual of a torsion group is a **Stonean** space.", status: 'draft', basedOn: "v0.9.3#6e8a3883" } },
  "def-link.norm-matnorm": { note: { en: "A matrix norm satisfies the norm axioms and is an instance of a norm on a matrix space. This is a definitional instantiation/specialization, not an implication.", status: 'draft', basedOn: "v0.9.3#a8db5e2e" } },
  "def-link.norm-induced": { note: { en: "An inner product induces a norm via $\\|v\\| = \\sqrt{\\langle v, v\\rangle}$. This is a definitional instantiation/specialization, not an implication.", status: 'draft', basedOn: "v0.9.3#1060c1cb" } },
  "def-link.topology-cr": { note: { en: "The definition of a completely regular space starts with a topological space and adds a separation condition involving continuous functions.", status: 'draft', basedOn: "v0.9.3#f0497661" } },
  "def-link.ring-intring": { note: { en: "The integer ring theorem gives the set of integers a ring structure. The set of integers itself is not part of the definition of a ring.", status: 'draft', basedOn: "v0.9.3#87b51691" } },
  "def-link.ring-matrixring": { note: { en: "The matrix ring theorem gives the set of matrices a ring structure. The set of matrices itself is not part of the definition of a ring.", status: 'draft', basedOn: "v0.9.3#e9c11913" } },
  "ana.smooth-exsphere": { note: { en: "$S^{2}$ is a concrete example of a smooth manifold.", status: 'draft', basedOn: "v0.9.3#8f2934a7" } },
  "ana.smooth-extorus": { note: { en: "$T^{2}$ is a concrete example of a smooth manifold.", status: 'draft', basedOn: "v0.9.3#0917c23c" } },
  "ana.smooth-exrp2": { note: { en: "$\\mathbb{RP}^{2}$ is a concrete example of a smooth manifold.", status: 'draft', basedOn: "v0.9.3#b403bfa8" } },
  "dep.seqlimit-fnlimit": { note: { en: "Both use the same $\\varepsilon$ language. The function version adds a layer of $\\delta$ to control how close the input gets, and Heine’s characterization **reduces** the function version to the sequence version.", status: 'draft', basedOn: "v0.9.3#3afed29d" } },
  "dep.seqlimit-cauchyseq": { note: { en: "A Cauchy sequence replaces comparisons with the limit by comparisons between terms of the sequence. The quantifier structure is the same, with $|x_n - x|$ replaced by $|x_m - x_n|$.", status: 'draft', basedOn: "v0.9.3#118ff757" } },
  "dep.interval-limitpoint": { note: { en: "A limit point is defined using “every $\\varepsilon$ neighborhood,” where the neighborhood is the open interval $(x - \\varepsilon, x + \\varepsilon)$.", status: 'draft', basedOn: "v0.9.3#d0801029" } },
  "dep.cauchyseq-criterion": { note: { en: "One side of the theorem is convergence and the other is the Cauchy sequence condition, which was just defined in this pack.", status: 'draft', basedOn: "v0.9.3#17b6c8ea" } },
  "dep.complete-realm": { note: { en: "The definition of completeness for metric spaces applies verbatim to $\\mathbb{R}$, where every Cauchy sequence converges.", status: 'draft', basedOn: "v0.9.3#00fbad69" } },
  "dep.compact-hb": { note: { en: "Heine–Borel is a criterion for **compactness** that uses the definition of a compact space.", status: 'draft', basedOn: "v0.9.3#5265eb4a" } },
  "dep.sym-real-def-limsup-liminf": { note: { en: "The statement concerns real numbers $\\mathbb{R}$ (symbol dependency)", status: 'draft', basedOn: "v0.9.3#0453d27b" } },
  "dep.continuous-uniform": { note: { en: "Moving $\\delta$ before $\\forall x$ in the definition of continuity gives uniform continuity. Both definitions use the same $\\varepsilon$-$\\delta$ language.", status: 'draft', basedOn: "v0.9.3#9b0b9b49" } },
  "dep.compact-continuousbounded": { note: { en: "The proof uses compactness only to extract a finite subcover from any open cover (or, equivalently, to use sequential compactness).", status: 'draft', basedOn: "v0.9.3#64d7ce74" } },
  "dep.continuous-discontinuity": { note: { en: "A point of discontinuity is a point where the function is not continuous. Such points are classified using one-sided limits, which are defined in terms of function limits.", status: 'draft', basedOn: "v0.9.3#66cc8acd" } },
  "dep.derivative-localextremum": { note: { en: "A local extremum compares function values only in a neighborhood of $x_0$, so it is a purely order-theoretic concept. Its connection with derivatives (Fermat’s lemma) is the starting point of differential calculus.", status: 'draft', basedOn: "v0.9.3#acef3b2b" } },
  "dep.interval-partition": { note: { en: "A partition is a finite selection of points from a closed interval, and $\\Delta x_i$ is the length of a subinterval. Both concern only intervals.", status: 'draft', basedOn: "v0.9.3#915e23d4" } },
  "dep.partition-riemannsum": { note: { en: "A Riemann sum uses a fixed partition and adds up $f(\\xi_i)\\Delta x_i$ using the tagged points.", status: 'draft', basedOn: "v0.9.3#a66e7a89" } },
  "dep.riemannsum-improper": { note: { en: "An improper integral is a limit of ordinary Riemann integrals, so the function must first be integrable on each segment of its domain.", status: 'draft', basedOn: "v0.9.3#4f5796ca" } },
  "dep.series-absolute": { note: { en: "Absolute convergence is a property **of another series** ($\\sum |a_n|$), a series with positive terms. It uses the same definition of series convergence.", status: 'draft', basedOn: "v0.9.3#65324148" } },
  "dep.absolute-conditional": { note: { en: "Conditional convergence = convergence **and** failure to converge absolutely, so its definition presupposes the term “absolute convergence”.", status: 'draft', basedOn: "v0.9.3#7f4e9197" } },
  "def-link.bern-power": { note: { en: "The generating function $t/(e^t-1)$ for the Bernoulli numbers is a formal power series. Analytically, it converges within $|t|<2\\pi$.", status: 'draft', basedOn: "v0.9.3#b7cfd8af" } },
  "def-link.bern-exp": { note: { en: "The denominator $e^t-1$ of the generating function uses the exponential function.", status: 'draft', basedOn: "v0.9.3#706095db" } },
  "dep.sym-complex-def-absolute-convergence": { note: { en: "The statement concerns complex numbers $\\mathbb{C}$ (symbol dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.seqlimit-pointwise": { note: { en: "Pointwise convergence means that “for each fixed $x$, the sequence $f_n(x)$ converges in the original sense.” It applies the notion of a sequence limit at each point.", status: 'draft', basedOn: "v0.9.3#1022939e" } },
  "dep.pointwise-uniform": { note: { en: "The two definitions use the same $\\varepsilon$-$N$ language and differ only in the order of $\\exists N$ and $\\forall x$.", status: 'draft', basedOn: "v0.9.3#9d1e9da5" } },
  "dep.series-powerseries": { note: { en: "A power series is a series of functions with coefficients $a_n (x - x_0)^{n}$. Once $x$ is fixed, it is a numerical series.", status: 'draft', basedOn: "v0.9.3#b027af46" } },
  "dep.powerseries-exp": { note: { en: "The series for $\\exp$, namely $\\sum z^{n}/n!$, is a power series with radius of convergence $+\\infty$.", status: 'draft', basedOn: "v0.9.3#7c61f159" } },
  "dep.powerseries-trig": { note: { en: "$\\cos$ and $\\sin$ are likewise defined by power series, retaining only the even-degree / odd-degree terms.", status: 'draft', basedOn: "v0.9.3#8de95728" } },
  "dep.exp-log": { note: { en: "$\\log$ is defined as the inverse of $\\exp$ (restricted to $\\mathbb{R}$), so its existence follows from the monotonicity of $\\exp$.", status: 'draft', basedOn: "v0.9.3#264e979e" } },
  "def-link.fps-power": { note: { en: "An analytic power series is a formal power series with the added condition that it converges in some neighborhood. A formal power series drops the convergence requirement and retains only the coefficients.", status: 'draft', basedOn: "v0.9.3#c0c3c8d4" } },
  "dep.sym-complex-def-power-series": { note: { en: "The statement concerns complex numbers $\\mathbb{C}$ (symbol dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.sym-complex-def-exp-function": { note: { en: "The statement concerns complex numbers $\\mathbb{C}$ (symbol dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.absconv-weierstrass-m": { note: { en: "The conclusion asserts that the series converges absolutely", status: 'draft', basedOn: "v0.9.3#29de0fb7" } },
  "def-link.abs-fn-limit": { note: { en: "In the $\\varepsilon$-$\\delta$ definition of a function limit, both inequalities involve absolute values.", status: 'draft', basedOn: "v0.9.3#4def8171" } },
  "def-link.abs-continuous": { note: { en: "The definition of continuity expresses “closeness” using $|x - x_0| < \\delta$ and $|f(x) - f(x_0)| < \\varepsilon$.", status: 'draft', basedOn: "v0.9.3#e77b42f0" } },
  "def-link.abs-cauchy-seq": { note: { en: "A Cauchy sequence requires the distance $|x_m - x_n|$ between any two terms to be controllable.", status: 'draft', basedOn: "v0.9.3#0a25382d" } },
  "def-link.abs-uniform-conv": { note: { en: "Uniform convergence uses $\\sup_x |f_n(x) - f(x)| \\to 0$ as its criterion, with absolute value at its core.", status: 'draft', basedOn: "v0.9.3#b303c845" } },
  "def-link.abs-squeeze": { note: { en: "Writing the conclusion of the squeeze theorem as $|x_n - L| < \\varepsilon$ relies on passing between absolute values and order inequalities.", status: 'draft', basedOn: "v0.9.3#c4f06e49" } },
  "def-link.abs-cauchy-criterion": { note: { en: "Both sides of the Cauchy criterion are $\\varepsilon$-$N$ statements about absolute differences.", status: 'draft', basedOn: "v0.9.3#5de5103f" } },
  "def-link.abs-bw": { note: { en: "Convergence of a subsequence is still expressed by $|x_{n_k} - x| < \\varepsilon$.", status: 'draft', basedOn: "v0.9.3#6b199592" } },
  "def-link.abs-limit-arithmetic": { note: { en: "The proofs for the four arithmetic operations estimate $|f(x) - A|$ and $|g(x) - B|$ throughout and also use $|xy| = |x||y|$ (`prop.abs-properties`).", status: 'draft', basedOn: "v0.9.3#654b0c78" } },
  "def-link.abs-metric": { note: { en: "The axioms of a metric space are abstracted from $d(x, y) = |x - y|$, with positive definiteness, symmetry, and the triangle inequality corresponding one by one.", status: 'draft', basedOn: "v0.9.3#6325b58e" } },
  "def-link.abs-riemann": { note: { en: "The definition of Riemann integrability requires $|S(f, P, \\xi) - I| < \\varepsilon$ to hold for all partitions and tags.", status: 'draft', basedOn: "v0.9.3#cf94faeb" } },
  "def-link.abs-integral-order": { note: { en: "The integral estimate hinges on $\\left|\\int_a^b f\\right| \\le \\int_a^b |f|$, with absolute values on both sides.", status: 'draft', basedOn: "v0.9.3#bcbc60c2" } },
  "def-link.abs-absolute-conv": { note: { en: "Absolute convergence means $\\sum |a_n| < \\infty$. The proof bounds the partial sums using the triangle inequality.", status: 'draft', basedOn: "v0.9.3#42ce699b" } },
  "def-link.abs-essential-sup": { note: { en: "The essential upper bound is the essential supremum of $|f|$. Absolute value is what gives “size” its meaning here.", status: 'draft', basedOn: "v0.9.3#3a431fe7" } },
  "def-link.power-nat": { note: { en: "Integer powers are defined recursively using multiplication on the natural numbers. In $a^{n+1} = a^{n} \\cdot a$, the $\\cdot$ is the multiplication of `def.nat-arith`.", status: 'draft', basedOn: "v0.9.3#b23f14f3" } },
  "def-link.power-series-power": { note: { en: "In the power series $\\sum a_n (x - x_0)^{n}$, the $n$th power is the integer power defined in `def.power`.", status: 'draft', basedOn: "v0.9.3#67e7870b" } },
  "def-link.power-root-test": { note: { en: "The root test compares $a_n$ with $q^{n}$ using integer powers ($q$ is fixed and $n$ varies).", status: 'draft', basedOn: "v0.9.3#4815000c" } },
  "def-link.power-geometric": { note: { en: "The general term $q^{n}$ of a geometric series is an integer power. The partial sum formula also uses only the exponent laws.", status: 'draft', basedOn: "v0.9.3#0fa9a8b4" } },
  "def-link.nthroot-complex": { note: { en: "The complex modulus $|z| = \\sqrt{a^{2} + b^{2}}$ uses a real square root. Without the existence of nth roots, this definition is vacuous.", status: 'draft', basedOn: "v0.9.3#b2a44bf0" } },
  "def-link.nthroot-induced-norm": { note: { en: "The norm $\\|v\\| = \\sqrt{\\langle v, v\\rangle}$ induced by an inner product also requires a real square root.", status: 'draft', basedOn: "v0.9.3#42165e47" } },
  "ana.nthroot-p-series": { note: { en: "The family of $p$ series is a standard example of the limits of the root test. For $a_{n} = n^{-p}$, one always has $\\alpha = \\lim \\sqrt[n]{n^{-p}} = 1$, so the test is inconclusive, while the Cauchy condensation test decides convergence or divergence of the $p$ series itself. The two tests are separate tools applied to the same family of series, with no dependency between them.", status: 'draft', basedOn: "v0.9.3#b4ce331e" } },
  "def-link.profinite-measure": { note: { en: "The measure is defined on a **profinite set**. “Continuous” for $C(S,\\mathbb{Z})$ refers precisely to the profinite topology.", status: 'draft', basedOn: "v0.9.3#02b722ee" } },
  "dep.cat-ab-prop-free-solid-solid": { note: { en: "The statement takes the category $\\mathbf{Ab}$ of abelian groups as the ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "dep.cat-ab-thm-solid-abelian": { note: { en: "The statement takes the category $\\mathbf{Ab}$ of abelian groups as the ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "dep.cat-ab-thm-solid-derived": { note: { en: "The statement takes the category $\\mathbf{Ab}$ of abelian groups as the ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "dep.za-analytic-ring": { note: { en: "Zariski's Main Theorem is stated for analytic rings (complete Noetherian rings).", status: 'draft', basedOn: "v0.9.3#e950dbd2" } },
  "dep.coherent-za": { note: { en: "The proof of coherent duality invokes Zariski's Main Theorem to handle the structure of analytic rings.", status: 'draft', basedOn: "v0.9.3#ec1deb12" } },
  "def-link.analyticring-dual": { note: { en: "In the six-functor formalism, $D(X)$ is the solid sheaf $D(\\mathcal{O}_{X,\\blacksquare})$, that is, a solid module over an analytic ring.", status: 'draft', basedOn: "v0.9.3#cbaaf995" } },
  "def-link.coherent-affine-global": { note: { en: "The affine version of $f_!$ is the local model for the global definition. The two agree on affine open sets.", status: 'draft', basedOn: "v0.9.3#bf04e38e" } },
  "def-link.solid-criterion-abelian": { note: { en: "The lemma's first hypothesis is that $\\mathcal{A}$ is an abelian category. Kernels, cokernels, complexes, and homology are all taken in this category.", status: 'draft', basedOn: "v0.9.3#fc9ae91e" } },
  "def-link.solid-criterion-projective": { note: { en: "The requirement is that $\\mathcal{A}_0$ consist of **compact projective** objects. Compactness lets $\\operatorname{RHom}(F(S), -)$ commute with direct sums, and projectivity lets resolutions be transferred back and forth.", status: 'draft', basedOn: "v0.9.3#b6d654e2" } },
  "def-link.solid-criterion-generator": { note: { en: "The requirement is that $\\mathcal{A}_0$ be a **family of generators**. Otherwise, $\\mathcal{A}_F$ may contain nonzero objects invisible to all $F(S)$, and the completion subcategory would no longer be determined by $F$.", status: 'draft', basedOn: "v0.9.3#dd1d265f" } },
  "def-link.productmeasure-premeasure": { note: { en: "The assignment $\\mu_{0}$ on rectangles is a premeasure.", status: 'draft', basedOn: "v0.9.3#443dbb48" } },
  "def-link.productmeasure-sigma": { note: { en: "The product measure is defined on the product $\\sigma$-algebra $\\mathcal{M} \\otimes \\mathcal{N}$.", status: 'draft', basedOn: "v0.9.3#205e1c75" } },
  "def-link.section-props": { note: { en: "The properties of sections under operations are verified directly.", status: 'draft', basedOn: "v0.9.3#3afd3ec6" } },
  "def-link.section-fubini": { note: { en: "Fubini's theorem is stated entirely in terms of sections.", status: 'draft', basedOn: "v0.9.3#8e0f1752" } },
  "def-link.productmeasure-fubini": { note: { en: "Multiple integration is integration with respect to $\\mu \\times \\nu$.", status: 'draft', basedOn: "v0.9.3#1b24858a" } },
  "def-link.integrable-fubini": { note: { en: "Part (b) of Fubini's theorem uses $L^{1}(\\mu \\times \\nu )$.", status: 'draft', basedOn: "v0.9.3#ef5bc347" } },
  "def-link.pair-section": { note: { en: "The set-builder expression $E_x = \\{ y : (x, y) \\in E \\}$ contains the **ordered pair** $(x, y)$.", status: 'draft', basedOn: "v0.9.3#3db65e74" } },
  "def-link.measurable-function-section-measurable": { note: { en: "**(b)** says precisely that sections of a measurable **function** are measurable.", status: 'draft', basedOn: "v0.9.3#7e235e54" } },
  "def-link.product-sigma-section-measurable": { note: { en: "In the hypothesis $E \\in \\mathcal{M} \\otimes \\mathcal{N}$, $\\otimes$ is the **product $\\sigma$-algebra**.", status: 'draft', basedOn: "v0.9.3#94202cb7" } },
  "def-link.tensormod-module": { note: { en: "The inputs to the tensor product are modules. Take $M$ to be a right module and $N$ to be a left module. The third relation imposed in the quotient matches the two module actions.", status: 'draft', basedOn: "v0.9.3#ff923178" } },
  "def-link.tensormod-bilinear": { note: { en: "For modules, “bilinear” becomes “balanced biadditive.” The extra relation $B(m r, n) = B(m, r n)$ moves a scalar from one side to the other. Over a field it holds automatically, so tensor products of vector spaces have no need for it.", status: 'draft', basedOn: "v0.9.3#4fd991b0" } },
  "def-link.flat-exactfunctor": { note: { en: "Flatness requires $(-) \\otimes_{R} N$ to be an exact functor. Since the functor is right exact, exactness is equivalent to left exactness, so the definition can simply require preservation of monomorphisms.", status: 'draft', basedOn: "v0.9.3#05ecafb7" } },
  "def-link.injmodule-projectiveobj": { note: { en: "An injective object is what a projective object becomes in $\\mathcal{C}^{\\mathrm{op}}$. Reversing every arrow in the lifting diagram gives the extension diagram.", status: 'draft', basedOn: "v0.9.3#37e5214b" } },
  "def-link.injectivesplitting-splitexact": { note: { en: "“Every monomorphism from an injective object splits” is phrased in terms of split short exact sequences. The sequence $0 \\to I \\to M \\to M_{2} \\to 0$ splits if and only if $I \\rightarrowtail M$ has a retraction.", status: 'draft', basedOn: "v0.9.3#36dfae0d" } },
  "def-link.baer-ideal": { note: { en: "Baer's criterion consists entirely in replacing an arbitrary monomorphism $A \\rightarrowtail B$ with an ideal inclusion $J \\rightarrowtail R$, reducing the test from submodules to ideals.", status: 'draft', basedOn: "v0.9.3#1ead95b0" } },
  "def-link.divisible-pid": { note: { en: "The two sides of the proposition belong to different worlds. The left is categorical (injectivity), and the right is group-theoretic (divisibility). Over a principal ideal domain they coincide, forming the shortest bridge between homological algebra and abelian group theory.", status: 'draft', basedOn: "v0.9.3#fb362594" } },
  "dep.n12-tensormod-scalarext": { note: { en: "The universal property of the tensor product gives the unique map from $S\\otimes_R M \\to P$ that is $S$-linear.", status: 'draft', basedOn: "v0.9.3#e885c277" } },
  "dep.flat-equiv-flatmodule": { note: { en: "The equivalent conditions for flatness start from the definition of a flat module.", status: 'draft', basedOn: "v0.9.3#71a5ee31" } },
  "dep.free-flat-flatmodule": { note: { en: "The proof that free modules are flat uses the universal-property characterization of flat modules.", status: 'draft', basedOn: "v0.9.3#f05ac8e5" } },
  "dep.cat-ab-prop-tensor-functor-properties": { note: { en: "The statement takes the category $\\mathbf{Ab}$ of abelian groups as the ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "dep.cat-ab-thm-hom-tensor-adjunction-mod": { note: { en: "The statement takes the category $\\mathbf{Ab}$ of abelian groups as the ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "dep.cat-ab-prop-tensor-right-exact": { note: { en: "The statement takes the category $\\mathbf{Ab}$ of abelian groups as the ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "def-link.homotopy-res": { note: { en: "“Homotopy equivalence” in the conclusion uses the definition of chain homotopy.", status: 'draft', basedOn: "v0.9.3#74ccbb6a" } },
  "def-link.pdvan-projobj": { note: { en: "One of the equivalent conditions is that the $n$th syzygy is projective, which uses the definition of a projective object.", status: 'draft', basedOn: "v0.9.3#1dce27c0" } },
  "def-link.flat-module": { note: { en: "Flatness concerns exactness of the tensor functor in the category of $R$-modules.", status: 'draft', basedOn: "v0.9.3#5d364fef" } },
  "def-link.torflat-flat": { note: { en: "The criterion characterizes flatness itself.", status: 'draft', basedOn: "v0.9.3#d265872c" } },
  "dep.cat-ab-def-flat-module": { note: { en: "The statement takes the category $\\mathbf{Ab}$ of abelian groups as the ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "def-link.groupcoh-h1crossed": { note: { en: "First cohomology means $H^{1}(G, M)$, the **first** right derived functor of the invariants functor. The name applies only to this functor.", status: 'draft', basedOn: "v0.9.3#d8359ca8" } },
  "def-link.skyscraper-stalks": { note: { en: "To compute the stalks, first determine what value the sheaf takes on each open set. A skyscraper sheaf takes only the two values $A$ and $0$, so its stalks can only be $A$ or $0$.", status: 'draft', basedOn: "v0.9.3#d6050236" } },
  "def-link.skyscraper-inj": { note: { en: "Injectivity is tested for this particular sheaf (the pushforward sheaf constructed from $i_{x,*}$), so the definition of a skyscraper sheaf comes first.", status: 'draft', basedOn: "v0.9.3#6be0136c" } },
  "def-link.exactcouple-ss": { note: { en: "A spectral sequence is the sequence of homology pages of the **derived sequence of an exact couple**. The bidegree pattern of $d_{r}$ comes from the exact couple.", status: 'draft', basedOn: "v0.9.3#e304a107" } },
  "dep.cat-ab-prop-skyscraper-injective": { note: { en: "The statement takes the category $\\mathbf{Ab}$ of abelian groups as the ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "dep.pcp-normal-shrink": { note: { en: "Each shrinking step uses normality to insert an intermediate set between a closed set and an open set containing it. Normality alone suffices for this step.", status: 'draft', basedOn: "v0.9.3#5d65d5d7" } },
  "dep.pcp-hausdorff-pcn": { note: { en: "The theorem requires “paracompact **and** Hausdorff.” Without the Hausdorff condition, paracompactness fails to imply normality (the Sierpiński space is a counterexample).", status: 'draft', basedOn: "v0.9.3#61f4f587" } },
  "dep.pcp-paracompact-pcn": { note: { en: "The other hypothesis is paracompactness. It is used only to take a locally finite open refinement.", status: 'draft', basedOn: "v0.9.3#d7ec21cd" } },
  "dep.pcp-existing-prop-paracompact": { note: { en: "The first part of that proposition concerns the combination “paracompact Hausdorff,” so it depends on the definition in this node.", status: 'draft', basedOn: "v0.9.3#bba10aa8" } },
  "dep.pcp-metric-metrizable": { note: { en: "Metrizable means “homeomorphic to some metric space.” This node transfers the definition of a metric space along a homeomorphism.", status: 'draft', basedOn: "v0.9.3#e5d6f832" } },
  "dep.pcp-base-second": { note: { en: "Second countability adds a countability condition to the notion of a base (the base has countably many members).", status: 'draft', basedOn: "v0.9.3#4bbbcdc0" } },
  "dep.pcp-second-urysohn": { note: { en: "One of the theorem's hypotheses is second countability (together with regularity).", status: 'draft', basedOn: "v0.9.3#4223582f" } },
  "dep.pcp-metrizable-urysohn": { note: { en: "The theorem concludes that the space is metrizable.", status: 'draft', basedOn: "v0.9.3#cf7db832" } },
  "dep.pcp-normal-urysohn-metrization": { note: { en: "The proof uses the intermediate step “regular $+$ Lindelöf $\\implies$ normal” to obtain the hypothesis of Urysohn's lemma.", status: 'draft', basedOn: "v0.9.3#4eaf9183" } },
  "dep.pcp-metrizable-ns": { note: { en: "Metrizability is the conclusion of the theorem. The converse, “metrizable $\\implies$ has a $\\sigma$-locally finite base,” is also half of the theorem, so an unqualified reference to the equivalence points to this node in both directions.", status: 'draft', basedOn: "v0.9.3#43386ef8" } },
  "def-link.pcn-normal": { note: { en: "The theorem concludes that the space is normal. The proof ends by verifying that two disjoint closed sets can be separated by open sets, exactly as the definition of normality requires.", status: 'draft', basedOn: "v0.9.3#f1f7ead8" } },
  "def-link.divisible-group": { note: { en: "Divisibility means “for every $n$, one can take a $n$th root,” which first requires a group operation.", status: 'draft', basedOn: "v0.9.3#0c847c28" } },
  "def-link.exact-couple-abelian": { note: { en: "An exact couple consists of two families of objects in an abelian category together with maps of degree $+1$. Exactness is expressed in terms of kernels and images in that category.", status: 'draft', basedOn: "v0.9.3#5449c62e" } },
  "def-link.exact-couple-complex": { note: { en: "It computes the homology of a complex page by page, so the complex and its differential are its inputs.", status: 'draft', basedOn: "v0.9.3#7f3df0cc" } },
  "def-link.etale-space-topology": { note: { en: "An étale space is a topological space equipped with a local homeomorphism, so the topology comes first.", status: 'draft', basedOn: "v0.9.3#a87e72de" } },
  "def-link.paracompact-cech": { note: { en: "The theorem assumes “paracompact + Hausdorff.” Paracompactness supplies a locally finite refinement, which lets one assemble a partition of unity so that Čech cohomology and sheaf cohomology agree.", status: 'draft', basedOn: "v0.9.3#96437055" } },
  "def-link.tensor-universal": { note: { en: "The universal property concerns the object $M\\otimes_R N$ itself. Its construction (quotienting by the bilinearity relations) comes before its universal property for bilinear maps.", status: 'draft', basedOn: "v0.9.3#7992243c" } },
  "def-link.curvature-tensor": { note: { en: "The Riemann curvature tensor measures the difference between parallel transport along two paths and is defined from the connection $R(X,Y)=\\nabla_X\\nabla_Y-\\nabla_Y\\nabla_X-\\nabla_{[X,Y]}$.", status: 'draft', basedOn: "v0.9.3#e4dd99a5" } },
  "dep.dg-ext-inner": { note: { en: "Normalizing $\\langle r_{u}, r_{u}\\rangle$, $\\lVert r_{u}\\times r_{v}\\rVert$, and $n$ relies on the inner product on $\\mathbb{R}^{3}$. Every step of the frame construction uses it.", status: 'draft', basedOn: "v0.9.3#b4346dda" } },
  "dep.dg-ext-eigen": { note: { en: "The principal curvatures are the eigenvalues of $W$ (equivalently, of $h$ relative to $g$). The principal directions are eigenvectors. The spectral theorem identifies the extremal directions with the eigendirections.", status: 'draft', basedOn: "v0.9.3#513898db" } },
  "dep.dg-surface-frame": { note: { en: "The frame moves along the surface. Take $e_{3}$ to be the normal from the Gauss map, and let $e_{1}, e_{2}$ span the tangent plane. The regular parametrization supplies all three.", status: 'draft', basedOn: "v0.9.3#80e37850" } },
  "dep.dg-frame-conn": { note: { en: "The connection forms are the coefficients obtained by **expanding $\\mathrm{d}e_{i}$ in the frame**. They require a frame.", status: 'draft', basedOn: "v0.9.3#c67194fe" } },
  "dep.dg-frame-adapt": { note: { en: "An adapted frame is a particular choice of moving frame on a surface ($e_{3} = n$). The lemma's conclusions all concern this choice.", status: 'draft', basedOn: "v0.9.3#e5e5d779" } },
  "dep.dg-conn-struct": { note: { en: "The two sets of objects in the structure equations are exactly $\\omega^{i}$ and $\\omega^{i}_{\\ j}$. These are the only quantities in the theorem itself.", status: 'draft', basedOn: "v0.9.3#cfe432ef" } },
  "dep.dg-frame-I": { note: { en: "In $I = (\\omega^{1})^{2}+(\\omega^{2})^{2}$, the $\\omega^{i}$ are the dual coframe. Writing the expression in parameters $u, v$ also requires $\\mathrm{d}r$, which the coframe expression dispenses with.", status: 'draft', basedOn: "v0.9.3#de3c4205" } },
  "dep.dg-frame-W": { note: { en: "For $W$, the matrix $(h_{ij})$ is written relative to the frame $e_{1}, e_{2}$. Changing the frame only gives a similarity/congruence transformation and preserves the eigenvalues.", status: 'draft', basedOn: "v0.9.3#93645f4d" } },
  "dep.dg-W-II": { note: { en: "The identity $II(v,w) = \\langle W(\\mathrm{d}r(v)), \\mathrm{d}r(w)\\rangle$ expresses the second fundamental form as the quadratic form of the shape operator relative to $I$.", status: 'draft', basedOn: "v0.9.3#d960c642" } },
  "dep.dg-II-gauss": { note: { en: "On the right-hand side of the Gauss equation, $c_{ij}$ and $h_{ij}$ are precisely the coefficients of the second fundamental form ($II = \\sum h_{ij}\\omega^{i}\\omega^{j}$).", status: 'draft', basedOn: "v0.9.3#481ec252" } },
  "dep.dg-II-codazzi": { note: { en: "Codazzi states that the covariant derivative of $II$ is symmetric. The object in question is the second fundamental form itself.", status: 'draft', basedOn: "v0.9.3#f69d92bd" } },
  "dep.dg-W-principal": { note: { en: "Principal curvatures are defined as the eigenvalues of $W$. Orthogonal principal directions require $W$ to be self-adjoint.", status: 'draft', basedOn: "v0.9.3#205b79cf" } },
  "dep.dg-principal-rodrigues": { note: { en: "Rodrigues' theorem translates “principal direction” into “eigenvector of $W$.” The two formulations express the same definition.", status: 'draft', basedOn: "v0.9.3#3d2effb3" } },
  "dep.adapted-connection": { note: { en: "The connection forms of an adapted frame lie among the tangential forms.", status: 'draft', basedOn: "v0.9.3#20b7ef99" } },
  "dep.christoffel-geodesic": { note: { en: "The coefficients of the quadratic terms in the geodesic equation are $\\Gamma^{k}_{ij}$. The invariant geodesic equation is $\\nabla_{\\dot\\gamma}\\dot\\gamma = 0$, and its coordinate form relies entirely on $\\Gamma$.", status: 'draft', basedOn: "v0.9.3#956e9abd" } },
  "dep.geodesic-gcurv": { note: { en: "Geodesic curvature measures deviation from geodesics. Using the family of curves given by $k_{g} = 0$ as a reference, $k_{g}$ measures how far a curve departs from them.", status: 'draft', basedOn: "v0.9.3#be504c39" } },
  "dep.curv-gauss": { note: { en: "Gaussian curvature is the normalization of the sole independent component of the curvature tensor in two dimensions, as given by $K = R_{1221}/\\det(g)$. The definition requires the curvature tensor.", status: 'draft', basedOn: "v0.9.3#277a04bb" } },
  "dep.iff-christoffel": { note: { en: "The formula for the Christoffel symbols contains only $g_{ij}$ and $\\partial_{k}g_{ij}$, and $g_{ij}$ is the coefficient matrix of $I$.", status: 'draft', basedOn: "v0.9.3#81f04be1" } },
  "dep.frame-christoffel": { note: { en: "The proposition expresses the connection coefficients in an orthonormal frame, using the moving frame itself.", status: 'draft', basedOn: "v0.9.3#1e80eda0" } },
  "dep.conn-christoffel": { note: { en: "In the proposition, $\\omega^{k}_{j}$ denotes the connection forms. The entire proposition says that $\\omega$ and $\\Gamma$ represent the same thing in two different frames.", status: 'draft', basedOn: "v0.9.3#3b9140b8" } },
  "dep.principal-liouville": { note: { en: "The notes on Liouville's formula use the principal curvatures $k_{1},k_{2}$ to rule out a common incorrect simplification, so they must refer to principal curvatures here.", status: 'draft', basedOn: "v0.9.3#7fd3b552" } },
  "dep.tu-inner-arclength": { note: { en: "The arc length integrand $\\lVert\\gamma'\\rVert = \\sqrt{\\langle\\gamma',\\gamma'\\rangle}$ is the norm induced by the inner product on $\\mathbb{R}^{3}$.", status: 'draft', basedOn: "v0.9.3#f0374026" } },
  "dep.tu-arclength-frenet": { note: { en: "The formulas use derivatives **with respect to arc length**. Switching to an arbitrary parameter introduces a factor of $\\lVert\\gamma'\\rVert$, and the resulting form is no longer a skew-symmetric matrix.", status: 'draft', basedOn: "v0.9.3#7105c180" } },
  "dep.tu-exterior-form": { note: { en: "At each point one has $\\omega_{p}\\in\\bigwedge^{k}(\\mathbb{R}^{n})^{\\ast}$. The wedge product, graded commutativity, and dimension $\\binom{n}{k}$ all come from exterior algebra.", status: 'draft', basedOn: "v0.9.3#5b450bf9" } },
  "dep.tu-altform-form": { note: { en: "Alternation distinguishes forms from general multilinear maps. The value is zero whenever two arguments coincide, reducing the number of components from $n^{k}$ to $\\binom{n}{k}$.", status: 'draft', basedOn: "v0.9.3#e3ad5d00" } },
  "dep.tu-form-exterior-d": { note: { en: "The definition of $\\mathrm{d}$ takes the total differential of the coefficients and wedges it with $\\mathrm{d}x^{I}$. The degree of the form is required to define $\\mathrm{d}$.", status: 'draft', basedOn: "v0.9.3#ca8fc9d5" } },
  "dep.tu-form-pullback": { note: { en: "Pullback acts pointwise on alternating $k$-linear forms, so it preserves degree and wedge products. The objects in question are differential forms.", status: 'draft', basedOn: "v0.9.3#924fa4a5" } },
  "dep.tu-d-pullback": { note: { en: "The identity $F^{\\ast}\\mathrm{d} = \\mathrm{d}F^{\\ast}$ relates exterior differentiation to pullback and formally expresses the coordinate independence of $\\mathrm{d}$.", status: 'draft', basedOn: "v0.9.3#a84f49dc" } },
  "dep.tu-topology-manifold": { note: { en: "A manifold is first of all a **topological space**. In the definition of a chart, $U$ must be open and $\\varphi$ must be a homeomorphism.", status: 'draft', basedOn: "v0.9.3#c696c4ce" } },
  "dep.tu-hausdorff-manifold": { note: { en: "The Hausdorff condition is one of the two technical hypotheses. It ensures uniqueness of limits (otherwise “$\\gamma'(0)$” would be meaningless).", status: 'draft', basedOn: "v0.9.3#2712f7ce" } },
  "dep.tu-secondcountable-manifold": { note: { en: "The other technical hypothesis is second countability, which gives paracompactness and partitions of unity so that local metrics and forms can be assembled into global ones.", status: 'draft', basedOn: "v0.9.3#3df1a37d" } },
  "dep.tu-homeo-manifold": { note: { en: "A chart is a homeomorphism from an open set to an open subset of $\\mathbb{R}^{n}$. A smooth structure imposes an additional requirement on top of the homeomorphisms.", status: 'draft', basedOn: "v0.9.3#f5c0f5fd" } },
  "dep.tu-manifold-tangent": { note: { en: "The definition of tangent vectors uses charts. The chain rule for transition maps gives the chart independence of tangency.", status: 'draft', basedOn: "v0.9.3#b66936c6" } },
  "dep.tu-partial-tangent": { note: { en: "The coordinate basis vector $\\partial_{i}(p)$ points in the direction in which only the $i$th coordinate varies. In the chart, it is the partial derivative.", status: 'draft', basedOn: "v0.9.3#b4d75dc1" } },
  "dep.tu-inner-riemannian": { note: { en: "A Riemannian metric assigns an inner product to each point, carrying over symmetry, bilinearity, and positive definiteness verbatim.", status: 'draft', basedOn: "v0.9.3#fa0a2b9d" } },
  "dep.tu-tangent-riemannian": { note: { en: "The inner product is defined on $T_{p}M$, so the tangent space comes first. Smooth variation is stated in terms of vector fields.", status: 'draft', basedOn: "v0.9.3#aab756eb" } },
  "dep.tu-tangent-connection": { note: { en: "Covariant differentiation acts on vector fields, whose values at each point lie in $TM$. A connection is a rule for differentiation on $TM$.", status: 'draft', basedOn: "v0.9.3#94879fcd" } },
  "dep.tu-connection-curvature": { note: { en: "The curvature operator is the commutator $[\\nabla_{X},\\nabla_{Y}]-\\nabla_{[X,Y]}$ of the connection. Both $\\Gamma$ and $\\omega$ are simply its coordinate expressions.", status: 'draft', basedOn: "v0.9.3#0ab40c71" } },
  "dep.tu-curv-symmetries": { note: { en: "The symmetries are properties of the curvature tensor itself. This node supplies the proof and counts the independent components.", status: 'draft', basedOn: "v0.9.3#0308b7d0" } },
  "dep.tu-form-integral": { note: { en: "The integrand is a top-degree form. The definition of integration uses verbatim the description “$k$-form = alternating form + smooth coefficients.”", status: 'draft', basedOn: "v0.9.3#7f4b3d8d" } },
  "dep.tu-integral-stokes": { note: { en: "Both sides of the theorem are integrals of forms. The equation requires the definition of $\\int_{M}\\omega$.", status: 'draft', basedOn: "v0.9.3#68905a1a" } },
  "dep.tu-d-stokes": { note: { en: "The left-hand side of the theorem is $\\mathrm{d}\\omega$. The statement of Stokes' theorem requires the exterior derivative.", status: 'draft', basedOn: "v0.9.3#1e28c182" } },
  "ana.n12-riemannmetric-bundlemetric": { note: { en: "The same convex combination argument gives a bundle metric upon replacing $TM$ with an arbitrary vector bundle.", status: 'draft', basedOn: "v0.9.3#e7a2d606" } },
  "dep.sym-real-def-smooth-manifold": { note: { en: "The statement concerns the real numbers $\\mathbb{R}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#0453d27b" } },
  "dep.vfield-riemannian": { note: { en: "The smoothness condition must be checked for arbitrary smooth vector fields X,Y, so it presupposes the definition of a vector field", status: 'draft', basedOn: "v0.9.3#9be56cf9" } },
  "def-link.measure-ac": { note: { en: "The reference $\\mu$ in absolute continuity is an actual measure.", status: 'draft', basedOn: "v0.9.3#5cb836a7" } },
  "def-link.ac-rn": { note: { en: "In $L$–$R$–$N$, the $\\rho \\ll \\mu$ denotes absolute continuity.", status: 'draft', basedOn: "v0.9.3#161cf4de" } },
  "def-link.integral-ac": { note: { en: "“$\\nu$ finite $\\iff f \\in L^{1}(\\mu )$” uses the definition of integrability.", status: 'draft', basedOn: "v0.9.3#36da6ad5" } },
  "def-link.holomorphic-complex": { note: { en: "For complex differentiability, the difference quotient takes values in $\\mathbb{C}$, and the approach in $|h| \\to 0$ is **two-dimensional**. This is precisely what distinguishes complex differentiability from real differentiability.", status: 'draft', basedOn: "v0.9.3#d44a45de" } },
  "def-link.holomorphic-derivative": { note: { en: "The formula is identical to the difference quotient for the real derivative, with the sole difference that $h$ takes complex values. In the real case, $h \\to 0$ has only two directions, while in the complex case it has infinitely many.", status: 'draft', basedOn: "v0.9.3#650a6d87" } },
  "def-link.cr-holomorphic": { note: { en: "Part (i) of the theorem is the definition of complex differentiability. The entire theorem **translates** that definition into component equations.", status: 'draft', basedOn: "v0.9.3#745fe1e0" } },
  "def-link.complex-partial-complex": { note: { en: "Both operators are defined using the imaginary unit $i$. They recombine the two real partial derivatives on $\\mathbb{R}^2$ into “two directions” in $\\mathbb{C}$.", status: 'draft', basedOn: "v0.9.3#9a15fa79" } },
  "def-link.contour-integral-riemann": { note: { en: "A contour integral is obtained by partitioning the parameter interval, forming Riemann sums, and taking the limit. The multiplier on each subinterval is the **complex displacement** $\\gamma(t_k) - \\gamma(t_{k-1})$ in place of the length.", status: 'draft', basedOn: "v0.9.3#16592120" } },
  "def-link.contour-integral-integrable": { note: { en: "On the right-hand side of the definition, $\\int_a^b f(\\gamma(t))\\gamma'(t)\\,\\mathrm{d}t$ is a complex-valued Riemann integral over a real interval. Integrability is checked separately for the real and imaginary parts.", status: 'draft', basedOn: "v0.9.3#35de1f71" } },
  "def-link.laurent-power-series": { note: { en: "The regular part is an ordinary power series. The principal part is the same kind of series with $(z - a)$ replaced by $(z - a)^{-1}$. Their convergence regions, one interior and one exterior, intersect in an annulus.", status: 'draft', basedOn: "v0.9.3#9bedd7ed" } },
  "def-link.taylor-power-series": { note: { en: "By definition, “$f$ is analytic in $B(a, R)$” means that a power series converges in $B(a, R)$ to $f$. The theorem says precisely that holomorphicity implies this.", status: 'draft', basedOn: "v0.9.3#97933814" } },
  "def-link.residue-contour": { note: { en: "The residue itself is defined by a **contour integral along a small circle**, and Cauchy–Goursat guarantees independence of $r$.", status: 'draft', basedOn: "v0.9.3#6f4435dc" } },
  "def-link.residue-theorem": { note: { en: "The right-hand side of the theorem is the sum of the residues at the singularities multiplied by $2\\pi i$. The definition of residue is used here for all the singularities at once.", status: 'draft', basedOn: "v0.9.3#5f02f1d5" } },
  "def-link.goursat-contour": { note: { en: "The theorem says precisely that a certain contour integral equals zero, so it first requires a definition of the contour integral itself.", status: 'draft', basedOn: "v0.9.3#8ed75865" } },
  "def-link.mobius-complex": { note: { en: "The coefficients $a, b, c, d$ all lie in $\\mathbb{C}$. The map becomes bijective upon extension to $\\hat{\\mathbb{C}} = \\mathbb{C} \\cup \\{\\infty\\}$.", status: 'draft', basedOn: "v0.9.3#020fa165" } },
  "def-link.goursat-holomorphic": { note: { en: "The lemma assumes that $f$ is holomorphic on an open set containing $T$. The proof uses this only once, to know that the difference quotient $\\dfrac{f(z) - f(z^*)}{z - z^*}$ has a limit as $z \\to z^*$ (precisely the definition of complex differentiability).", status: 'draft', basedOn: "v0.9.3#7c22798f" } },
  "dep.sym-complex-def-contour-integral": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.partial-complexpartial": { note: { en: "The definition combines partial derivatives to form $\\partial/\\partial z$ and $\\partial/\\partial \\bar z$", status: 'draft', basedOn: "v0.9.3#3018f31a" } },
  "dep.mf-topology-chart": { note: { en: "In a chart, $U$ must be open and $\\varphi$ must be a homeomorphism onto an open set. The statement “$M$ locally looks like $\\mathbb{R}^{n}$” is entirely topological, so a manifold must first be a topological space.", status: 'draft', basedOn: "v0.9.3#1ba0a1cf" } },
  "dep.mf-homeo-chart": { note: { en: "A chart is a homeomorphism between open sets. A mere bijection cannot transfer continuity, compactness, or convergence from $\\mathbb{R}^{n}$, so the coordinates would lose their topological meaning.", status: 'draft', basedOn: "v0.9.3#ee20682f" } },
  "dep.mf-jacobian-diff": { note: { en: "In charts, the matrix of $\\mathrm{d}F_{p}$ is the Jacobian matrix of the local representation. Changing charts multiplies it by a Jacobian matrix on each side, once covariantly and once contravariantly, so it remains a well-defined linear map.", status: 'draft', basedOn: "v0.9.3#44ab2ad4" } },
  "dep.mf-tangent-diff": { note: { en: "The tangent map is a linear map between tangent spaces, with tangent spaces as both domain and codomain. The definition of tangency for curve classes gives $\\mathrm{d}F_{p}([\\gamma]) := [F \\circ \\gamma]$ directly.", status: 'draft', basedOn: "v0.9.3#f7f69a93" } },
  "dep.mf-tangent-vf": { note: { en: "The vector chosen at each point belongs to $T_{p}M$. The derivation viewpoint $Xf := \\mathrm{d}f(X)$ uses precisely the definition of a tangent vector as acting on functions.", status: 'draft', basedOn: "v0.9.3#2f9dc19c" } },
  "dep.mf-vf-bracket": { note: { en: "The bracket takes two vector fields and returns a vector field. The cancellation of the second-order terms also makes sense only when the bracket is defined on a family of smooth vector fields.", status: 'draft', basedOn: "v0.9.3#c060d571" } },
  "dep.mf-vs-vectorbundle": { note: { en: "Each fiber is a $k$-dimensional real vector space, and the transition functions take values in $\\operatorname{GL}(k,\\mathbb{R})$. All the linear structure comes from the vector spaces. The vector bundle simply puts that linear structure on a manifold.", status: 'draft', basedOn: "v0.9.3#70ba3182" } },
  "dep.mf-secondcountable-smooth-pu": { note: { en: "Paracompactness follows from being “second-countable $+$ Hausdorff $+$ locally Euclidean.” Without second countability, a locally finite refinement need not exist, and the bump functions cannot then be assembled into a global whole. The long line is a counterexample.", status: 'draft', basedOn: "v0.9.3#27f156f0" } },
  "dep.mf-extd-derham": { note: { en: "The complex is the chain formed by $\\mathrm{d}$, and $\\mathrm{d}^{2} = 0$ is the sole source of “$\\operatorname{im} \\subseteq \\ker$.” Without it the quotient space cannot be defined.\n\n⭐ 2026-11-01 Changed the reference to $\\mathrm{d}$ **on a manifold** (it previously pointed to the coordinate formula on a Euclidean open set).\n\nEvery term of the de Rham complex is $\\Omega^{k}(M)$, so the d used is naturally the d on a manifold.\n\nThat proposition establishes its well-definedness.", status: 'draft', basedOn: "v0.9.3#22fa9e7c" } },
  "dep.mf-connected-h0": { note: { en: "The $c$ in the conclusion counts connected components, and “component” is precisely the language of connectedness. “$M$ is connected $\\iff \\dim H^{0} = 1$” is also a criterion for connectedness.", status: 'draft', basedOn: "v0.9.3#1c17aa9f" } },
  "dep.mf-group-liegroup": { note: { en: "A Lie group is first a group. Associativity, the identity, and inversion all come from the group structure. The smooth structure is an additional layer.", status: 'draft', basedOn: "v0.9.3#525cf594" } },
  "dep.mf-smoothmanifold-liegroup": { note: { en: "To say that multiplication and inversion are smooth, one must first regard both $G \\times G$ and $G$ as smooth manifolds. Thus the definition of a Lie group depends on the definition of a manifold.", status: 'draft', basedOn: "v0.9.3#c496e266" } },
  "dep.mf-ift-liegroup": { note: { en: "The classical groups $\\operatorname{SL}$, $\\operatorname{O}$, and $\\operatorname{U}$ are submanifolds cut out by equations. The implicit function theorem provides the construction, and the group structure is an added bonus.", status: 'draft', basedOn: "v0.9.3#d5508259" } },
  "dep.mf-liegroup-leftinv": { note: { en: "Left invariance is expressed using left translation $L_{g}$. The smoothness of $L_{g}$, which makes $\\mathrm{d}(L_{g})$ meaningful, is part of the definition of a Lie group.", status: 'draft', basedOn: "v0.9.3#074207ef" } },
  "dep.mf-bracket-leftinv": { note: { en: "The step showing that the bracket is again left-invariant uses the naturality of the vector field bracket, a direct consequence of the definition in `def.lie-bracket`.", status: 'draft', basedOn: "v0.9.3#7a99352a" } },
  "dep.mf-tangent-leftinv": { note: { en: "$\\mathfrak{g} := T_{e}G$. The underlying space of the Lie algebra is the tangent space at the identity, and item 1 of the proposition identifies it with the space of left-invariant vector fields by an isomorphism.", status: 'draft', basedOn: "v0.9.3#04695f1d" } },
  "dep.sym-real-def-manifold-chart": { note: { en: "The statement concerns the real numbers $\\mathbb{R}$ (notation dependency)", status: 'draft', basedOn: "v0.9.3#0453d27b" } },
  "dep.spivak-form-chain-integral": { note: { en: "Integration over a chain ultimately reduces to integration over $\\int_{[0,1]^{k}}f$. This uses precisely the definition of integration of a $n$-form on an open set (take $U$ to be an open set containing the cube). This definition also explains how $\\det$ matches the change-of-variables formula under a substitution.", status: 'draft', basedOn: "v0.9.3#f832a8fd" } },
  "dep.spivak-form-chain-stokes": { note: { en: "Both sides of the theorem concern forms. The left side uses a $(k-1)$-form, and the right side uses its exterior derivative, a $k$-form. The difference of one in degree comes from the grading of differential forms.", status: 'draft', basedOn: "v0.9.3#d8111725" } },
  "dep.spivak-d-cube-stokes": { note: { en: "The entire calculation in the proof amounts to “expanding $\\mathrm{d}$ into $\\sum_{j}\\partial_{j}f_{j}$ by definition.” The step $\\mathrm{d}^{2} = 0$ is also used implicitly here ($\\mathrm{d}(\\mathrm{d}x^{I}) = 0$).", status: 'draft', basedOn: "v0.9.3#e7bb45dd" } },
  "dep.spivak-det-changevars": { note: { en: "The change-of-variables factor is the determinant $\\det(\\partial g/\\partial x)$ of the Jacobian matrix. The oriented formula omits the absolute value precisely because $\\det$ already carries a sign. The absolute value is added back once orientation is discarded.", status: 'draft', basedOn: "v0.9.3#7ca5de00" } },
  "def-link.winding-contour": { note: { en: "The winding number is **defined using a contour integral** by taking $\\oint_{\\gamma} \\mathrm{d}\\zeta/(\\zeta - a_0)$ and dividing by $2\\pi i$. The trick of showing independence from $r$ applies here too, except that this time even the radius changes.", status: 'draft', basedOn: "v0.9.3#efc013fa" } },
  "def-link.argument-winding": { note: { en: "The $n(f \\circ \\gamma, 0)$ on the right-hand side is the winding number from the definition, with the curve replaced by $f \\circ \\gamma$ and the point replaced by $0$. The entire theorem says that the integral on the left equals this winding number.", status: 'draft', basedOn: "v0.9.3#b66bd1dc" } },
  "def-link.harmonic-partial": { note: { en: "Laplace's equation $\\Delta u = u_{xx} + u_{yy}$ combines four second-order partial derivatives. These derivatives must first be specified before “$\\Delta u = 0$” can be discussed.", status: 'draft', basedOn: "v0.9.3#4d68cfd3" } },
  "def-link.meanvalue-harmonic": { note: { en: "The theorem concerns harmonic functions, and the criterion for harmonicity is $\\Delta u = 0$.", status: 'draft', basedOn: "v0.9.3#1be46be6" } },
  "def-link.poisson-harmonic": { note: { en: "The Poisson formula represents the values of the harmonic function $u = \\operatorname{Re} f$. It also addresses the part of the Dirichlet problem that requires the solution to be harmonic.", status: 'draft', basedOn: "v0.9.3#50fac29a" } },
  "def-link.conjugate-harmonic": { note: { en: "In “harmonic conjugate,” $v$ appears as the partner of $u$. The starting assumption is that $u$ is harmonic, and $v$ is recovered by solving the Cauchy–Riemann equations.", status: 'draft', basedOn: "v0.9.3#5e2f69cf" } },
  "def-link.entire-holomorphic": { note: { en: "An entire function is “holomorphic everywhere on $\\mathbb{C}$.” A meromorphic function is “holomorphic after its isolated poles are removed.” Both qualify the concept of holomorphicity and therefore presuppose it.", status: 'draft', basedOn: "v0.9.3#76b29217" } },
  "def-link.schwarzpick-mobius": { note: { en: "The $\\varphi_a(z) = (z - a)/(1 - \\overline{a} z)$ used in the proof is the fractional linear transformation with $a = 1$, $b = -a$, $c = -\\overline{a}$, and $d = 1$. The automorphism in “equality holds if and only if $f$ is an automorphism” is also a fractional linear transformation.", status: 'draft', basedOn: "v0.9.3#d394f7a2" } },
  "dep.mf2-chart-frobenius": { note: { en: "Conclusion (2) of the theorem says that there are coordinates that straighten the distribution into coordinate slices. This is a statement about charts (coordinates), and flattening coordinates are a special case of a chart.", status: 'draft', basedOn: "v0.9.3#d0edd1cf" } },
  "dep.mf2-liegroup-liform": { note: { en: "Left invariance means invariance under pullback by left translation $L_{g}$. The smoothness of $L_{g}$, which makes pullback possible, is part of the definition of a Lie group.", status: 'draft', basedOn: "v0.9.3#5efc8afb" } },
  "dep.mf2-dform-liform": { note: { en: "Left invariance here is a property of $k$-forms. When $k = n$, the left-invariant $n$-form is also a volume form. This corollary uses the theory of forms rather than group theory.", status: 'draft', basedOn: "v0.9.3#133eebda" } },
  "dep.mf2-pullback-liform": { note: { en: "“$L_{g}^{\\ast}\\omega = \\omega$” uses pullback of forms. The proof of `thm.maurer-cartan` also requires that pullback commute with exterior differentiation.", status: 'draft', basedOn: "v0.9.3#5e4b4e4a" } },
  "dep.mf2-derham-derhamthm": { note: { en: "The $H^{k}_{\\mathrm{dR}}$ on the left is “closed forms modulo exact forms,” which depends entirely on $\\mathrm{d}^{2} = 0$ and the construction of quotient spaces.", status: 'draft', basedOn: "v0.9.3#a24b2347" } },
  "dep.mf2-integralonchain-derhamthm": { note: { en: "The isomorphism is given by $[\\omega] \\mapsto \\bigl([c] \\mapsto \\int_{c}\\omega\\bigr)$, so “integration of forms over chains” supplies the theorem's **construction** rather than an example. Without it there is no map.", status: 'draft', basedOn: "v0.9.3#63ce0648" } },
  "dep.weierstrass-holomorphic": { note: { en: "The Weierstrass convergence theorem concerns sequences of holomorphic functions.", status: 'draft', basedOn: "v0.9.3#4559a81c" } },
  "dep.weierstrass-uniform": { note: { en: "Uniform convergence is a hypothesis of the Weierstrass convergence theorem.", status: 'draft', basedOn: "v0.9.3#a00b117f" } },
  "e32.definition": { note: { en: "The reflection principle gives precisely an analytic continuation across the boundary. Use $f$ on the upper half to define $F$ on the lower half, then verify holomorphicity.", status: 'draft', basedOn: "v0.9.3#2275fa29" } },
  "e33.definition": { note: { en: "Every factor in the product theorem is an elementary factor $E_{p_{n}}(z/a_{n})$. The definition is here, and the theorem shows how it is used.", status: 'draft', basedOn: "v0.9.3#09f3664c" } },
  "e34.definition": { note: { en: "A path is a map $\\gamma : [0,1] \\to X$. Without the definition of a map, a path cannot be defined.", status: 'draft', basedOn: "v0.9.3#dffe275c" } },
  "e35.definition": { note: { en: "A path requires $\\gamma$ to be continuous. This is the first place where continuity from point-set topology is actually used.", status: 'draft', basedOn: "v0.9.3#3e960075" } },
  "e36.definition": { note: { en: "A path homotopy is a homotopy of maps that fixes both endpoints, with $H(\\cdot, 0) = \\gamma_{0}$ and $H(\\cdot, 1) = \\gamma_{1}$, and with both endpoints held fixed.", status: 'draft', basedOn: "v0.9.3#bfe29afd" } },
  "e40.definition": { note: { en: "The $f_{*}$ induced by a continuous map is a **group homomorphism**, with $f_{*}([\\alpha][\\beta]) = f_{*}([\\alpha])f_{*}([\\beta])$.", status: 'draft', basedOn: "v0.9.3#bb462855" } },
  "e41.definition": { note: { en: "A covering map $p : E \\to B$ is a continuous surjection with the additional requirement that each point have an evenly covered neighborhood.", status: 'draft', basedOn: "v0.9.3#6c0c125e" } },
  "e42.definition": { note: { en: "Standard covering results such as uniqueness of lifts and discreteness of fibers take a clean form under the Hausdorff hypothesis (or at least $T_{1}$).", status: 'draft', basedOn: "v0.9.3#21f5675a" } },
  "e43.definition": { note: { en: "A retraction $r : \\overline{\\mathbb{D}} \\to S^{1}$ must be continuous and satisfy $r|_{S^{1}} = \\mathrm{id}$.", status: 'draft', basedOn: "v0.9.3#13d07857" } },
  "e47.definition": { note: { en: "The chain group $C_{n}(K)$ is a **free abelian group** with the $n$-simplices as its basis and integer coefficients. Its group structure is exactly the one defined here.", status: 'draft', basedOn: "v0.9.3#ff0f112c" } },
  "e49.definition": { note: { en: "A singular $n$-simplex is a **continuous map** $\\sigma : \\Delta^{n} \\to X$ (compare an abstract simplex, a combinatorial object with no topology).", status: 'draft', basedOn: "v0.9.3#59628360" } },
  "e50.definition": { note: { en: "The **homotopy invariance** of singular homology uses homotopies of maps. The prism operator $P$ is their algebraic counterpart, making this dependency unavoidable.", status: 'draft', basedOn: "v0.9.3#5b7dd8ee" } },
  "e51.definition": { note: { en: "Singular and simplicial chain groups use the same construction (free abelian groups + boundary operators). The former uses continuous simplices and the latter uses combinatorial simplices.", status: 'draft', basedOn: "v0.9.3#70442bd5" } },
  "def-link.shrinks-general": { note: { en: "The theorem holds for every shrinkable family.", status: 'draft', basedOn: "v0.9.3#0694ddab" } },
  "e59.definition": { note: { en: "Uniqueness of the lift follows directly from the fact that on each sheet $V_{j}$, $p$ is a homeomorphism. Once the sheet is known, the entire segment of the lift is determined.", status: 'draft', basedOn: "v0.9.3#9d2e1205" } },
  "e64.definition": { note: { en: "The retraction $r : D^{2} \\to S^{1}$ satisfies $r \\circ i = \\operatorname{id}_{S^{1}}$ and is precisely a **retraction** of $i$ in the categorical sense ($i$ is $S^{1} \\hookrightarrow D^{2}$). Thus “$S^{1}$ is not a retract” $=$ “$i$ has no left inverse.”", status: 'draft', basedOn: "v0.9.3#05c09282" } },
  "def-link.chainhom-simplicial": { note: { en: "The proof uses the chain map induced by a simplicial map and the prism construction for chain homotopies to turn $|g| \\simeq \\operatorname{id}$ into a chain homotopy.", status: 'draft', basedOn: "v0.9.3#050cfbe8" } },
  "dep.n12-crossratio-mobiuscircle": { note: { en: "The cross-ratio is invariant under fractional linear transformations and can be used to determine whether four points are concyclic or collinear.", status: 'draft', basedOn: "v0.9.3#fba305c7" } },
  "dep.n12-complexelem-standardmaps": { note: { en: "Elementary functions such as powers, exponentials, and logarithms are building blocks for standard conformal maps.", status: 'draft', basedOn: "v0.9.3#cfe8b038" } },
  "dep.crossratio-real-crossratio": { note: { en: "The real cross-ratio proposition is the special case of the cross-ratio on the real axis.", status: 'draft', basedOn: "v0.9.3#b6084b57" } },
  "e124.definition": { note: { en: "The proof uses the group-theoretic fact that the order of an element of a finite group divides the order of the group. This is a **proof tool**. The theorem itself mentions only $\\gcd(a,n)=1$ and $a^{\\varphi(n)}\\equiv1$, with no mention of groups.", status: 'draft', basedOn: "v0.9.3#5c3ea98f" } },
  "e125.analogy": { note: { en: "The proofs have exactly the same structure. On $\\mathbb{Z}$ the absolute value decreases, and on $K[x]$ the degree decreases. Both conclude with “quotient + remainder, with the remainder smaller than the divisor.”\n\n\n\nThe only difference is how “smaller” is measured. $\\mathbb{Z}$ has a total order, while $K[x]$ uses degree alone (with arbitrary coefficients). This also explains why both are called **Euclidean domains**. A Euclidean function suffices.\n\n\n\nThe subsequent steps also match. On $\\mathbb{Z}$ the Euclidean algorithm gives gcds and then the UFD property. On $K[x]$ exactly the same chain applies (`thm.poly-ufd`).", status: 'draft', basedOn: "v0.9.3#db9f4e8f" } },
  "e126.analogy": { note: { en: "The two theorems are word for word the same after replacing “prime number” with “irreducible polynomial” and “absolute value” with “degree.”\n\n\n\nThe UFD property is not automatic, however. Neither $\\mathbb{Z}[\\sqrt{-5}]$ nor $K[x, y]$ is a UFD. The counterexamples have the same form too. A single element has two genuinely different factorizations.", status: 'draft', basedOn: "v0.9.3#068c0cd6" } },
  "dep.intdiv-int": { note: { en: "The statement is about $a,b,q,r\\in\\mathbb{Z}$.", status: 'draft', basedOn: "v0.9.3#ba3502cf" } },
  "dep.intdiv-abs": { note: { en: "The statement uses $0\\le r<|b|$, directly invoking absolute value.", status: 'draft', basedOn: "v0.9.3#3f4f7245" } },
  "dep.euclidalg-abs": { note: { en: "The algorithm starts from $|a|,|b|$ and ensures that the remainder is nonnegative.", status: 'draft', basedOn: "v0.9.3#42bea000" } },
  "e127.definition": { note: { en: "An integral domain is a commutative ring with identity and no zero divisors. All three conditions are additions to `def.ring`.", status: 'draft', basedOn: "v0.9.3#22505764" } },
  "e130.definition": { note: { en: "A UFD is an integral domain. Without the assumption of no zero divisors, factorization and cancellation both fail, and uniqueness cannot be discussed.", status: 'draft', basedOn: "v0.9.3#f299ebb1" } },
  "e131.definition": { note: { en: "A gcd domain is an integral domain. A greatest common divisor uses divisibility to define lower bounds, and the absence of zero divisors makes divisibility behave as expected ($0$ is excluded as a factor).", status: 'draft', basedOn: "v0.9.3#5532dd1a" } },
  "e132.definition": { note: { en: "A Euclidean domain is an integral domain equipped with a Euclidean function satisfying division with remainder.", status: 'draft', basedOn: "v0.9.3#7cce1eab" } },
  "e133.definition": { note: { en: "A Bézout domain is an integral domain with the condition that every finitely generated ideal is principal.", status: 'draft', basedOn: "v0.9.3#ba1d5c8c" } },
  "e134.definition": { note: { en: "A PID is defined by the condition that every ideal is principal. This requires the concept of an ideal.", status: 'draft', basedOn: "v0.9.3#f5e9ebe0" } },
  "e137.definition": { note: { en: "“$\\mathbb{Z}$ is a UFD” is an **example** of viewing the fundamental theorem of arithmetic in the framework of general rings. The theorem itself speaks only of primes and factorization, without invoking the definition of a UFD. The definition of a UFD likewise does not presuppose integer factorization.", status: 'draft', basedOn: "v0.9.3#1d52d38a" } },
  "e138.definition": { note: { en: "$K[x]$ is a UFD. The theorem itself verifies this definition.", status: 'draft', basedOn: "v0.9.3#542da745" } },
  "e139.definition": { note: { en: "Division with remainder in $K[x]$ is exactly what is needed for “the Euclidean function of $N = \\deg$.” This theorem is an example of a Euclidean domain.", status: 'draft', basedOn: "v0.9.3#292ec448" } },
  "e141.analogy": { note: { en: "The number-theoretic version of Bézout's identity says “$\\gcd(a,b)$ is an integer linear combination of $a,b$.” This requires the special properties of $\\mathbb{Z}$ (the Euclidean algorithm).\n\n\n\nTaking this as an **axiomatic property** defines a class of rings, the Bézout domains, in which every finitely generated ideal is principal. $\\mathbb{Z}$ and $K[x]$ satisfy it. $\\mathbb{Z}[x]$ does not (yet $\\gcd(2,x)=1$ is not a linear combination).\n\n\n\nSo “Bézout” correctly appears twice in the graph, once as a theorem on $\\mathbb{Z}$ and once as the name of a class of integral domains. The latter includes the former as well as $K[x]$.", status: 'draft', basedOn: "v0.9.3#ac447e3f" } },
  "dep.bezout-principal": { note: { en: "A Bézout domain requires every finitely generated ideal to be principal.", status: 'draft', basedOn: "v0.9.3#3588030c" } },
  "dep.pid-principal": { note: { en: "A principal ideal domain requires every ideal to be principal.", status: 'draft', basedOn: "v0.9.3#05fc0151" } },
  "def-link.newman-analytic": { note: { en: "The assumption that “$g$ extends analytically to a neighborhood of $\\{\\operatorname{Re}z\\ge0\\}$” invokes analytic continuation.", status: 'draft', basedOn: "v0.9.3#a9d4f9b8" } },
  "def-link.newman-holomorphic": { note: { en: "The proof uses holomorphicity both when $g$ is holomorphic on $D$ and when $g_T$ is entire.", status: 'draft', basedOn: "v0.9.3#a13507a8" } },
  "def-link.newman-contour": { note: { en: "The entire proof consists of estimating the contour integral of $C=\\partial D$.", status: 'draft', basedOn: "v0.9.3#88d6c8c3" } },
  "e162.definition": { note: { en: "Zorn's lemma is equivalent to the axiom of choice (`imp.zorn-choice`). The proof needs to pick elements from a family and does so with a choice function.", status: 'draft', basedOn: "v0.9.3#2a5b4e85" } },
  "def-link.ac-function-ift": { note: { en: "The proposition gives a measure-theoretic interpretation of an absolutely continuous function.", status: 'draft', basedOn: "v0.9.3#3ef55649" } },
  "def-link.ac-measure-ift": { note: { en: "It also uses absolute continuity for measures.", status: 'draft', basedOn: "v0.9.3#ecddfaf1" } },
  "def-link.ac-ftc": { note: { en: "(a) is precisely the definition of absolute continuity.", status: 'draft', basedOn: "v0.9.3#4e1d0cb9" } },
  "def-link.integrable-ftc": { note: { en: "In (b) and (c), $f$ and $F'$ are both required to belong to $L^{1}$.", status: 'draft', basedOn: "v0.9.3#91377e3d" } },
  "dep.sym-complex-def-ac-function": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notation dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.mf3-form-rn": { note: { en: "This is a coordinate model of the same object. Expanding $\\omega$ in a chart gives exactly the formula in that statement.", status: 'draft', basedOn: "v0.9.3#abff50dc" } },
  "dep.mf3-form-tanspace": { note: { en: "The definition concerns alternating forms on $T_{p}M$ that are $k$-linear. Without the tangent space the definition cannot be written.", status: 'draft', basedOn: "v0.9.3#a5b986db" } },
  "dep.mf3-form-chart": { note: { en: "Smoothness is independent of the chart, as follows from the Jacobian transformation rule between charts.", status: 'draft', basedOn: "v0.9.3#81779aa5" } },
  "dep.mf3-form-smoothmanifold": { note: { en: "The base manifold must be smooth for “the coefficients are smooth” to make sense.", status: 'draft', basedOn: "v0.9.3#db30eab6" } },
  "dep.mf3-dm-extd": { note: { en: "The coordinate formula on an open set is carried over directly as the definition in a chart.", status: 'draft', basedOn: "v0.9.3#e802f303" } },
  "dep.mf3-dm-form": { note: { en: "The proposition is about a family of operators on $\\Omega^{k}(M)$.", status: 'draft', basedOn: "v0.9.3#2adcef3a" } },
  "dep.mf3-pbm-form": { note: { en: "The source and target of pullback are both spaces of forms on manifolds.", status: 'draft', basedOn: "v0.9.3#7f88bf4f" } },
  "dep.mf3-pbm-rn": { note: { en: "The version for maps between open sets is the chart expression of this one. The proof here verifies the four axioms pointwise without relying on the open-set list of axioms. This is an **instance of a definition** rather than an implication. (The dependency is on the object rather than the proposition.)", status: 'draft', basedOn: "v0.9.3#0555fec9" } },
  "dep.mf3-pbm-dmap": { note: { en: "The defining formula inserts the tangent map $\\mathrm{d}F_{p}$ into the slots of the form $\\omega$. Without it the formula cannot be written.", status: 'draft', basedOn: "v0.9.3#7170b777" } },
  "dep.mf3-pbm-covm": { note: { en: "The change-of-variables formula is stated in terms of pullback, but the proof uses only the well-definedness of `def.integral-form` and a partition of unity. This is an **instance of a definition** rather than an implication (pullback supplies the language rather than a hypothesis). (The dependency is on the object rather than the proposition.)", status: 'draft', basedOn: "v0.9.3#bbfe7fdf" } },
  "dep.mf3-cotb-dual": { note: { en: "The cotangent space is the dual space. This is what makes the fiber a vector space.", status: 'draft', basedOn: "v0.9.3#329f449d" } },
  "dep.mf3-cotb-vbundle": { note: { en: "The cotangent bundle is an example of a rank-$n$ vector bundle. The local trivialization $\\Phi$ is precisely the $\\Phi$ required by that definition.", status: 'draft', basedOn: "v0.9.3#f2f3903b" } },
  "dep.mf3-cotb-chart": { note: { en: "The basis $\\mathrm{d}x^{i}$ is tied to the chart and gives the bundle its smooth structure.", status: 'draft', basedOn: "v0.9.3#fc1f7810" } },
  "dep.mf3-fb-chart": { note: { en: "The “local” in “local trivialization” refers to an open neighborhood in the base space (in the sense of a chart).", status: 'draft', basedOn: "v0.9.3#0942ad2d" } },
  "dep.mf3-prin-lie": { note: { en: "The structure group has to support smooth actions and smooth transition functions, so it must be a Lie group.", status: 'draft', basedOn: "v0.9.3#9b3e020e" } },
  "dep.mf3-prin-fb": { note: { en: "A principal bundle is first a fiber bundle, with two additional conditions, “$G$-equivariant trivializations” and a “free and transitive” action.", status: 'draft', basedOn: "v0.9.3#c220f92b" } },
  "dep.mf3-form-stokes": { note: { en: "The $\\omega$ in Stokes' theorem is a $(n-1)$-form **on a manifold**. It is integrated over the boundary, and $\\mathrm{d}\\omega$ is integrated over the interior. Previously, this could only refer to the definition on a Euclidean open set.", status: 'draft', basedOn: "v0.9.3#69bf6b0f" } },
  "dep.mf3-form-chainint": { note: { en: "The bilinearity of integration over chains is bilinearity on $\\Omega^{k}(M)$. Adding this edge gives the node its first definition edge (it was previously a “proposition without a definition edge”).", status: 'draft', basedOn: "v0.9.3#a7d71b28" } },
  "dep.mf3-form-lieform": { note: { en: "A left-invariant form is a $k$-form on a Lie group with an additional invariance condition. The underlying object is still a form on a manifold.", status: 'draft', basedOn: "v0.9.3#918013a0" } },
  "dep.mf3-triv-topology": { note: { en: "“Open set $U$,” “continuous map,” and “homeomorphism” in a trivialization are all terms for topological spaces.", status: 'draft', basedOn: "v0.9.3#5a327baf" } },
  "dep.mf3-triv-product": { note: { en: "The trivial product $U\\times F$ has the product topology. Without it, “flattening” has no meaning.", status: 'draft', basedOn: "v0.9.3#80276a23" } },
  "dep.mf3-triv-homeo": { note: { en: "The central requirement of local trivialization is that “the map connecting $\\Phi$ is a homeomorphism.” In the smooth case, this becomes a diffeomorphism.", status: 'draft', basedOn: "v0.9.3#c0208793" } },
  "dep.mf3-triv-vbundle": { note: { en: "The vector bundle definition requires “a local trivialization $\\Phi : \\pi^{-1}(U)\\to U\\times\\mathbb{R}^{k}$ that is a linear isomorphism on each fiber.” The first part is this definition, and the second adds the vector space structure.", status: 'draft', basedOn: "v0.9.3#9b3561a4" } },
  "dep.mf3-triv-fbundle": { note: { en: "Fiber bundle = locally trivial (topological) + fixed fiber the manifold $F$ (smooth).", status: 'draft', basedOn: "v0.9.3#ce9c6e71" } },
  "dep.mf3-triv-cotbundle": { note: { en: "The cotangent bundle chart $\\Phi : \\pi^{-1}(U)\\to\\varphi(U)\\times\\mathbb{R}^{n}$ is precisely its local trivialization.", status: 'draft', basedOn: "v0.9.3#e087b073" } },
  "dep.mf3-triv-bmetric": { note: { en: "A fiber metric is built by first choosing inner products on each trivializing patch, then assembling them with a partition of unity.", status: 'draft', basedOn: "v0.9.3#81278d4a" } },
  "dep.mf3-triv-form": { note: { en: "The equivalent formulation “$\\Omega^{k}(M) = \\Gamma(\\Lambda^{k}T^{\\ast}M)$” works because the exterior power bundle has local trivializations.", status: 'draft', basedOn: "v0.9.3#fef56d15" } },
  "dep.mf3-triv-prin": { note: { en: "The third condition for a principal bundle is “locally trivial and $G$-equivariant,” which adds equivariance to the trivialization condition.", status: 'draft', basedOn: "v0.9.3#3950a14d" } },
  "dep.mf3-lieform-pullback": { note: { en: "“Left-invariant” is expressed by pullback under left translation $L_{g}$, namely $L_{g}^{\\ast}\\omega = \\omega$, and $L_{g}$ is a smooth map between manifolds.", status: 'draft', basedOn: "v0.9.3#03257cd2" } },
  "dep.mf3-stokes-dmanifold": { note: { en: "In Stokes' theorem, $\\mathrm{d}$ denotes the exterior derivative **on a manifold**, as distinct from the coordinate formula on a Euclidean open set. (The dependency is on the object rather than the proposition.)", status: 'draft', basedOn: "v0.9.3#174536b9" } },
  "dep.mf3-chainint-form": { note: { en: "Integration over a chain takes forms on $M$ (the form is pulled back to $R^{k}$ only to do the calculation on the cube).", status: 'draft', basedOn: "v0.9.3#406e3955" } },
  "dep.ln-transpose-matrix": { note: { en: "Transposition swaps the indices of matrix entries, so it presupposes a matrix.", status: 'draft', basedOn: "v0.9.3#4a2cc413" } },
  "dep.ln-transpose-dual": { note: { en: "Transpose = matrix of the dual map. The reversal of multiplication order is the coordinate expression of duality reversing arrows.", status: 'draft', basedOn: "v0.9.3#05fb21e8" } },
  "dep.ln-ctranspose-adjoint": { note: { en: "In a standard orthonormal basis, the matrix of the adjoint operator is the conjugate transpose. This is the only correct way to connect the two.", status: 'draft', basedOn: "v0.9.3#3f78e1fe" } },
  "dep.ln-ctranspose-inner": { note: { en: "Conjugation appears because the inner product conjugates its second argument. Without an inner product there is no $A^{*}$.", status: 'draft', basedOn: "v0.9.3#c44fe388" } },
  "dep.ln-ctranspose-transpose": { note: { en: "Conjugate transpose = conjugate first, then transpose.", status: 'draft', basedOn: "v0.9.3#ca86c469" } },
  "dep.ln-unitary-ctranspose": { note: { en: "The defining condition $U^{*}U = I$ for unitarity is written directly using the conjugate transpose.", status: 'draft', basedOn: "v0.9.3#586750d9" } },
  "dep.ln-unitary-isometry": { note: { en: "A unitary matrix represents an inner-product-preserving linear map in a standard orthonormal basis. This is the coordinate expression of an isometry.", status: 'draft', basedOn: "v0.9.3#4a3faceb" } },
  "dep.ln-unitary-matrix": { note: { en: "A square matrix is needed before $U^{*}U = I$ can be discussed.", status: 'draft', basedOn: "v0.9.3#be5b019a" } },
  "dep.ln-hermite-ctranspose": { note: { en: "The definition $A^{*} = A$ of a Hermitian matrix is a condition on its conjugate transpose.", status: 'draft', basedOn: "v0.9.3#37f7a30e" } },
  "dep.ln-hermite-inner": { note: { en: "“Self-adjoint” means $\\langle Ax,y\\rangle = \\langle x,Ay\\rangle$ and presupposes an inner product.", status: 'draft', basedOn: "v0.9.3#238e5cfc" } },
  "dep.ln-normal-ctranspose": { note: { en: "The normality condition $A^{*}A = AA^{*}$ is written using the conjugate transpose.", status: 'draft', basedOn: "v0.9.3#b17b83e5" } },
  "dep.ln-normal-operator": { note: { en: "The matrix and operator versions translate into each other in a standard orthonormal basis.", status: 'draft', basedOn: "v0.9.3#52265814" } },
  "dep.ln-normal-unitary": { note: { en: "Hermitian matrices are a special case of normal matrices ($A^{*} = A$ $\\implies$, both products are $A^{2}$). The inclusion is stated in the main text.", status: 'draft', basedOn: "v0.9.3#a8e402c4" } },
  "dep.ln-posdef-hermite": { note: { en: "Positive definiteness is defined only for Hermitian (real symmetric) matrices. Otherwise $x^{*}Ax$ need not be real, and “$>0$” has no meaning.", status: 'draft', basedOn: "v0.9.3#58108ce1" } },
  "dep.ln-posdef-qform": { note: { en: "Positive-definite matrices correspond one-to-one with positive-definite quadratic forms.", status: 'draft', basedOn: "v0.9.3#9694c670" } },
  "dep.ln-schur-unitary": { note: { en: "The transformation to Schur form must use a unitary matrix (which is precisely why it is numerically stable and Jordan form is unstable).", status: 'draft', basedOn: "v0.9.3#a8d2c591" } },
  "dep.ln-schur-eigen": { note: { en: "The diagonal entries of a triangular matrix are its eigenvalues. Each step of the inductive proof chooses an eigenvector.", status: 'draft', basedOn: "v0.9.3#f20082dc" } },
  "dep.ln-schur-normal": { note: { en: "The matrix version of the spectral theorem concerns normal matrices.", status: 'draft', basedOn: "v0.9.3#f6d5529d" } },
  "dep.ln-spectral-unitary": { note: { en: "A diagonalization is called a spectral decomposition here when the diagonalizing transformation is unitary.", status: 'draft', basedOn: "v0.9.3#5fd664e7" } },
  "dep.ln-spectral-diag": { note: { en: "The spectral theorem strengthens diagonalizability by requiring orthogonality. It builds on the general criterion for diagonalizability.", status: 'draft', basedOn: "v0.9.3#38d4da41" } },
  "dep.ln-polar-posdef": { note: { en: "$P = \\sqrt{A^{*}A}$ is positive semidefinite, and the positive-definiteness result gives the fact that a positive semidefinite matrix has a unique square root.", status: 'draft', basedOn: "v0.9.3#6bfbb297" } },
  "dep.ln-polar-svd": { note: { en: "The two theorems imply each other for **square matrices**, which is precisely the scope of the equivalence. The SVD has a broader statement that also allows rectangular matrices, where the polar decomposition uses an isometry in place of a unitary matrix. Originally labeled analogy, FIX-065 changed it to equivalence following AUD-062 and added proofs in both directions.", status: 'draft', basedOn: "v0.9.3#c9e2d702" } },
  "dep.ln-rayleigh-hermite": { note: { en: "The Rayleigh quotient is real-valued and has meaningful extrema only for Hermitian (real symmetric) matrices.", status: 'draft', basedOn: "v0.9.3#c00e20ff" } },
  "dep.ln-rayleigh-inner": { note: { en: "The $x^{*}y$ in the quotient is the inner product.", status: 'draft', basedOn: "v0.9.3#904fc596" } },
  "dep.ln-spectral-old": { note: { en: "The two results express the same fact in operator and matrix language. The crucial step of taking the matrix in a standard orthonormal basis is reversible. Originally labeled analogy, FIX-065 changed it to equivalence and added derivations in both directions.", status: 'draft', basedOn: "v0.9.3#7d59ab6a" } },
  "dep.ln-normal-oldspectral": { note: { en: "Originally labeled analogy, FIX-065 changed it to equivalence. Both directions reduce to the same fact about the matrix in a standard orthonormal basis + $AU = U\\Lambda$.", status: 'draft', basedOn: "v0.9.3#c9952a36" } },
  "dep.sym-complex-def-conjugate-transpose": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notation dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.iso-bf": { note: { en: "Isotropy is a property defined with respect to a bilinear form (quadratic form).", status: 'draft', basedOn: "v0.9.3#dd2c55d1" } },
  "dep.iso-qform": { note: { en: "$\\beta(v,v) = q(v)$, so isotropy can also be expressed directly in terms of a quadratic form.", status: 'draft', basedOn: "v0.9.3#9bbd7741" } },
  "dep.eigsp-eig": { note: { en: "An eigenspace consists of all the eigenvectors belonging to a given eigenvalue, so the eigenvalue comes first.", status: 'draft', basedOn: "v0.9.3#64c45570" } },
  "dep.eigsp-ker": { note: { en: "$V_{\\lambda} = \\ker(T - \\lambda I)$, directly a kernel.", status: 'draft', basedOn: "v0.9.3#f655857e" } },
  "dep.eigsp-invariant": { note: { en: "An eigenspace is $T$-invariant, which is what allows it to be used to decompose the space.", status: 'draft', basedOn: "v0.9.3#f7ceafcd" } },
  "dep.genvec-eigsp": { note: { en: "A generalized eigenvector of order $1$ is an ordinary eigenvector, as expressed by $V_{\\lambda} \\subseteq G_{\\lambda}$.", status: 'draft', basedOn: "v0.9.3#b0b6f1a3" } },
  "dep.genvec-nilp": { note: { en: "$T - \\lambda I$ is nilpotent on $G_{\\lambda}$. This is the entire meaning of “generalized” here.", status: 'draft', basedOn: "v0.9.3#cbe82495" } },
  "dep.nilp-eig": { note: { en: "The criterion that all eigenvalues are $0$ is stated directly in terms of eigenvalues.", status: 'draft', basedOn: "v0.9.3#c3cf1ab0" } },
  "dep.nilp-cayley": { note: { en: "The statement $T^{n} = 0$ follows immediately from Cayley–Hamilton (the characteristic polynomial is $x^{n}$).", status: 'draft', basedOn: "v0.9.3#0b1bb755" } },
  "dep.orthsim-similarity": { note: { en: "Orthogonal similarity strengthens similarity by requiring $P$ to be an orthogonal matrix.", status: 'draft', basedOn: "v0.9.3#119a48f5" } },
  "dep.orthsim-unitary": { note: { en: "In the complex case, replace the orthogonal matrix with a unitary matrix.", status: 'draft', basedOn: "v0.9.3#ec5675d9" } },
  "dep.nilpotent-charpoly": { note: { en: "The equivalent condition for nilpotence is expressed in terms of the characteristic polynomial.", status: 'draft', basedOn: "v0.9.3#f7f3ceb2" } },
  "dep.mnorm-vs": { note: { en: "The operator norm is induced by the vector norm, so the vector space and its norm must first be defined.", status: 'draft', basedOn: "v0.9.3#1735d873" } },
  "dep.mnorm-inner": { note: { en: "The Frobenius norm is the Euclidean length obtained by treating the matrix as a vector. The spectral norm uses singular values, which come from the inner product.", status: 'draft', basedOn: "v0.9.3#bbae49ee" } },
  "dep.mnorm-svd": { note: { en: "Both $\\lVert A\\rVert_2 = \\sigma_{\\max}$ and $\\lVert A\\rVert_F = (\\sum\\sigma_i^2)^{1/2}$ rely on the SVD.", status: 'draft', basedOn: "v0.9.3#4c7fd603" } },
  "dep.lu-elem": { note: { en: "LU factorization is the matrix form of Gaussian elimination (elementary row operations).", status: 'draft', basedOn: "v0.9.3#e1ce16fd" } },
  "dep.lu-posdef": { note: { en: "When the matrix is positive definite, LU becomes Cholesky $A = LL^{T}$, as pointed out in the note.", status: 'draft', basedOn: "v0.9.3#66a64e22" } },
  "dep.qr-unitary": { note: { en: "In the square-matrix case, $Q$ is an orthogonal (unitary) matrix.", status: 'draft', basedOn: "v0.9.3#2d7150c1" } },
  "dep.ls-proj": { note: { en: "The geometric meaning of the least-squares solution is the orthogonal projection of $b$ onto the column space. The normal equations are its algebraic form.", status: 'draft', basedOn: "v0.9.3#d522ab5e" } },
  "dep.ls-posdef": { note: { en: "Full column rank $\\implies$ $A^{T}A$ is positive definite $\\implies$ the normal equations have a unique solution.", status: 'draft', basedOn: "v0.9.3#fe3fbbb1" } },
  "dep.pinv-svd": { note: { en: "The standard construction of the pseudoinverse uses the SVD: $A^{+} = V\\Sigma^{+}U^{*}$.", status: 'draft', basedOn: "v0.9.3#1216825f" } },
  "dep.pinv-invertible": { note: { en: "For an invertible matrix, the pseudoinverse is the inverse itself. It generalizes the inverse.", status: 'draft', basedOn: "v0.9.3#0d68520c" } },
  "dep.lagid-det": { note: { en: "The algebraic expression for the square of the area is the $2\\times2$ determinant.", status: 'draft', basedOn: "v0.9.3#8b1e0c7b" } },
  "dep.lagid-inner": { note: { en: "Both sides of the identity are written using inner products.", status: 'draft', basedOn: "v0.9.3#fa6fb4c4" } },
  "dep.sm-form": { note: { en: "A symplectic form is a 2-form on a manifold, using the general definition of a form on a manifold (`def.form-on-manifold`).", status: 'draft', basedOn: "v0.9.3#c55bc1f3" } },
  "dep.sm-extd": { note: { en: "“Closed” $d\\omega = 0$ is stated using the exterior derivative on a manifold.", status: 'draft', basedOn: "v0.9.3#e9d685b2" } },
  "dep.sm-mf": { note: { en: "A symplectic manifold is, first of all, a smooth manifold.", status: 'draft', basedOn: "v0.9.3#3da39a7d" } },
  "dep.sm-cotb": { note: { en: "The standard example $T^{*}\\mathbb{R}^{n}$ is the cotangent bundle, the mathematical identity of phase space.", status: 'draft', basedOn: "v0.9.3#81a9d242" } },
  "dep.darb-sm": { note: { en: "The theorem concerns symplectic manifolds, which can be put into standard form locally.", status: 'draft', basedOn: "v0.9.3#a52a3e0d" } },
  "dep.darb-mf": { note: { en: "The conclusion asserts the existence of a coordinate neighborhood. Coordinate systems are defined on manifolds.", status: 'draft', basedOn: "v0.9.3#a9d22e6c" } },
  "dep.hvf-sm": { note: { en: "In $\\iota_{X_H}\\omega = +dH$, $\\omega$ is the symplectic form of the symplectic manifold.", status: 'draft', basedOn: "v0.9.3#0ca34c63" } },
  "dep.hvf-vf": { note: { en: "$X_H$ is itself a vector field.", status: 'draft', basedOn: "v0.9.3#94b0f53b" } },
  "dep.pb-hvf": { note: { en: "$\\{f,g\\} = \\omega(X_f, X_g)$. The bracket is obtained by pairing two Hamiltonian vector fields.", status: 'draft', basedOn: "v0.9.3#84291a99" } },
  "dep.pb-sm": { note: { en: "The entire construction takes place on a symplectic manifold.", status: 'draft', basedOn: "v0.9.3#37f5a10e" } },
  "dep.lsm-sm": { note: { en: "A Lagrangian submanifold is a submanifold of a symplectic manifold.", status: 'draft', basedOn: "v0.9.3#639b3d75" } },
  "dep.lsm-mf": { note: { en: "The concept of an immersed submanifold itself presupposes that of a smooth manifold.", status: 'draft', basedOn: "v0.9.3#e193d0cc" } },
  "dep.lb-pb": { note: { en: "The matrices of the two brackets are inverses of each other, so the definition must first specify the Poisson bracket matrix.", status: 'draft', basedOn: "v0.9.3#a3b4eb9b" } },
  "dep.lb-cotb": { note: { en: "$(q, p)$ are Darboux coordinates on the cotangent bundle.", status: 'draft', basedOn: "v0.9.3#a82c0a47" } },
  "dep.cn-sub": { note: { en: "The hereditary property concerns the subspace topology.", status: 'draft', basedOn: "v0.9.3#e031d2d0" } },
  "dep.cn-closed": { note: { en: "The criterion for separated sets is written using closures: $\\overline{A} \\cap B = A \\cap \\overline{B} = \\emptyset$.", status: 'draft', basedOn: "v0.9.3#cac7cc6e" } },
  "dep.cnormal-subspace": { note: { en: "Complete normality requires every subspace to be normal.", status: 'draft', basedOn: "v0.9.3#ea939de8" } },
  "def-link.conjugate-holder": { note: { en: "The $1/p + 1/q = 1$ in the statement is the definition of conjugate exponents.", status: 'draft', basedOn: "v0.9.3#e844ffc4" } },
  "def-link.duality-bounded": { note: { en: "The proposition says precisely that boundedness of the pairing $\\int fg$ forces $g$ to belong to L^q.", status: 'draft', basedOn: "v0.9.3#a870c68d" } },
  "def-link.conjugate-riesz": { note: { en: "The conclusion says that “$q$ is the conjugate exponent.”", status: 'draft', basedOn: "v0.9.3#deda18fb" } },
  "def-link.duality-riesz": { note: { en: "The theorem says that $g \\mapsto \\varphi _g$ is an isometric isomorphism.", status: 'draft', basedOn: "v0.9.3#2ff97657" } },
  "dep.sym-complex-def-essential-sup": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.rcf-minpoly": { note: { en: "The largest invariant factor $d_{s}$ is the minimal polynomial.", status: 'draft', basedOn: "v0.9.3#937a7b64" } },
  "dep.rcf-similarity": { note: { en: "The conclusion asserts similarity to a certain block-diagonal matrix. The classification is by similarity class.", status: 'draft', basedOn: "v0.9.3#3895e9f4" } },
  "dep.rcf-poly": { note: { en: "The product of the invariant factors is the characteristic polynomial, so the two polynomial chains align here.", status: 'draft', basedOn: "v0.9.3#52329cd6" } },
  "dep.invariant-smith": { note: { en: "The invariant factors are the diagonal entries of the Smith normal form.", status: 'draft', basedOn: "v0.9.3#c71644e0" } },
  "dep.invariant-rcf": { note: { en: "The rational canonical form has one companion matrix block for each invariant factor.", status: 'draft', basedOn: "v0.9.3#c0d80503" } },
  "def-link.uc-norm": { note: { en: "The definition of uniform convexity is written entirely in terms of the norm.", status: 'draft', basedOn: "v0.9.3#ba156e9e" } },
  "def-link.uc-banach": { note: { en: "Uniform convexity is usually discussed for Banach spaces. The definition itself makes sense for any normed space.", status: 'draft', basedOn: "v0.9.3#a06d6388" } },
  "def-link.ref-dual": { note: { en: "Reflexivity is defined using the double dual $X^{**}$ and the canonical embedding $J_X$.", status: 'draft', basedOn: "v0.9.3#e2fccd88" } },
  "def-link.ref-banach": { note: { en: "Reflexivity is a property of Banach spaces (completeness is used for the norm structure of $X^{**}$).", status: 'draft', basedOn: "v0.9.3#edd1be33" } },
  "e166.definition": { note: { en: "Orthogonal decomposition requires the subspace $E$ to be closed. Otherwise, a nearest point may fail to exist.", status: 'draft', basedOn: "v0.9.3#a0801fe7" } },
  "dep.hb-norm": { note: { en: "The norm-preserving extension corollary takes $p(x) = \\|\\varphi\\|\\,\\|x\\|$.", status: 'draft', basedOn: "v0.9.3#07657c4c" } },
  "dep.sym-complex-def-norm": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.sym-real-def-norm": { note: { en: "The statement concerns the real numbers $\\mathbb{R}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#0453d27b" } },
  "dep-opc-lc": { note: { en: "The statement “$X^{*}$ Hausdorff $\\iff$ $X$ locally compact Hausdorff” uses local compactness.", status: 'draft', basedOn: "v0.9.3#db59ba50" } },
  "dep-opc-hausdorff": { note: { en: "The same statement also requires $X$ to be Hausdorff.", status: 'draft', basedOn: "v0.9.3#c50af2a0" } },
  "dep-opc-compact": { note: { en: "The second clause defining the open sets uses compactness of the complement to define neighborhoods of $\\infty$.", status: 'draft', basedOn: "v0.9.3#f57a4bb5" } },
  "dep-net-top": { note: { en: "Convergence is expressed in terms of neighborhoods and therefore presupposes a topological space.", status: 'draft', basedOn: "v0.9.3#3de0d16c" } },
  "dep-net-cont": { note: { en: "“Continuous $\\iff$ preserve net convergence” is one of the main uses of this definition.", status: 'draft', basedOn: "v0.9.3#1360cb74" } },
  "dep-net-compact": { note: { en: "“Compact $\\iff$ every net has a convergent subnet” is another main use.", status: 'draft', basedOn: "v0.9.3#ec2b03b5" } },
  "dep-flt-top": { note: { en: "Convergence is expressed in terms of neighborhood filters.", status: 'draft', basedOn: "v0.9.3#d0433a2a" } },
  "dep-flt-zorn": { note: { en: "The ultrafilter lemma (every filter is contained in an ultrafilter) uses Zorn’s lemma.", status: 'draft', basedOn: "v0.9.3#e71701c2" } },
  "eq.net-filter": { note: { en: "The two languages are equivalent. One uses an index set and eventual membership, and the other uses a family of sets and inclusion. Analysis texts tend to use nets, while set theory and topology texts tend to use filters.", status: 'draft', basedOn: "v0.9.3#19c3f4ea" } },
  "def-link.fa-complete-BEF": { note: { en: "What is needed here is metric completeness of $F$ (Cauchy sequences converge).", status: 'draft', basedOn: "v0.9.3#31d42f38" } },
  "def-link.fa-banach-openmap": { note: { en: "Completeness of $E$ is used to obtain an interior point (by Baire), and completeness of $F$ is used to remove the closure.", status: 'draft', basedOn: "v0.9.3#34e60512" } },
  "def-link.fa-banach-closedgraph": { note: { en: "Both spaces must be Banach spaces because the inverse operator theorem requires the product space to be complete.", status: 'draft', basedOn: "v0.9.3#b8a8ca85" } },
  "def-link.fa-linmap-op": { note: { en: "Bounded operators are the **continuous** linear maps: $L(E,F) \\supseteq B(E,F)$.", status: 'draft', basedOn: "v0.9.3#e2d17818" } },
  "def-link.fa-norm-op": { note: { en: "The operator norm is the norm on $B(E,F)$.", status: 'draft', basedOn: "v0.9.3#ee568123" } },
  "def-link.fa-normequiv-findim": { note: { en: "The theorem concludes that the norms are pairwise equivalent, expressed in terms of stronger and weaker norms.", status: 'draft', basedOn: "v0.9.3#513b2410" } },
  "def-link.fa-compact-riesz": { note: { en: "Compactness here is topological compactness. In metric spaces it is equivalent to sequential compactness, which the proof uses.", status: 'draft', basedOn: "v0.9.3#da0962cc" } },
  "def-link.fa-inducednorm-pol": { note: { en: "The $\\|\\cdot\\|$ in the polarization identity is the norm induced by the inner product.", status: 'draft', basedOn: "v0.9.3#dcce161a" } },
  "def-link.fa-orth-orthonormal": { note: { en: "“Orthogonal” in “orthogonal basis” means $f_i \\perp f_j$. Completeness is an additional topological condition.", status: 'draft', basedOn: "v0.9.3#d0531953" } },
  "def-link.fa-orthcompl": { note: { en: "Orthogonal decomposition uses the definition of $E^\\perp$.", status: 'draft', basedOn: "v0.9.3#2b3502b9" } },
  "def-link.fa-orthproj": { note: { en: "Orthogonal projection in finite dimensions is a special case, since every subspace is then closed.", status: 'draft', basedOn: "v0.9.3#65ecf076" } },
  "def-link.fa-nowhere-meager": { note: { en: "A set of the first category is defined as a countable union of nowhere dense sets.", status: 'draft', basedOn: "v0.9.3#657bf80d" } },
  "def-link.fa-meager-bairechar": { note: { en: "“Second category” and “nowhere dense” in the three equivalent characterizations are understood according to these definitions.", status: 'draft', basedOn: "v0.9.3#659d34a5" } },
  "def-link.fa-ck-complete": { note: { en: "Completeness is with respect to the uniform metric $\\Delta$.", status: 'draft', basedOn: "v0.9.3#7adc6cd3" } },
  "def-link.fa-hausdorff-ck": { note: { en: "$K$ must be Hausdorff. Compact Hausdorff spaces are the “good” compact spaces (continuous functions separate points, Urysohn’s lemma applies, and so on).", status: 'draft', basedOn: "v0.9.3#eed65718" } },
  "def-link.fa-uniformconv-ck": { note: { en: "Convergence in the distance $\\Delta$ is uniform convergence. It is the metric formulation of the same concept.", status: 'draft', basedOn: "v0.9.3#ada64ed1" } },
  "def-link.fa-equi-ascoli": { note: { en: "Condition (a) in the generalized Arzelà–Ascoli theorem is precisely this definition of equicontinuity.", status: 'draft', basedOn: "v0.9.3#320206b1" } },
  "def-link.fa-subalgebra-sw": { note: { en: "“Unital subalgebra that separates points” combines the three terms from this definition.", status: 'draft', basedOn: "v0.9.3#e4287ffa" } },
  "def-link.fa-arzela-classic": { note: { en: "These are two versions of the same theorem. `thm.arzela-ascoli-general` allows $E$ to be any metric space, and the classical version ($\\mathbb{R}$-valued and uniformly bounded) is a special case. Use an analogy edge and omit a theorem dependency.", status: 'draft', basedOn: "v0.9.3#e093177a" } },
  "def-link.fa-function-closedgraph": { note: { en: "“A map is its graph” follows directly from the definition of a map (a map = a special kind of relation = a set of ordered pairs), so $G(u)$ in the closed graph theorem is the same object.", status: 'draft', basedOn: "v0.9.3#a88ac67a" } },
  "def-link.fa-openmapping-holo": { note: { en: "⚠️ The theorems share a name but concern different objects. One says that a nonconstant holomorphic function is an open map, and the other says that a surjective bounded linear operator is an open map. Their proofs are unrelated.", status: 'draft', basedOn: "v0.9.3#69d47fe4" } },
  "def-link.fa-vs-norm2": { note: { en: "The domain of a norm is a vector space. The third axiom uses addition in that vector space.", status: 'draft', basedOn: "v0.9.3#659cb6b1" } },
  "def-link.fa-norm-normeq": { note: { en: "Comparing stronger and weaker norms involves two norms, both satisfying the three norm axioms.", status: 'draft', basedOn: "v0.9.3#a4c44345" } },
  "def-link.fa-compact-normeq": { note: { en: "The lower bound $\\alpha > 0$ relies on compactness of the unit sphere and attainment of the minimum by a continuous function.", status: 'draft', basedOn: "v0.9.3#555029ba" } },
  "def-link.fa-boundedop-opalgebra": { note: { en: "All three norms in the inequality $\\|vu\\| \\le \\|v\\|\\,\\|u\\|$ are operator norms, in the sense of that definition.", status: 'draft', basedOn: "v0.9.3#3cc02467" } },
  "def-link.fa-closed-nowhere": { note: { en: "“Nowhere dense” uses the closure $\\overline{A}$ and the interior, both covered by the definition concerning closed sets.", status: 'draft', basedOn: "v0.9.3#ec9ca885" } },
  "def-link.fa-topology-gdelta": { note: { en: "$G_\\delta$ / $F_\\sigma$ are built from open sets (as defined by the topology) and closed sets.", status: 'draft', basedOn: "v0.9.3#88e649e6" } },
  "def-link.fa-metric-baire": { note: { en: "The $B(x, \\varepsilon)$ in the nested-ball argument are balls in the metric space. Completeness gives a nonempty intersection of nested closed balls with radii $\\to 0$.", status: 'draft', basedOn: "v0.9.3#c555eff2" } },
  "def-link.fa-complete-baire": { note: { en: "The two approaches to proving Baire’s theorem use completeness in the metric case and compactness in the locally compact case, respectively.", status: 'draft', basedOn: "v0.9.3#82e4f26f" } },
  "def-link.fa-closed-closedcover": { note: { en: "The lemma concerns a cover by closed sets. Taking complements of interiors and unions of exteriors uses the laws governing operations on closed sets.", status: 'draft', basedOn: "v0.9.3#e61ac2fb" } },
  "def-link.fa-continuous-equi": { note: { en: "Equicontinuity = continuity of each $f$ plus an $\\varepsilon$-$\\delta$ condition that is **uniform over the whole family**.", status: 'draft', basedOn: "v0.9.3#ed153c91" } },
  "def-link.fa-vs-subalgebra": { note: { en: "A subalgebra is a vector space (closed under addition and scalar multiplication) that is also closed under multiplication.", status: 'draft', basedOn: "v0.9.3#597f2db0" } },
  "def-link.fa-subalg-lattice": { note: { en: "The lemma’s hypothesis of a unital closed subalgebra combines the subalgebra, closedness, and $1 \\in A$ conditions from this definition.", status: 'draft', basedOn: "v0.9.3#b919f0b3" } },
  "def-link.fa-ck-bernstein": { note: { en: "In “$\\|B_n f - f\\|_\\infty \\to 0$,” $\\|\\cdot\\|_\\infty$ is the uniform norm on $C[0,1]$.", status: 'draft', basedOn: "v0.9.3#d8c47774" } },
  "def-link.fa-hausdorff-baire": { note: { en: "Local compactness together with the Hausdorff property gives a compact neighborhood basis, allowing the nested-ball argument to use a chain of compact neighborhoods.", status: 'draft', basedOn: "v0.9.3#7579b2fc" } },
  "def-link.fa-op-pointwise": { note: { en: "The conclusion “$u \\in B(E, F)$” states precisely that the operator belongs to the space of bounded linear operators.", status: 'draft', basedOn: "v0.9.3#c0874273" } },
  "def-link.fa-ueq-metric": { note: { en: "The uniform version uses the metric $\\delta$ to express “$\\delta(x,y) < \\eta$”. On a topological space, only a pointwise definition is available.", status: 'draft', basedOn: "v0.9.3#d70dc924" } },
  "def-link.fa-ueq-thm": { note: { en: "The theorem concludes precisely this uniform version.", status: 'draft', basedOn: "v0.9.3#4534e418" } },
  "dep.sym-complex-thm-stone-weierstrass-complex": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.banach-ckcomplete": { note: { en: "The completeness of C(K,E) in the conclusion presupposes the definition of a Banach space (a complete normed space)", status: 'draft', basedOn: "v0.9.3#64679e6b" } },
  "dep-link.meager-baire": { note: { en: "The conclusions of the Baire category theorem that a countable intersection of dense open sets is dense and that every nonempty open set is of the second category are equivalent. The first and second categories must therefore be defined before stating the theorem.", status: 'draft', basedOn: "v0.9.3#28932188" } },
  "dep-link.nowhere-baire": { note: { en: "The equivalent formulation of the Baire category theorem in which a countable union of nowhere dense closed sets has empty interior directly uses the notion of nowhere density.", status: 'draft', basedOn: "v0.9.3#a8de9685" } },
  "dep-link.closedset-meager": { note: { en: "Nowhere density is defined in terms of empty interior, while category uses countable unions of nowhere dense closed sets. Both require closed sets and closures.", status: 'draft', basedOn: "v0.9.3#c04469af" } },
  "dep-link.meager-openmap": { note: { en: "Textbooks often state the open mapping theorem using “$u(E)$ is of the second category.” The first step of the proof uses category itself: $E = \\bigcup_k \\overline{u(kB_E)}$, so one of the closures contains an interior point.", status: 'draft', basedOn: "v0.9.3#176e3d90" } },
  "dep-link.nowhere-openmap": { note: { en: "The image having an interior point and the image failing to be nowhere dense are presented as two sides of the same statement, using the complement characterization of nowhere density.", status: 'draft', basedOn: "v0.9.3#489ea4e5" } },
  "dep-link.meager-closedcover": { note: { en: "The assertion that if countably many closed sets cover $X$, then the union of their interiors is dense, is the closed-set form of the Baire category theorem. It is equivalent to saying that $X$ is of the second category.", status: 'draft', basedOn: "v0.9.3#b4cc79b4" } },
  "dep-link.meager-lcb": { note: { en: "Saying that a locally compact Hausdorff space is a Baire space means that every nonempty open set in it is of the second category.", status: 'draft', basedOn: "v0.9.3#318dfeb4" } },
  "dep.real-interval": { note: { en: "An interval is described using the total order on $\\mathbb{R}$, denoted by $\\le$. Everything between the endpoints counts.", status: 'draft', basedOn: "v0.9.3#9c8860b4" } },
  "dep.real-sequence": { note: { en: "The $|x_n - x| < \\varepsilon$ in the limit uses the absolute value and order on the real numbers.", status: 'draft', basedOn: "v0.9.3#d113fb1f" } },
  "dep.real-series": { note: { en: "Convergence of a series = convergence of the **sequence** of partial sums.", status: 'draft', basedOn: "v0.9.3#879b74b5" } },
  "dep.real-continuous": { note: { en: "Continuity is defined by “when $x \\to x_0$, $f(x) \\to f(x_0)$,” in the language of limits.", status: 'draft', basedOn: "v0.9.3#76deb578" } },
  "dep.real-derivative": { note: { en: "The derivative is a **limit**, specifically the limit of the difference quotient.", status: 'draft', basedOn: "v0.9.3#4425dd34" } },
  "dep.continuous-derivative": { note: { en: "Differentiability $\\implies$ continuity follows directly from the definition of the derivative.", status: 'draft', basedOn: "v0.9.3#ad24187a" } },
  "dep.real-complex": { note: { en: "$\\mathbb{C} = \\mathbb{R}^2$, and both the real and imaginary parts are real numbers.", status: 'draft', basedOn: "v0.9.3#fd2ec78d" } },
  "def-link.mc-continuous": { note: { en: "This theorem gives the explicit form of metric continuity on $\\mathbb{R}$.", status: 'draft', basedOn: "v0.9.3#d2e91ce4" } },
  "def-link.continuous-specialcase": { note: { en: "For $\\mathbb{R}\\to\\mathbb{R}$, the $\\varepsilon$-$\\delta$ criterion is the metric-space specialization of the definition of a continuous map. The reverse direction fails. Deriving the $\\varepsilon$-$\\delta$ criterion from the definition of a continuous map also requires the metric structure of $\\mathbb{R}$.", status: 'draft', basedOn: "v0.9.3#5c6cca85" } },
  "dep.sym-complex-def-derivative": { note: { en: "The statement concerns the complex numbers $\\mathbb{C}$ (notational dependency)", status: 'draft', basedOn: "v0.9.3#9f776ab5" } },
  "dep.lpbanach-norm": { note: { en: "In the statement “$L^{p}$ is a Banach space,” the space is a **normed space**. The norm $\\|\\cdot\\|_{p}$ must be specified first because completeness is relative to it. Previously, all outgoing edges from `def.lp-norm` stayed within measure theory and analysis, with none leading to functional analysis.", status: 'draft', basedOn: "v0.9.3#c6958dd6" } },
  "dep.lpbanach-banach": { note: { en: "Likewise, the conclusion’s predicate “is a Banach space” was itself unreferenced. The only incoming edge to `def.banach-space` originally came from `def.complete`, leaving $L^{p}$ disconnected from functional analysis.", status: 'draft', basedOn: "v0.9.3#38ba5c29" } },
  "dep.tensormodule-tensorvs": { note: { en: "An $K$-vector space is an $K$-module, so the tensor product of vector spaces is a special case of the tensor product of modules ($R = K$). ⛔ The reverse edge `imp.derived-multilinear-tensor-dual` is a **pink edge** (`layer:false`, with a proof that returns to the result using advanced tools). The full graph therefore shows a visible cycle. That is the intended meaning of a pink edge. It is excluded from layering, so the cycle can stay.", status: 'draft', basedOn: "v0.9.3#1b9a481d" } },
  "e174.analogy": { note: { en: "One node concerns a group homomorphism $G/\\ker\\varphi \\cong \\operatorname{im}\\varphi$ and the other a linear map $V/\\ker T \\cong \\operatorname{im} T$.\n\n**Neither implies the other** (a group need not be a vector space, and the additive group of a vector space does not determine scalar multiplication). The proofs are **identical word for word**: well-definedness $\\to$ homomorphism (linearity) $\\to$ bijectivity. The note on the group version already makes this explicit: “It is a general theorem for the set + operations + axioms format, applicable beyond groups.”\n\n⭐ This edge therefore serves only as an **analogy**. A single statement that genuinely covers both requires a node for the first isomorphism theorem in abelian categories.", status: 'draft', basedOn: "v0.9.3#aefd2583" } },
  "e179.analogy": { note: { en: "Both say that “everything **local/finite** works $\\implies$ the whole works too”:\n\nTychonoff’s theorem builds compactness of the product space from compactness of each coordinate space. The compactness theorem builds a model of the whole set from the existence of models for every finite subset.\n\nThe two are indeed connected through Boolean algebra / Stone duality (compactness for propositional logic follows from compactness of Cantor space). Making that connection requires carrying Stone representation duality through to logic, which the graph has yet to do, so only the analogy is recorded.", status: 'draft', basedOn: "v0.9.3#7659c4e3" } },
  "dep.poly-quotient": { note: { en: "A polygonal representation is the quotient space obtained by gluing the boundary according to the pairings.", status: 'draft', basedOn: "v0.9.3#0e0c6f30" } },
  "dep.poly-closed": { note: { en: "The object constructed by a polygonal representation is a closed surface (the manifold property must be verified after gluing).", status: 'draft', basedOn: "v0.9.3#7680a7c2" } },
  "dep.handle-connsum": { note: { en: "Adding a handle is equivalent to taking the connected sum with a torus.", status: 'draft', basedOn: "v0.9.3#40b18845" } },
  "dep.handle-torus": { note: { en: "The basic example of a handle is the torus.", status: 'draft', basedOn: "v0.9.3#98f37b81" } },
  "dep.handle-genus": { note: { en: "Adding a handle increases the orientable genus by 1.", status: 'draft', basedOn: "v0.9.3#6617ef33" } },
  "dep.crosscap-projective": { note: { en: "The basic example of a crosscap is the projective plane.", status: 'draft', basedOn: "v0.9.3#2b5c5159" } },
  "dep.crosscap-mobius": { note: { en: "Adding a crosscap amounts to gluing in a Möbius band along its boundary.", status: 'draft', basedOn: "v0.9.3#b81262c4" } },
  "dep.crosscap-connsum": { note: { en: "Adding a crosscap is equivalent to taking the connected sum with a projective plane.", status: 'draft', basedOn: "v0.9.3#35f8bcb3" } },
  "dep.nongenus-crosscap": { note: { en: "Nonorientable genus is defined by the number of crosscaps.", status: 'draft', basedOn: "v0.9.3#9deb778f" } },
  "dep.nongenus-euler": { note: { en: "The formula chi = 2 - k depends on the Euler characteristic.", status: 'draft', basedOn: "v0.9.3#4ad14944" } },
  "dep.nongenus-connsum": { note: { en: "The definition uses connected sums of projective planes.", status: 'draft', basedOn: "v0.9.3#d8ed631c" } },
  "dep.smoothmanifold-connectedsum": { note: { en: "The connected sum is formed on $n$-dimensional **manifolds** and presupposes the notions of open balls and boundary spheres.", status: 'draft', basedOn: "v0.9.3#abdb8b3f" } },
  "dep.connectedsum-genus": { note: { en: "The intuition that “$g$ is a connected sum of several tori” requires the notion of connected sum. The statement itself is a **theorem** (the classification theorem, to be added in the next pass) and is unnecessary for the definition.", status: 'draft', basedOn: "v0.9.3#a24b0679" } },
  "e181.analogy": { note: { en: "On a closed orientable surface, $\\chi(M) = 2 - 2g(M)$. The two numbers determine each other, so counting Betti numbers and counting holes amount to the same thing.\n\n⚠ The graph **keeps this as an analogy** rather than an implication. It requires a proper theorem node (to be added in the next pass), and recording an implication now would treat an unwritten proof as already established.", status: 'draft', basedOn: "v0.9.3#906940c6" } },
  "dep.topology-triangulation": { note: { en: "Triangulation is defined for **topological spaces** (a topology is needed to talk about homeomorphisms). This edge was previously missing, so “topological space” was merely a term in the triangulation node.", status: 'draft', basedOn: "v0.9.3#e1d07e6c" } },
  "dep.triangulation-eulerchar": { note: { en: "The proposition “chi is independent of the triangulation” **presupposes a triangulation** (chi is computed from one). It does exactly what the triangulation note calls for: first prove that a quantity defined using a triangulation is independent of the choice of triangulation.", status: 'draft', basedOn: "v0.9.3#192e6121" } },
  "dep.triangulation-rado": { note: { en: "Radó’s theorem concludes that such a $(K,h)$ exists.", status: 'draft', basedOn: "v0.9.3#436d7fd5" } },
  "dep.compact-rado": { note: { en: "Compactness is a necessary hypothesis for Radó’s theorem (open surfaces can also be triangulated, but require a locally finite $K$ and a different proof).", status: 'draft', basedOn: "v0.9.3#84f48566" } },
  "dep.rado-classification": { note: { en: "This is the **first step** of the classification theorem. A triangulation is needed before combinatorial simplifications such as deleting triangles or flipping edges. The edge records a dependency rather than a strict implication.", status: 'draft', basedOn: "v0.9.3#890ccc05" } },
  "dep.triangulation-simphomology": { note: { en: "The statement “singular homology $=$ simplicial homology” **implicitly assumes** that the surface can be triangulated (a triangulation is needed to compute simplicial homology). This assumption was previously invisible in the graph.", status: 'draft', basedOn: "v0.9.3#a6b55028" } },
  "dep.compact-closedsurface": { note: { en: "The first part of being a closed surface is being **compact** (the other is having no boundary).", status: 'draft', basedOn: "v0.9.3#e952f6f5" } },
  "dep.closedsurface-classification": { note: { en: "The theorem concerns closed surfaces.", status: 'draft', basedOn: "v0.9.3#436b6bfc" } },
  "dep.connectedsum-classification": { note: { en: "Both standard forms in the conclusion are **connected sums** (of tori or of projective planes).", status: 'draft', basedOn: "v0.9.3#266dd4c3" } },
  "dep.genus-classification": { note: { en: "The classification invariant in the orientable case is the genus $g$. Nonhomeomorphic surfaces are distinguished by $g$ (or equivalently by $\\chi$).", status: 'draft', basedOn: "v0.9.3#9edff101" } },
  "dep.classsurf-genus": { note: { en: "Surfaces are classified by orientability and genus.", status: 'draft', basedOn: "v0.9.3#5992e618" } },
  "dep.classification-eulerchargenus": { note: { en: "The proof of the proposition **does not use** the classification theorem (the node’s note specifies Radó’s theorem plus an elementary argument, and $\\chi=2-2g$ can be computed directly from homology). This edge is kept solely for the analogy “standard form = connected sum of $g$ tori.”", status: 'draft', basedOn: "v0.9.3#5ed4f89b" } },
  "dep.genus-eulerchargenus": { note: { en: "The proposition says precisely that $\\chi$ and $g$ determine each other. The definition of $g$ is required here.", status: 'draft', basedOn: "v0.9.3#2f645c0e" } },
  "dep.classification-eulercharnonor": { note: { en: "The nonorientable standard form likewise serves only as an analogy. The proposition already assumes standard form, so the classification theorem is unnecessary.", status: 'draft', basedOn: "v0.9.3#b4e4e706" } },
  "dep.closedsurface-sphere": { note: { en: "The sphere satisfies all three conditions for a closed surface: it is compact (a closed and bounded subset of $\\mathbb{R}^{3}$), connected, and without boundary.", status: 'draft', basedOn: "v0.9.3#bb847d03" } },
  "dep.closedsurface-torus": { note: { en: "$S^{1} \\times S^{1}$ is a product of compact spaces and hence compact. Connectedness and the absence of boundary follow similarly.", status: 'draft', basedOn: "v0.9.3#56940a31" } },
  "dep.closedsurface-rp2": { note: { en: "The antipodal quotient of a compact space is still compact as a continuous image. Connectedness and the absence of boundary are inherited.", status: 'draft', basedOn: "v0.9.3#cb4c6258" } },
  "dep.connectedsum-klein": { note: { en: "The definition of the Klein bottle ($\\mathbb{RP}^{2} \\# \\mathbb{RP}^{2}$) directly uses the connected sum.", status: 'draft', basedOn: "v0.9.3#14a00e6b" } },
  "dep.closedsurface-klein": { note: { en: "The connected sum of two closed surfaces is still a closed surface (compactness, connectedness, and the absence of boundary are all preserved).", status: 'draft', basedOn: "v0.9.3#3368f61f" } },
  "dep.genus-sphere": { note: { en: "The sphere's $g = 0$ is no convention: $H_{1}(S^{2}) = 0$, so $\\tfrac{1}{2}\\operatorname{rank} = 0$.", status: 'draft', basedOn: "v0.9.3#391ddc64" } },
  "dep.genus-torus": { note: { en: "For the torus's $g = 1$, we have $H_{1} \\cong \\mathbb{Z}^{2}$, which has rank 2. Dividing by 2 gives 1.", status: 'draft', basedOn: "v0.9.3#1cf2dc60" } },
  "dep.eulerchargenus-torus": { note: { en: "The value “$\\chi = 0$” in the example is obtained directly from this proposition ($2 - 2g$), without a separate calculation.", status: 'draft', basedOn: "v0.9.3#68b80c1e" } },
  "dep.eulercharnonor-rp2": { note: { en: "“$k = 1$, $\\chi = 1$” are read off from the criterion for the nonorientable case ($2 - k$).", status: 'draft', basedOn: "v0.9.3#cb4ba8ee" } },
  "dep.eulercharnonor-klein": { note: { en: "The same applies to “$k = 2$, $\\chi = 0$.”", status: 'draft', basedOn: "v0.9.3#76dbf1c2" } },
  "def-link.toporient-eg": { note: { en: "Lemma D uses an oriented atlas to orient the 2-simplices consistently", status: 'draft', basedOn: "v0.9.3#20dd2d5b" } },
  "def-link.toporient-nonor": { note: { en: "Nonorientable means that no oriented atlas exists. The standard form is a connected sum of $k$ copies of $\\mathbb{RP}^{2}$", status: 'draft', basedOn: "v0.9.3#788f5054" } },
  "dep.eulernonorient-genus": { note: { en: "The Euler characteristic of a nonorientable surface is expressed in terms of its genus.", status: 'draft', basedOn: "v0.9.3#c678dec5" } },
  "dep.klein-genus": { note: { en: "The Klein bottle has nonorientable genus 2.", status: 'draft', basedOn: "v0.9.3#a5f2ec68" } },
  "dep.sym-real-def-topological-orientability": { note: { en: "The statement concerns the real numbers $\\mathbb{R}$ (notation dependency)", status: 'draft', basedOn: "v0.9.3#0453d27b" } },
  "dep.field-fieldext": { note: { en: "Both ends of the extension are **fields**. The concept of a “subfield” comes from taking a substructure of `def.field`.", status: 'draft', basedOn: "v0.9.3#d2215de7" } },
  "dep.algext-normal": { note: { en: "Normality is a property specific to **algebraic extensions** (as opposed to arbitrary extensions).", status: 'draft', basedOn: "v0.9.3#65312fe7" } },
  "dep.fieldext-galoisgroup": { note: { en: "The Galois group consists of the automorphisms fixing $F$ and acting on $K$. The extension $K/F$ must be given first.", status: 'draft', basedOn: "v0.9.3#00d8c1ab" } },
  "dep.group-galoisgroup": { note: { en: "Automorphisms form a group under composition. This is where group theory enters field theory.", status: 'draft', basedOn: "v0.9.3#3a9dfe3d" } },
  "dep.normal-galoisext": { note: { en: "Galois = normal + separable + finite.", status: 'draft', basedOn: "v0.9.3#bf004731" } },
  "dep.separable-galoisext": { note: { en: "Separability ensures that there are “enough automorphisms” ($|\\operatorname{Gal}| = [K:F]$).", status: 'draft', basedOn: "v0.9.3#4ec7e3c6" } },
  "dep.galoisgroup-galoisext": { note: { en: "The equivalent characterizations of Galois extensions are all stated in terms of the Galois group ($|G| = [K:F]$, $K^{G} = F$).", status: 'draft', basedOn: "v0.9.3#44b036f0" } },
  "dep.galoisgroup-radical": { note: { en: "The left-hand side of the theorem says “expressible by radicals,” and the right-hand side says that $\\operatorname{Gal}(f)$ is solvable. That is the bridge.", status: 'draft', basedOn: "v0.9.3#3e29f179" } },
  "dep.solvable-radical": { note: { en: "Here “solvable” has the **group-theoretic** meaning (having a normal series with abelian quotients), distinct from the solvability of an equation. The theorem asserts precisely that the two are equivalent.", status: 'draft', basedOn: "v0.9.3#a5ec7857" } },
  "dep.fixedfield-galois": { note: { en: "The fixed field consists of the elements fixed by the automorphisms in the Galois group.", status: 'draft', basedOn: "v0.9.3#5254b452" } },
  "dep.fixedfield-field": { note: { en: "The fixed field is a subfield of the extension field.", status: 'draft', basedOn: "v0.9.3#28c031cf" } },
  "dep.algebraic-closure": { note: { en: "An algebraic closure is a field extension.", status: 'draft', basedOn: "v0.9.3#543375f3" } },
  "dep.closure-algebraically-closed": { note: { en: "An algebraic closure requires the extension field to be algebraically closed.", status: 'draft', basedOn: "v0.9.3#be28843b" } },
  "dep.fieldext-algclosed": { note: { en: "An algebraic closure combines two conditions, “algebraic extension + algebraically closed,” so a field extension is needed first.", status: 'draft', basedOn: "v0.9.3#ab34eb96" } },
  "dep.complex-algclosed": { note: { en: "$\\mathbb{C}$ is the **first example** of an algebraically closed field (by the fundamental theorem of algebra), and $\\overline{\\mathbb{Q}}$ is taken in it.", status: 'draft', basedOn: "v0.9.3#684da8b0" } },
  "dep.algext-separable": { note: { en: "Separability is a property of **algebraic extensions** (there is no “minimal polynomial” to speak of for a transcendental extension).", status: 'draft', basedOn: "v0.9.3#8dd73dc3" } },
  "dep.ext-empty": { note: { en: "$\\emptyset$ is first given as a primitive object. This theorem shows that **the axiom schema of separation alone, without taking it as primitive**, yields the same set, and the axiom of extensionality gives its uniqueness.", status: 'draft', basedOn: "v0.9.3#b3672152" } },
  "dep.nullset-ae": { note: { en: "By definition, a.e. means that “the exceptional set is a **null set**.”", status: 'draft', basedOn: "v0.9.3#865eb379" } },
  "dep.measure-ae": { note: { en: "In $\\mu(E) = 0$, $\\mu$ is a measure. The term a.e. is used on measure spaces.", status: 'draft', basedOn: "v0.9.3#cbd41c1e" } },
  "dep.real-metric": { note: { en: "Distances take values in $d : X \\times X \\to [0, +\\infty) \\subseteq \\mathbb{R}$, using the order and absolute value of the real numbers.", status: 'draft', basedOn: "v0.9.3#51a7aee9" } },
  "dep.interval-bv": { note: { en: "In the definition of absolute continuity, “any finite collection of pairwise disjoint intervals” refers to intervals.", status: 'draft', basedOn: "v0.9.3#542adb84" } },
  "dep.complex-integral-complex": { note: { en: "The integral of a complex-valued function is split into the two real-valued integrals $\\operatorname{Re} f$ and $\\operatorname{Im} f$.", status: 'draft', basedOn: "v0.9.3#0de64273" } },
  "dep.complex-complex-measure": { note: { en: "A complex measure takes values in $\\mathbb{C}$, so it is automatically finite.", status: 'draft', basedOn: "v0.9.3#507ff03d" } },
  "dep.continuous-continuous-measurable": { note: { en: "To show “continuous $\\implies$ Borel measurable,” translate the $\\varepsilon$-$\\delta$ definition of continuity into a statement about preimages of open sets.", status: 'draft', basedOn: "v0.9.3#aa64a4dd" } },
  "dep.empty-sep": { note: { en: "The empty set is obtained from the axiom schema of separation $\\{x \\in A : x \\ne x\\}$ (with $A$ arbitrary).", status: 'draft', basedOn: "v0.9.3#00526928" } },
  "dep.closedsurface-genus": { note: { en: "Genus is defined only for **closed orientable surfaces** (the formula $\\tfrac{1}{2}\\operatorname{rank} H_{1}$ depends on both closedness and orientability), so a closed surface is a prerequisite. This edge was previously missing. The definition of `def.genus` said “closed orientable surface” without linking to the concept.", status: 'draft', basedOn: "v0.9.3#4c32a842" } },
  "dep.connectedsum-sphere": { note: { en: "The sphere is the **identity element** for the connected sum ($S^{2}\\# M \\cong M$). This statement requires the connected sum, so the explanation of the example depends on it.", status: 'draft', basedOn: "v0.9.3#a8c58a35" } },
  "e186.analogy": { note: { en: "**Same name, different objects**, exactly the issue identified in audit B2:\n\n- `def.regular-surface` describes “the image of $U \\subseteq \\mathbb{R}^{2}$ under $r$ into $\\mathbb{R}^{3}$,” with an **embedding, metric, and curvature** built in.\n\n- The definition only specifies “compact, connected, without boundary, and locally homeomorphic to $\\mathbb{R}^{2}$,” with **no ambient space at all**.\n\nSo “sphere” refers to different things on the two sides. One is the unit sphere in $\\mathbb{R}^{3}$ (with area and Gauss curvature), and the other is the abstract $S^{2}$ (with only a topology).\n\n⛔ Neither a definition nor an implication edge is valid. One is embedded in $\\mathbb{R}^{3}$ and the other has no embedding. Neither is a prerequisite for the other.", status: 'draft', basedOn: "v0.9.3#c076f5ce" } },
  "e189.analogy": { note: { en: "One Chinese term, two ways of counting (the very reason this proposition exists):\n\n- Orientable case: $g = \\tfrac{1}{2}\\operatorname{rank} H_{1}$, $\\chi = 2 - 2g$.\n\n- Nonorientable case: $k$ (the connected sum of that many projective planes), $\\chi = 2 - k$.\n\n⚠ The slopes differ ($-2$ vs $-1$), so **the same $\\chi$ describes different surfaces in the two families**. $\\chi = 0$ can be either the torus ($g=1$) or the Klein bottle ($k=2$).\n\n⛔ A definition edge is invalid. The “divide by 2” in `def.genus` relies on the free rank of $H_{1}$ being **even**. In the nonorientable case the rank can be odd (the free rank of $\\mathbb{RP}^{2}$ is 0), and the formula fails.", status: 'draft', basedOn: "v0.9.3#39ae0253" } },
  "e190.analogy": { note: { en: "**Same name, different objects**. Both are called “subspaces” in Chinese:\n\n- `def.subspace`: a **linear** subspace of $V$, required to contain zero and be closed under addition and scalar multiplication (algebraic conditions).\n\n- `def.subspace-topology`: a **subset** of $X$, denoted $A$, equipped with the topology specified by “$U \\cap A$ is open” (a purely topological operation, with $A$ allowed to be any subset).\n\n⚠ The two are related only in special cases such as “a linear subspace of $\\mathbb{R}^{n}$ equipped with the subspace topology.” In general, one is an algebraic structure and the other restricts a topology to a subset.\n\n⛔ Neither a definition nor an implication edge is valid. Neither concept is a prerequisite for the other, and even settling on a direction is difficult. An analogy edge is the only way to record the shared name and keep readers from clicking through to the wrong concept.", status: 'draft', basedOn: "v0.9.3#b315e860" } },
  "dep.gap-simple-approximation-uniform-convergence": { note: { en: "The statement mentions “uniform convergence”: “and **the convergence is also uniform on sets on which $f$ is bounded**.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#a6bafa2d" } },
  "dep.gap-simple-approximation-pointwise-convergence": { note: { en: "The statement mentions “pointwise convergence”: “**(b)** In general (with $f : X \\to \\mathbb{C}$ measurable), one can choose a sequence of simple functions whose absolute values increase pointwise and which converges pointwise to $f$: …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#e02b1ae6" } },
  "dep.gap-quotient-vs-subspace": { note: { en: "The statement mentions “subspace”: “Let $U \\subseteq V$ be a subspace.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#d29b9a41" } },
  "dep.gap-quotient-vs-linear-map": { note: { en: "The statement mentions “linear map”: “The quotient maps $\\pi : V \\to V/U$ and $v \\mapsto v + U$ are surjective linear maps, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#b53ffbd2" } },
  "dep.gap-single-valued-branch-analytic-continuation": { note: { en: "The statement mentions “analytic continuation”: “If $F$ comes from analytic continuation, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#ab68cd75" } },
  "dep.gap-lifting-path-homotopy": { note: { en: "The statement mentions “path homotopy”: “If $F$ is a path homotopy (with both endpoints fixed), …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#33cc01d5" } },
  "dep.gap-quotient-universal-vs-subspace": { note: { en: "The statement mentions “subspace”: “Let $U \\subseteq V$ be a subspace, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#a7e9401e" } },
  "dep.gap-quotient-universal-vs-linear-map": { note: { en: "The statement mentions “linear map”: “Then for every linear map $T : V \\to W$ satisfying $U \\subseteq \\ker T$, there exists a **unique** linear map $\\overline{T} : V/U \\to W$ making the following diagram commute: …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#2f0c4cbc" } },
  "dep.gap-free-solid-product-condensed-abelian-group": { note: { en: "The statement mentions “condensed abelian group”: “For any profinite set $S$, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#0494c051" } },
  "dep.gap-solid-hypercover-condensed-abelian-group": { note: { en: "The statement mentions “condensed abelian group”: “then the complex of condensed abelian groups.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#e7e61549" } },
  "dep.gap-condab-generated-condensed-abelian-group": { note: { en: "The statement mentions “condensed abelian group”: “$\\mathrm{CondAb}$ is generated by **finitely presented projective** condensed abelian groups.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#0a73b135" } },
  "dep.gap-similarity-minimal-poly": { note: { en: "The statement mentions “minimal polynomial”: “Similarity invariants: rank, trace, determinant, characteristic polynomial (and hence the eigenvalues and their algebraic multiplicities), …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#20d68fd1" } },
  "dep.gap-solvable-quotients-normal-subgroup": { note: { en: "The statement uses “normal subgroup.” $N\\trianglelefteq G$ appears once in (b) and once in (c). This edge previously pointed to the field-theoretic `def.normal-extension`. In informal group-theory usage, “normal extension” is just another way to say “normal subgroup,” so the edge targeted the wrong concept. It now points to `def.normal-subgroup`.", status: 'draft', basedOn: "v0.9.3#69e58159" } },
  "dep.gap-gauss-curvature-second-fundamental-form": { note: { en: "The statement mentions “second fundamental form”: “On the other hand, if $h_{ij}$ is the coefficient matrix of the second fundamental form in the same frame, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#30e675a7" } },
  "dep.gap-harmonic-holomorphic": { note: { en: "The statement mentions “holomorphic function”: “Equivalent characterization (local): $u$ is the real part of a holomorphic function (this is always possible on a disk and is also possible on a simply connected domain, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#05de0044" } },
  "dep.gap-ab-of-categories-topo-ab-group": { note: { en: "The statement mentions “topological abelian group”: “- $\\mathrm{Ab}(\\mathbf{Top})$ = **topological abelian groups**.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#12d336f9" } },
  "dep.gap-copowers-give-adjoint-representable": { note: { en: "The statement mentions “representable functor”: “If the small category $\\mathcal{C}$ has **copowers**, then every representable functor $h_{X}$ has a left adjoint: …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#9a1ca874" } },
  "dep.gap-similarity-char-poly": { note: { en: "The statement mentions “characteristic polynomial”: “Similarity invariants: rank, trace, determinant, characteristic polynomial (and hence the eigenvalues and their algebraic multiplicities), …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#3e556e5b" } },
  "dep.gap-inner-product-bilinear-form": { note: { en: "The statement mentions “bilinear form”: “Over the reals, an inner product is a positive-definite symmetric bilinear form.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#313e2879" } },
  "dep.gap-operator-adjoint-orthonormal-set": { note: { en: "The statement mentions “orthonormal basis”: “In the standard orthonormal basis, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#b4a95c51" } },
  "dep.gap-regular-surface-differential-map": { note: { en: "The statement mentions “tangent map”: “The tangent map $\\mathrm{d}r\\colon T_{p}U \\to T_{r(p)}S$ is given by $\\mathrm{d}r(\\partial_{u}) = r_{u}$, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#ddb4d4ad" } },
  "dep.gap-vector-bundle-linear-isomorphism": { note: { en: "The statement mentions “linear isomorphism”: “2. **Local trivialization**: Every point has an open neighborhood $U$ and a diffeomorphism $\\Phi : \\pi^{-1}(U) \\to U \\times \\mathbb{R}^{k}$ such that $\\Phi$ commutes with the projections ($\\operatorname{pr}_{1} \\circ \\Phi = \\pi$), …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#d4bb76b2" } },
  "dep.gap-form-on-manifold-jacobian": { note: { en: "The statement mentions “Jacobian matrix”: “On the overlap of the two charts, the two sets of coefficients are converted into one another by the order-$k$ minors of the Jacobian matrix. The minors are smooth, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#83276357" } },
  "dep.gap-fiber-bundle-vector-bundle": { note: { en: "The statement mentions “vector bundle”: “**What it says**: A vector bundle only requires that ‘the fibers are vector spaces.’” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#b2fa5e48" } },
  "dep.gap-eigenspace-char-poly": { note: { en: "The statement mentions “characteristic polynomial”: “The multiplicity of $\\lambda$ in the characteristic polynomial is called its **algebraic multiplicity**.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#698a2220" } },
  "dep.gap-invariant-subspace-kernel-image-vs": { note: { en: "The statement mentions “kernel and image”: “The kernel and image of $T$ are also both $T$-invariant.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#71ece114" } },
  "dep.gap-similarity-determinant": { note: { en: "The statement mentions “determinant”: “Similarity invariants: rank, trace, determinant, characteristic polynomial (and hence the eigenvalues and their algebraic multiplicities), …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#b6a6ad25" } },
  "dep.gap-det-as-exterior-determinant": { note: { en: "The statement mentions “determinant”: “That number is precisely the determinant: …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#269177e6" } },
  "dep.gap-tensor-functor-properties-tensor-module": { note: { en: "The statement mentions “tensor product”: “The tensor product is a **bifunctor** $\\otimes_{R} : \\mathbf{Mod}\\text{-}R \\times R\\text{-}\\mathbf{Mod} \\to \\mathbf{Ab}$, and: …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#7886454b" } },
  "dep.gap-etale-space-continuous-map": { note: { en: "The statement mentions “continuous map”: “A continuous map $p : E \\to X$ is called an **étale map** (local homeomorphism) if every $e \\in E$ has an open neighborhood $V \\ni e$ such that $p(V)$ is open in $X$, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#16267f2c" } },
  "dep.gap-local-trivialization-smooth-manifold": { note: { en: "The statement mentions “smooth manifold”: “**Smooth case**: If all of $E, B, F$ are smooth manifolds and $\\pi$ is smooth, replace ‘homeomorphism’ by ‘**diffeomorphism**’ in the definition, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#4ee8d1d6" } },
  "dep.gap-schur-triangularization-normal-matrix": { note: { en: "The statement mentions “normal matrix”: “**What it does**: Unitary diagonalization is too strong a requirement (only normal matrices admit it, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#431233f0" } },
  "dep.gap-schur-triangularization-orthogonally-similar": { note: { en: "The statement mentions “orthogonally similar”: “Real case: Every real square matrix is orthogonally similar to a matrix in **real Schur form**, that is, block upper triangular, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#b578dc08" } },
  "dep.gap-bounded-operators-banach-banach-space": { note: { en: "The statement mentions “Banach space”: “Then $(B(E, F), \\|\\cdot\\|)$ is a Banach space.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#6d558656" } },
  "dep.gap-baire-locally-compact": { note: { en: "The statement mentions “locally compact Hausdorff space”: “Let $X$ be a complete metric space (or a locally compact Hausdorff space).” The link lets readers reach the definition of local compactness.", status: 'draft', basedOn: "v0.9.3#5845c42b" } },
  "dep.gap-baire-hausdorff": { note: { en: "Readers also need to be able to follow “Hausdorff” in the same sentence to its definition.", status: 'draft', basedOn: "v0.9.3#15bb1623" } },
  "dep.gap-commutative-diagram-natural-transformation": { note: { en: "The statement mentions “natural transformation”: “All such diagrams have natural transformations as morphisms, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#68b0d25a" } },
  "dep.gap-presheaf-natural-transformation": { note: { en: "The statement mentions “natural transformation”: “The **morphisms** between presheaves are the natural transformations between them.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#5e5971c1" } },
  "dep.gap-stonean-projective-condensed-abelian-group": { note: { en: "The statement mentions “condensed abelian group”: “Then the free condensed abelian group $\\mathbb{Z}\\cdot F$ is a **finitely presented** **projective** condensed abelian group.” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#fe269482" } },
  "dep.gap-continuous-hom-condensed-condensed-abelian-group": { note: { en: "The statement mentions “condensed abelian group”: “If $M, N$ are two topological abelian groups and $M$ is **compactly generated**, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#06465c84" } },
  "dep.gap-tietze-banach-banach-space": { note: { en: "The statement mentions “Banach space”: “Let $X$ be a **normal** topological space and $K \\subseteq X$ a **compact** subset, …” The link lets readers follow the term to its definition.", status: 'draft', basedOn: "v0.9.3#57c6c095" } },
  "dep.gap-orthogonal-projection-operator-adjoint": { note: { en: "The characterization of an orthogonal projection is “$P^{2} = P$ and $P^{\\ast} = P$,” which uses the **adjoint operator** directly.", status: 'draft', basedOn: "v0.9.3#c67b19e0" } },
  "dep.gap-prop.power-rules-ordered-field": { note: { en: "The power rules use the **ordered field** structure of $\\mathbb{R}$ (comparison, absolute value, and monotonicity).", status: 'draft', basedOn: "v0.9.3#722cf8dd" } },
  "dep.gap-thm.gauss-equation-gauss-curvature": { note: { en: "The Gauss equation expresses $K$ in terms of the first and second fundamental forms. The conclusion refers precisely to the **Gauss curvature** $K$.", status: 'draft', basedOn: "v0.9.3#f032b818" } },
  "dep.category-isomorphism": { note: { en: "An isomorphism is a concept **in a category** (an invertible morphism), so a category must be given first.", status: 'draft', basedOn: "v0.9.3#f7b94310" } },
  "dep.group-grouporder": { note: { en: "The order of a group and the order of an element are both quantities defined for **groups**.", status: 'draft', basedOn: "v0.9.3#e795879f" } },
  "dep.grouporder-vs": { note: { en: "The basis existence theorem counts the “cardinality of a basis,” while the group side uses the language “$|G|$ is the order.” The two notions of size correspond here.", status: 'draft', basedOn: "v0.9.3#5e210bbd" } },
  "dep.cauchy-complete": { note: { en: "**Completeness is defined by “every Cauchy sequence converges.”** There was previously no edge between these two nodes, so readers of `def.complete` had no link explaining what a Cauchy sequence is, and readers of the Cauchy sequence node had no link showing where it is used.", status: 'draft', basedOn: "v0.9.3#5e3f1b4e" } },
  "dep.realcomplete-complete": { note: { en: "$\\mathbb{R}$ is a **complete ordered field**. Completeness here means **order completeness** (existence of suprema). It is equivalent to “metric completeness” (convergence of Cauchy sequences) on $\\mathbb{R}$, and that equivalence requires a theorem beyond the definitions. ⚠ The two kinds of completeness are distinct concepts that happen to coincide here.", status: 'draft', basedOn: "v0.9.3#492d2b3e" } },
  "e191.analogy": { note: { en: "**Same name, different concepts** (the third is order completeness, covered by the edge for `thm.real-ordered-field`):\n\n- `def.complete`: completeness of a metric space means **every Cauchy sequence converges** (a property of the metric).\n\n- Completeness of a measure space (the family around `def.null-set`): **subsets of null sets are still measurable** (a property of the $\\sigma$-algebra).\n\n- Order completeness: every nonempty subset bounded above has a supremum (a property of $\\le$).\n\n⚠ All three happen to hold on $\\mathbb{R}$, so beginners can easily mistake them for the same property. They come apart on other spaces ($\\mathbb{Q}$ is order-incomplete, and a measure space can be complete as a measure space and incomplete as a metric space, or vice versa).\n\n⛔ A definition edge is invalid. One says “all such sequences converge,” and the other says “all null sets belong to the $\\sigma$-algebra.” Neither implies the other.", status: 'draft', basedOn: "v0.9.3#e0d3af74" } },
  "dep.mobius-quotient": { note: { en: "The Möbius strip **is** a quotient space of the square. The “gluing” in the definition is precisely the quotient topology.", status: 'draft', basedOn: "v0.9.3#59b141a7" } },
  "dep.mobius-klein": { note: { en: "The standard construction of the Klein bottle is to “glue two Möbius strips along their boundaries.” This edge was previously missing (the note mentioned it without a corresponding node).", status: 'draft', basedOn: "v0.9.3#6b8c08ee" } },
  "ana.condab-abeliancat": { note: { en: "Both answer the same question: **In what kind of category can we safely do homological algebra?**\n- Abelian category: kernels and cokernels exist, and all monomorphisms and epimorphisms are regular $\\implies$ the snake lemma and long exact sequences hold.\n- $\\mathrm{CondAb}$: it is first shown to be preabelian and to satisfy AB3–AB6, then “having enough compact projective objects” makes Ext computable (`thm.condab-ab`).\n\n⚠ This is an analogy rather than an implication. $\\mathrm{CondAb}$ **is** an abelian category (as proved in that part of `thm.condab-ab`), so the analogy is “example $\\leftrightarrow$ general framework” rather than a comparison between parallel theories.", status: 'draft', basedOn: "v0.9.3#4aaeb12a" } },
  "dep.zeta-series": { note: { en: "The **definition** of $\\zeta$ is a series. Its convergence is established using general tests for series convergence.", status: 'draft', basedOn: "v0.9.3#78fc6071" } },
  "dep.zeta-absconv": { note: { en: "When $\\operatorname{Re}s > 1$, $\\sum n^{-s}$ **converges absolutely**. This justifies rearrangement and termwise differentiation.", status: 'draft', basedOn: "v0.9.3#27cde2ae" } },
  "dep.zeta-holo": { note: { en: "The conclusion “$\\zeta$ is holomorphic on that half-plane” uses the definition of holomorphicity (uniform convergence on compact subsets $\\implies$ holomorphic).", status: 'draft', basedOn: "v0.9.3#f6e9916b" } },
  "dep.zeta-continuation": { note: { en: "The note's claim that it “extends to $\\mathbb{C}$, with its only pole at $s = 1$” is an application of **analytic continuation**.", status: 'draft', basedOn: "v0.9.3#a7b13023" } },
  "dep.plane-proj": { note: { en: "The example gives the matrix of an orthogonal projection and checks each condition in the definition (idempotent + self-adjoint).", status: 'draft', basedOn: "v0.9.3#da575484" } },
  "dep.plane-ls": { note: { en: "The note treats it as the geometric core of least squares (the residual is orthogonal to the subspace).", status: 'draft', basedOn: "v0.9.3#aa7ece1d" } },
  "dep.regsurf-smooth": { note: { en: "The image $S = r(U)$ of a regular parametrized surface is a **2-dimensional smooth manifold**. $(u, v) \\mapsto r(u, v)$ itself is a (global) chart, and chart transitions use the $C^{2}$ property of changes of parameters. This uses the definition of a smooth manifold.", status: 'draft', basedOn: "v0.9.3#dda605fb" } },
  "dep-dif-k": { note: { en: "The proof requires computing the second fundamental form and $K$.", status: 'draft', basedOn: "v0.9.3#2d2d4602" } },
  "dep-cgc-k": { note: { en: "The subject is “constant Gauss curvature.”", status: 'draft', basedOn: "v0.9.3#8c02d833" } },
  "dep-cgc-form": { note: { en: "The entire argument uses only the first fundamental form (intrinsic).", status: 'draft', basedOn: "v0.9.3#a60ebf01" } },
  "dep.subset-powerset": { note: { en: "The elements of a power set are precisely the **subsets**: $A \\in \\mathcal{P}(X) \\iff A \\subseteq X$.", status: 'draft', basedOn: "v0.9.3#32e6c847" } },
  "dep.equinumerous-cardinal": { note: { en: "A cardinal is an equivalence class under equinumerosity. Equinumerosity must be defined before asking “how large is $A$?”", status: 'draft', basedOn: "v0.9.3#12ead210" } },
  "dep.cardinal-cantor": { note: { en: "“$\\#A < \\#\\mathcal{P}(A)$” is a comparison of **cardinalities**.", status: 'draft', basedOn: "v0.9.3#256acd8e" } },
  "dep.powerset-cantor": { note: { en: "The theorem compares the size of $A$ with that of its **power set**.", status: 'draft', basedOn: "v0.9.3#a5709765" } },
  "dep.cardinal-comparable-thm": { note: { en: "“Any two cardinals are comparable” is a proposition about **cardinals**.", status: 'draft', basedOn: "v0.9.3#24238580" } },
  "dep.powerset-outer-measure": { note: { en: "An outer measure is defined on **all subsets**: $\\mu^* : \\mathcal{P}(X) \\to [0, +\\infty]$.", status: 'draft', basedOn: "v0.9.3#b110697f" } },
  "ana.cod-gauss": { note: { en: "The Gauss equation and the Codazzi–Mainardi equations are the **two halves** of the fundamental equations of surface theory. The former governs intrinsic curvature (Gauss curvature is computed from the second fundamental form), and the latter governs the symmetry of the second fundamental form. The two stand side by side, with neither implying the other. Together they give the compatibility conditions for the fundamental theorem of surface theory.", status: 'draft', basedOn: "v0.9.3#bdb0a3bd" } },
  "dep.cover-branchedcover": { note: { en: "A branched covering is a **covering map** after finitely many branch points are removed, so “sheets” and “local homeomorphism” carry over directly from that definition.", status: 'draft', basedOn: "v0.9.3#96ce5efa" } },
  "dep.holomorphic-branchedcover": { note: { en: "The local form $z \\mapsto z^{e}$ follows from being “nonconstant and holomorphic” (open mapping + isolated zeros), with no additional hypothesis.", status: 'draft', basedOn: "v0.9.3#960ba4ff" } },
  "dep.arep-algebra": { note: { en: "A representation is a module over an algebra, with the action given by an algebra homomorphism", status: 'draft', basedOn: "v0.9.3#5f3eaabc" } },
  "dep.arep-module": { note: { en: "A representation is equivalent to a left $A$-module, and the module axioms are the representation axioms", status: 'draft', basedOn: "v0.9.3#05535bd2" } },
  "dep.arep-category": { note: { en: "The equivalence relates the category of representations to the category of modules", status: 'draft', basedOn: "v0.9.3#313d990b" } },
  "dep.rmorph-arep": { note: { en: "Both the domain and codomain of the homomorphism are representations", status: 'draft', basedOn: "v0.9.3#1a275db2" } },
  "dep.rmorph-modulehom": { note: { en: "A representation homomorphism is precisely a module homomorphism", status: 'draft', basedOn: "v0.9.3#2e3ed838" } },
  "dep.rmorph-linear": { note: { en: "An intertwiner is first of all a linear map", status: 'draft', basedOn: "v0.9.3#5bd71d39" } },
  "dep.grep-group": { note: { en: "The domain of a representation is a group", status: 'draft', basedOn: "v0.9.3#e512ed46" } },
  "dep.grep-arep": { note: { en: "A group representation is a special case of an algebra representation", status: 'draft', basedOn: "v0.9.3#c2b90eed" } },
  "dep.subrep-arep": { note: { en: "A subrepresentation is a subobject of a representation", status: 'draft', basedOn: "v0.9.3#23f0f0f2" } },
  "dep.subrep-invariant": { note: { en: "A subrepresentation is precisely an invariant subspace", status: 'draft', basedOn: "v0.9.3#731fa022" } },
  "dep.irr-subrep": { note: { en: "Irreducibility is defined in terms of subrepresentations", status: 'draft', basedOn: "v0.9.3#978fcb91" } },
  "dep.quot-subrep": { note: { en: "A quotient representation is constructed from a subrepresentation", status: 'draft', basedOn: "v0.9.3#9344a970" } },
  "dep.quot-quotmodule": { note: { en: "A quotient representation is precisely a quotient module", status: 'draft', basedOn: "v0.9.3#9b90d1da" } },
  "dep.dsum-arep": { note: { en: "The actions on the components are given by the representations", status: 'draft', basedOn: "v0.9.3#65f56470" } },
  "dep.tensor-tensor": { note: { en: "The tensor product representation is constructed using the tensor product", status: 'draft', basedOn: "v0.9.3#1803fe01" } },
  "dep.tensor-grep": { note: { en: "The diagonal action is defined on group representations", status: 'draft', basedOn: "v0.9.3#086ae399" } },
  "dep.dual-dualspace": { note: { en: "The dual representation uses the dual space", status: 'draft', basedOn: "v0.9.3#c084bb21" } },
  "dep.dual-arep": { note: { en: "The dual action is the contragredient action of the representation", status: 'draft', basedOn: "v0.9.3#d0e86ace" } },
  "dep.indec-dsum": { note: { en: "Indecomposability is defined in terms of direct sums", status: 'draft', basedOn: "v0.9.3#6aa7e2c8" } },
  "dep.indec-subrep": { note: { en: "Direct summands are subrepresentations", status: 'draft', basedOn: "v0.9.3#455d83f9" } },
  "dep.ss-irr": { note: { en: "Semisimple representations are built from irreducible representations", status: 'draft', basedOn: "v0.9.3#93a74fd7" } },
  "dep.ss-dsum": { note: { en: "Semisimplicity is expressed in terms of direct sums", status: 'draft', basedOn: "v0.9.3#40d8b1f7" } },
  "dep.char-arep": { note: { en: "The character is a function associated with a representation", status: 'draft', basedOn: "v0.9.3#543b1514" } },
  "dep.char-trace": { note: { en: "The character is defined as the trace", status: 'draft', basedOn: "v0.9.3#7571d814" } },
  "dep.gchar-grep": { note: { en: "A group character comes from a group representation", status: 'draft', basedOn: "v0.9.3#de1f01ed" } },
  "dep.gchar-char": { note: { en: "A group character is the restriction of an algebra character", status: 'draft', basedOn: "v0.9.3#5c7c4fe3" } },
  "dep.gchar-centralizer": { note: { en: "Conjugacy classes are characterized by centralizers", status: 'draft', basedOn: "v0.9.3#9ccc81eb" } },
  "dep.cf-group": { note: { en: "Class functions are defined on groups", status: 'draft', basedOn: "v0.9.3#3a1dee5c" } },
  "dep.cf-centralizer": { note: { en: "The centralizer is the stabilizer under the conjugation action", status: 'draft', basedOn: "v0.9.3#cc1471f9" } },
  "dep.ann-arep": { note: { en: "The annihilator is defined by the representation", status: 'draft', basedOn: "v0.9.3#c5199231" } },
  "dep.ann-ideal": { note: { en: "The annihilator is a two-sided ideal", status: 'draft', basedOn: "v0.9.3#a9654d78" } },
  "dep.jac-ann": { note: { en: "The radical equals the intersection of the annihilators of all simple modules", status: 'draft', basedOn: "v0.9.3#50cc2d05" } },
  "dep.jac-irr": { note: { en: "The equivalent characterization uses irreducible left modules", status: 'draft', basedOn: "v0.9.3#463385ec" } },
  "dep.simple-ring": { note: { en: "A simple algebra is a ring", status: 'draft', basedOn: "v0.9.3#b9d55c89" } },
  "dep.simple-ideal": { note: { en: "Simplicity is defined using two-sided ideals", status: 'draft', basedOn: "v0.9.3#1116715e" } },
  "dep.div-ring": { note: { en: "A division algebra is a ring", status: 'draft', basedOn: "v0.9.3#b8e8e7e7" } },
  "dep.div-field": { note: { en: "A field is a commutative division algebra", status: 'draft', basedOn: "v0.9.3#819df9f9" } },
  "dep.div-algebra": { note: { en: "A division algebra is a special case of an algebra", status: 'draft', basedOn: "v0.9.3#c99a18d3" } },
  "dep.alg-ring": { note: { en: "An algebra is first of all a ring, and its multiplication comes from the ring structure", status: 'draft', basedOn: "v0.9.3#46b25c30" } },
  "dep.schur-irr": { note: { en: "Schur's lemma assumes irreducible representations", status: 'draft', basedOn: "v0.9.3#976080f9" } },
  "dep.schur-rmorph": { note: { en: "The conclusion concerns homomorphisms between representations", status: 'draft', basedOn: "v0.9.3#8aee36b7" } },
  "dep.sym2-tensor": { note: { en: "The symmetric square is a quotient of the tensor square", status: 'draft', basedOn: "v0.9.3#d7360c8a" } },
  "dep.sym2-arep": { note: { en: "The symmetric square is applied to the representation space", status: 'draft', basedOn: "v0.9.3#aedb38ee" } },
  "dep.alt2-tensor": { note: { en: "The exterior square is a quotient of the tensor square", status: 'draft', basedOn: "v0.9.3#f21fe4ad" } },
  "dep.alt2-arep": { note: { en: "The exterior square is applied to the representation space", status: 'draft', basedOn: "v0.9.3#805c33ef" } },
  "dep.regrep-grep": { note: { en: "The regular representation is a special case of a group representation", status: 'draft', basedOn: "v0.9.3#365eea62" } },
  "dep.alg-module": { note: { en: "An algebra is first of all a module over the base ring", status: 'draft', basedOn: "v0.9.3#d81b2033" } },
  "dep.schur-div": { note: { en: "Schur's lemma asserts that the endomorphism ring is a division algebra", status: 'draft', basedOn: "v0.9.3#1afb04f3" } },
  "dep.schurscalar-ac": { note: { en: "The scalar conclusion requires algebraic closure", status: 'draft', basedOn: "v0.9.3#9ea90cbc" } },
  "dep.local-indecomposable": { note: { en: "Indecomposability is a hypothesis for locality", status: 'draft', basedOn: "v0.9.3#86ea059a" } },
  "dep.local-fitting": { note: { en: "The Fitting decomposition shows that every endomorphism that fails to be an automorphism is nilpotent", status: 'draft', basedOn: "v0.9.3#05f70729" } },
  "dep.local-cor": { note: { en: "The dichotomy “automorphism or nilpotent” implies that every nonunit is nilpotent", status: 'draft', basedOn: "v0.9.3#5a02595f" } },
  "dep.krull-indec": { note: { en: "The factors in the Krull–Schmidt decomposition are indecomposable representations", status: 'draft', basedOn: "v0.9.3#20e8b357" } },
  "dep.krull-directsum": { note: { en: "The decomposition is written as a direct sum of representations", status: 'draft', basedOn: "v0.9.3#9b742c83" } },
  "dep.nilpotent-indec": { note: { en: "The lemma assumes that $V$ is indecomposable", status: 'draft', basedOn: "v0.9.3#28980d29" } },
  "dep.maschke-subrep": { note: { en: "Maschke's theorem averages a projection onto a subrepresentation", status: 'draft', basedOn: "v0.9.3#7a3d8e9a" } },
  "dep.charip-classfun": { note: { en: "The inner product is defined on the space of class functions", status: 'draft', basedOn: "v0.9.3#fea95ccc" } },
  "dep.charip-groupchar": { note: { en: "Characters are typical inputs to the inner product", status: 'draft', basedOn: "v0.9.3#1f488584" } },
  "dep.fixdim-char": { note: { en: "The dimension of the fixed-point space is computed by averaging the character", status: 'draft', basedOn: "v0.9.3#00265886" } },
  "dep.fixdim-invariant": { note: { en: "$V^G$ is an invariant subspace", status: 'draft', basedOn: "v0.9.3#0176546e" } },
  "dep.chartable-classfun": { note: { en: "The rows of the character table are class functions", status: 'draft', basedOn: "v0.9.3#36853a02" } },
  "dep.chartable-groupchar": { note: { en: "The rows of the table are irreducible characters", status: 'draft', basedOn: "v0.9.3#553a8f7d" } },
  "dep.chartable-irr": { note: { en: "The rows are indexed by irreducible representations", status: 'draft', basedOn: "v0.9.3#5c17f879" } },
  "dep.jacobson-algebra": { note: { en: "The Jacobson criterion applies to finite-dimensional unital $F$-algebras", status: 'draft', basedOn: "v0.9.3#aa2d4c32" } },
  "dep.powerset-topology": { note: { en: "A topology is a subfamily of the **power set**, namely $\\mathcal{T} \\subseteq \\mathcal{P}(X)$.", status: 'draft', basedOn: "v0.9.3#def2293e" } },
  "dep.subset-topology": { note: { en: "Both “an open set is a subset of $X$” and “$\\mathcal{T}$ as a family of sets” describe subset relations.", status: 'draft', basedOn: "v0.9.3#b0c8b151" } },
  "dep.topology-base": { note: { en: "A basis is a “well-behaved” subfamily of the **family of open sets** whose members can be unioned to obtain every open set.", status: 'draft', basedOn: "v0.9.3#295d2da2" } },
  "dep.topology-continuous-map": { note: { en: "A continuous map satisfies the condition that “the preimage of every open set in $\\mathcal{T}_Y$ belongs to $\\mathcal{T}_X$.”", status: 'draft', basedOn: "v0.9.3#767d263b" } },
  "dep.continuous-map-homeo": { note: { en: "The requirement that “$f$ and $f^{-1}$ are both continuous” uses the notion of a **continuous map**.", status: 'draft', basedOn: "v0.9.3#58096fb8" } },
  "dep.topology-metric": { note: { en: "The family of open sets induced by $d$ (unions of open balls) is the topology in this definition. All three axioms can be checked individually (closure under arbitrary unions follows from the description in terms of balls, and closure under finite intersections follows from the triangle inequality). Thus **every metric space is a topological space**, and the converse fails.", status: 'draft', basedOn: "v0.9.3#9e1d2d14" } },
  "dep.topology-borel": { note: { en: "The Borel $\\sigma$-algebra is defined by taking $X$ to be a **topological space** and forming the $\\sigma$-algebra generated by all its open sets.", status: 'draft', basedOn: "v0.9.3#1a68e9bb" } },
  "dep.topology-engine-continuous": { note: { en: "The $\\varepsilon$-$\\delta$ formulation spells out **topological continuity** on the real numbers (or on metric spaces), where open balls are $\\varepsilon$ neighborhoods.", status: 'draft', basedOn: "v0.9.3#2bf64e8a" } },
  "dep.closed-set-compact-closed": { note: { en: "In “compact subsets are closed,” “closed” means a closed set in the sense of this definition.", status: 'draft', basedOn: "v0.9.3#72c5d0b5" } },
  "dep.base-metric": { note: { en: "In a metric space, “all open balls form a **basis** for the topology” is a standard example of the definition of a basis.", status: 'draft', basedOn: "v0.9.3#b2e70f0d" } },
  "dep.topology-subspace": { note: { en: "The subspace topology is obtained by intersecting the open sets in the **topology of the ambient space** with $Y$.", status: 'draft', basedOn: "v0.9.3#fa20c922" } },
  "dep.subset-subspace": { note: { en: "$Y \\subseteq X$ must first be given as a subset before its subspace topology can be defined.", status: 'draft', basedOn: "v0.9.3#b8a00aaa" } },
  "dep.topology-quotient": { note: { en: "The quotient topology asks which subsets of the quotient set **have open preimages**, with openness tested in the topology of the ambient space.", status: 'draft', basedOn: "v0.9.3#15b487fd" } },
  "dep.function-quotient": { note: { en: "The quotient topology starts with a **surjection** $\\pi : X \\twoheadrightarrow Y$ and uses it to equip $Y$ with a topology.", status: 'draft', basedOn: "v0.9.3#7ab86916" } },
  "dep.topology-hausdorff": { note: { en: "“Two points can be separated by **open sets**.” Open sets belong to the topology.", status: 'draft', basedOn: "v0.9.3#0da88448" } },
  "dep.topology-connected": { note: { en: "The condition “cannot be written as the union of two disjoint nonempty **open sets**” is stated in terms of the topology.", status: 'draft', basedOn: "v0.9.3#956664a8" } },
  "dep.topology-clopen": { note: { en: "A clopen set is both **open** and **closed**, with each concept supplying one of the two conditions.", status: 'draft', basedOn: "v0.9.3#08dfb6c5" } },
  "dep.induction-natarith": { note: { en: "Addition and multiplication are both **defined recursively**. The recursion theorem supplies exactly the existence and uniqueness assertion.", status: 'draft', basedOn: "v0.9.3#03039df0" } },
  "dep.omega-int": { note: { en: "$\\mathbb{Z}$ is built on $\\mathbb{N} \\times \\mathbb{N}$, and both its operations and its order come from $\\mathbb{N}$.", status: 'draft', basedOn: "v0.9.3#12fb86cb" } },
  "dep.induction-int": { note: { en: "Induction or recursion is needed to verify the **well-definedness** of addition, multiplication, and order.", status: 'draft', basedOn: "v0.9.3#08a478db" } },
  "dep.function-cauchy-null": { note: { en: "A “sequence” is a function $\\omega \\to \\mathbb{Q}$. Indices and subsequences are both expressed in the language of functions.", status: 'draft', basedOn: "v0.9.3#a7306610" } },
  "dep.ordered-abs": { note: { en: "Absolute value is defined on an **ordered field** (both $\\mathbb{Q}$ and $\\mathbb{R}$ are ordered fields).", status: 'draft', basedOn: "v0.9.3#0290336b" } },
  "dep.ordered-triangle": { note: { en: "The triangle inequality holds in every ordered field. The proof uses only a case split and compatibility of the order with addition.", status: 'draft', basedOn: "v0.9.3#4b22b19e" } },
  "dep.ordered-realfield": { note: { en: "The goal is to show that “the constructed $\\mathbb{R}$ is a **complete ordered field**.” The first two groups of axioms specify an ordered field, and the third is an additional requirement outside this definition.", status: 'draft', basedOn: "v0.9.3#af5c65a2" } },
  "dep.ordered-archimedean": { note: { en: "In “$\\mathbb{N}$ is unbounded above in $K$,” $K$ is an **ordered field** (the substructure generated from $\\mathbb{N}$ according to $1$ embeds in it).", status: 'draft', basedOn: "v0.9.3#db06c75e" } },
  "dep.cauchy-null-real": { note: { en: "⭐ The elements of $\\mathbb{R}$ are the equivalence classes of “Cauchy sequences modulo null sequences.” The construction rests directly on this.", status: 'draft', basedOn: "v0.9.3#78f8f9c6" } },
  "dep.cardinal-uncountable": { note: { en: "Expressed in terms of cardinality, the conclusion is $\\#\\mathbb{R} = 2^{\\aleph_0} > \\aleph_0$.", status: 'draft', basedOn: "v0.9.3#02ca8bff" } },
  "dep.function-field": { note: { en: "The two operations are two **functions** $F \\times F \\to F$ (specifying their domain first requires using the Cartesian product to construct $F \\times F$).", status: 'draft', basedOn: "v0.9.3#16e96a83" } },
  "dep.field-ordered": { note: { en: "An ordered field is a **field** equipped with a total order compatible with its operations.", status: 'draft', basedOn: "v0.9.3#7884a753" } },
  "dep.poset-ordered": { note: { en: "The $\\le$ in the definition is a **total order**, a partial order with comparability.", status: 'draft', basedOn: "v0.9.3#53b354f6" } },
  "dep.field-vs": { note: { en: "“Let $K$ be a field and $V$ a vector space over $K$.” The **coefficients** of a vector space come from a field. (Taking $K = \\mathbb{R}$ gives the most commonly used case, real vector spaces.)", status: 'draft', basedOn: "v0.9.3#bd440faa" } },
  "dep.wellorder-ordinal": { note: { en: "The second requirement for an ordinal is that “$\\in$ is a **well-order** on $\\alpha$.” The notion of a well-ordered set is needed to ask whether $\\in$ on a transitive set is a well-order.", status: 'draft', basedOn: "v0.9.3#9b2d0661" } },
  "def-link.wellorder-recursion": { note: { en: "The recursion theorem applies to **well-ordered sets**. The portion preceding each step must have a beginning and an end for the recursion to terminate.", status: 'draft', basedOn: "v0.9.3#b518710f" } },
  "def-link.ordinal-cardinal-comparable": { note: { en: "The proof of cardinal comparability goes through ordinals by first well-ordering $\\to$, passing to ordinals $\\to$, and using the fact that ordinals are always comparable.", status: 'draft', basedOn: "v0.9.3#ee587fdf" } },
  "def-link.ordinal-cardinal": { note: { en: "Strictly speaking, an equipotence class is too large to fit in any set. The standard convention takes the least **ordinal** in each equipotence class as its representative, and that ordinal is called the cardinal. (The $\\#A$ in this graph uses only injections and bijections, so this dependency is conceptual rather than definitional.)", status: 'draft', basedOn: "v0.9.3#b89e742d" } },
  "def-link.category-groups": { note: { en: "The category of groups has groups as objects and group homomorphisms as morphisms, and is a standard example of def.category.", status: 'draft', basedOn: "v0.9.3#6bd28a09" } },
  "def-link.group-groups": { note: { en: "The object class of the category of groups consists of all groups.", status: 'draft', basedOn: "v0.9.3#30524e2a" } },
  "def-link.category-abelian-groups": { note: { en: "The category of abelian groups is another standard example and is also a full subcategory of def.category-of-groups.", status: 'draft', basedOn: "v0.9.3#66159651" } },
  "def-link.group-abelian-groups": { note: { en: "Abelian groups are a special case of groups. The object class consists of the commutative groups in def.group.", status: 'draft', basedOn: "v0.9.3#f58eafbe" } },
  "analogy.grp-ab": { note: { en: "Ab is a full subcategory of Grp. Adding commutativity to the group operation gives an abelian group.", status: 'draft', basedOn: "v0.9.3#c07e3167" } },
  "dep.catset-category": { note: { en: "The category of sets has sets as objects and functions as morphisms, and is a standard example of def.category.", status: 'draft', basedOn: "v0.9.3#3b5c3ccc" } },
  "dep.cattop-category": { note: { en: "The category of topological spaces has topological spaces as objects and continuous maps as morphisms, and is a standard example of def.category.", status: 'draft', basedOn: "v0.9.3#66f79e98" } },
  "dep.cat-sets-def-category-of-abelian-groups": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cvect-category": { note: { en: "The category of vector spaces instantiates the general definition of a category with vector spaces as objects and linear maps as morphisms", status: 'draft', basedOn: "v0.9.3#aa194a39" } },
  "dep.cvect-linearmap": { note: { en: "The morphisms are precisely the K-linear maps", status: 'draft', basedOn: "v0.9.3#972fcf03" } },
  "dep.homfunctor-functor": { note: { en: "The Hom functors are two specific functors whose functoriality is checked using the definition of a functor", status: 'draft', basedOn: "v0.9.3#7bfa4e6a" } },
  "dep.homfunctor-cvect": { note: { en: "The source and target categories are both categories of vector spaces", status: 'draft', basedOn: "v0.9.3#d698a676" } },
  "dep.homfunctor-linearmap": { note: { en: "The Hom sets consist of linear maps, and the action on morphisms is given by precomposition or postcomposition", status: 'draft', basedOn: "v0.9.3#e692212e" } },
  "dep.homfunctor-dualspace": { note: { en: "The dual space is the value of the Hom functor at $W=K$, a special case of its application outside the definition of the Hom functor", status: 'draft', basedOn: "v0.9.3#3cbfbabf" } },
  "dep.forgetful-functor": { note: { en: "A forgetful functor instantiates the general definition of a functor on concrete categories", status: 'draft', basedOn: "v0.9.3#6f1d3462" } },
  "dep.forgetful-sets": { note: { en: "The standard target category is the category of sets", status: 'draft', basedOn: "v0.9.3#bcc6bb37" } },
  "dep.forgetful-top": { note: { en: "The forgetful functor for $\\mathbf{Top}\\to\\mathbf{Set}$ is a standard example outside the dependencies of the general definition", status: 'draft', basedOn: "v0.9.3#4d1496a6" } },
  "dep.forgetful-cvect": { note: { en: "The forgetful functor for $\\mathbf{Vect}_K\\to\\mathbf{Set}$ is a standard example outside the dependencies of the general definition", status: 'draft', basedOn: "v0.9.3#a8f01c85" } },
  "dep.forgetful-prop-ffnf": { note: { en: "The proposition concerns the forgetful functor's faithfulness and failure to be full", status: 'draft', basedOn: "v0.9.3#ba72acd6" } },
  "dep.forgetful-prop-fpl": { note: { en: "The proposition concerns preservation of limits by the forgetful functor", status: 'draft', basedOn: "v0.9.3#ccd4fb92" } },
  "dep.cat-sets-def-mono": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-def-presheaf": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-def-representable": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-lem-yoneda": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-thm-right-adjoint-criterion": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-top-def-chaus": { note: { en: "The statement uses the category of topological spaces $\\mathbf{Top}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#1502f8ff" } },
  "dep.cat-top-prop-chaus-reflective": { note: { en: "The statement uses the category of topological spaces $\\mathbf{Top}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#1502f8ff" } },
  "dep.cat-sets-def-sheaf": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-def-effective-equivalence": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-def-generator": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-ab-prop-condab-section": { note: { en: "The statement uses the category of abelian groups $\\mathbf{Ab}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "dep.injcrit-abelian": { note: { en: "The injectivity criterion is stated in an abelian category.", status: 'draft', basedOn: "v0.9.3#fb22f033" } },
  "dep.cat-ab-thm-topos-abelian-grothendieck": { note: { en: "The statement uses the category of abelian groups $\\mathbf{Ab}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "dep.cat-top-prop-cg-coreflective": { note: { en: "The statement uses the category of topological spaces $\\mathbf{Top}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#1502f8ff" } },
  "dep.grouppower-group": { note: { en: "Integer powers are defined using only group multiplication, the identity, and inverses.", status: 'draft', basedOn: "v0.9.3#bd3bb1cc" } },
  "dep.grouppower-order": { note: { en: "The order of an element is the least positive integer for which $x^{n}=e$ holds, stated directly in terms of integer powers.", status: 'draft', basedOn: "v0.9.3#554bc5b5" } },
  "dep.fg-group": { note: { en: "The multiplication and axioms of a free group are checked against the definition of a group.", status: 'draft', basedOn: "v0.9.3#65d1fb88" } },
  "dep.fgu-fg": { note: { en: "The universal property concerns free groups.", status: 'draft', basedOn: "v0.9.3#9911fd0f" } },
  "dep.fgu-adjoint": { note: { en: "The free functor and the forgetful functor form an adjoint pair.", status: 'draft', basedOn: "v0.9.3#48b43d3d" } },
  "dep.pgroup-group": { note: { en: "A p-group is a group with the additional requirement that its order be a power of a prime.", status: 'draft', basedOn: "v0.9.3#aba6d4fd" } },
  "dep.commutator-group": { note: { en: "Commutators are defined using group multiplication and inverses.", status: 'draft', basedOn: "v0.9.3#f2c2f524" } },
  "dep.commutator-subgroup": { note: { en: "The commutator subgroup is the subgroup generated by commutators.", status: 'draft', basedOn: "v0.9.3#e4629a53" } },
  "dep.commutator-solvable": { note: { en: "Solvability is defined using the derived series $G^{(i+1)}=[G^{(i)},G^{(i)}]$.", status: 'draft', basedOn: "v0.9.3#d199deb8" } },
  "dep.nilpotent-group": { note: { en: "The lower central series is defined using group multiplication and commutators.", status: 'draft', basedOn: "v0.9.3#b1f2b226" } },
  "dep.nilpotent-commutator": { note: { en: "The lower central series is obtained by iterating the commutator subgroup construction.", status: 'draft', basedOn: "v0.9.3#9eda796d" } },
  "dep.automorphism-group": { note: { en: "An automorphism is an isomorphism from a group to itself, so it presupposes the group structure.", status: 'draft', basedOn: "v0.9.3#a66b9869" } },
  "dep.automorphism-hom": { note: { en: "An automorphism is a special case of a homomorphism (a bijective homomorphism).", status: 'draft', basedOn: "v0.9.3#968370f9" } },
  "dep.inner-automorphism": { note: { en: "The inner automorphisms form a normal subgroup of the automorphism group.", status: 'draft', basedOn: "v0.9.3#7300b9ee" } },
  "dep.cat-sets-def-free-group-universal": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "def-link.category-module-category": { note: { en: "A module category has modules as objects and module homomorphisms as morphisms, and is a standard example of def.category in algebra.", status: 'draft', basedOn: "v0.9.3#3ba77882" } },
  "def-link.module-module-category": { note: { en: "The object class of the module category consists of all left A-modules.", status: 'draft', basedOn: "v0.9.3#2e13b894" } },
  "analogy.module-category-abelian": { note: { en: "Z-Mod and Ab are equivalent because modules over the integers are abelian groups. This is a special case common to module categories and the category of abelian groups.", status: 'draft', basedOn: "v0.9.3#07f8f187" } },
  "dep.ringhom-ring": { note: { en: "Ring homomorphisms are maps between unital rings.", status: 'draft', basedOn: "v0.9.3#38d92365" } },
  "dep.ringhom-propideal": { note: { en: "The proposition is stated in terms of the kernel and image of a ring homomorphism.", status: 'draft', basedOn: "v0.9.3#25640e5e" } },
  "dep.quotient-ideal": { note: { en: "A quotient ring is formed by taking the quotient by an ideal.", status: 'draft', basedOn: "v0.9.3#c8f98c18" } },
  "dep.quotient-ring": { note: { en: "Addition and multiplication in the quotient ring come from the original ring.", status: 'draft', basedOn: "v0.9.3#d30a184f" } },
  "dep.quotient-poly": { note: { en: "$K[x]/(f)$ is a standard example of a quotient ring.", status: 'draft', basedOn: "v0.9.3#339cbc2a" } },
  "dep.quotient-propideal": { note: { en: "The proposition concerns the correspondence of ideals in quotient rings.", status: 'draft', basedOn: "v0.9.3#2bd609d3" } },
  "dep.quotient-prime": { note: { en: "Prime and maximal ideals are characterized by their quotient rings.", status: 'draft', basedOn: "v0.9.3#f2dbb143" } },
  "dep.submodule-module": { note: { en: "A submodule is an additive subgroup of a module that is closed under the ring action.", status: 'draft', basedOn: "v0.9.3#f14ba8d6" } },
  "dep.submodule-injective": { note: { en: "Injective modules are defined by an extension property for submodules.", status: 'draft', basedOn: "v0.9.3#313aeee9" } },
  "dep.module-hom": { note: { en: "A module homomorphism preserves module addition and the ring action.", status: 'draft', basedOn: "v0.9.3#32d2df0a" } },
  "dep.quotient-module": { note: { en: "A quotient module is the quotient of a module by a submodule.", status: 'draft', basedOn: "v0.9.3#2ba701b0" } },
  "dep.quotient-submodule": { note: { en: "The object by which one quotients to form a quotient module must be a submodule.", status: 'draft', basedOn: "v0.9.3#3480c37b" } },
  "dep.quotient-map": { note: { en: "The quotient map is a module homomorphism, and the quotient module satisfies the universal property for homomorphisms.", status: 'draft', basedOn: "v0.9.3#b2d23380" } },
  "dep.prime-ideal": { note: { en: "A prime ideal is an ideal of a ring with the additional condition $ab \\in P \\implies a \\in P$ or $b \\in P$.", status: 'draft', basedOn: "v0.9.3#a56ccd2d" } },
  "dep.prime-quotient": { note: { en: "Primality is equivalent to the quotient ring $A/P$ being an integral domain.", status: 'draft', basedOn: "v0.9.3#b69a3cbd" } },
  "dep.maximal-ideal": { note: { en: "A maximal ideal is an ideal with the additional property of maximality.", status: 'draft', basedOn: "v0.9.3#00261ef9" } },
  "dep.maximal-quotient": { note: { en: "Maximality is equivalent to the quotient ring $A/M$ being a field.", status: 'draft', basedOn: "v0.9.3#e51a651e" } },
  "dep.prop-prime": { note: { en: "The proposition characterizes prime ideals in terms of quotient rings.", status: 'draft', basedOn: "v0.9.3#7f118d17" } },
  "dep.prop-maximal": { note: { en: "The proposition characterizes maximal ideals in terms of quotient rings.", status: 'draft', basedOn: "v0.9.3#96b31a5d" } },
  "dep.principal-ideal": { note: { en: "A principal ideal is a special case of an ideal, generated by a single element.", status: 'draft', basedOn: "v0.9.3#edda46fd" } },
  "dep.fractions-ring": { note: { en: "The field of fractions is constructed from an integral domain (a commutative ring with identity).", status: 'draft', basedOn: "v0.9.3#0ff70159" } },
  "dep.fractions-field": { note: { en: "The construction of the field of fractions takes fields as its target category.", status: 'draft', basedOn: "v0.9.3#76ac7b95" } },
  "dep.submodule-kernelimage": { note: { en: "Kernels and images of homomorphisms are examples of submodules.", status: 'draft', basedOn: "v0.9.3#28b88e18" } },
  "dep.fractions-ringhom": { note: { en: "The universal property of the field of fractions is stated in terms of ring homomorphisms.", status: 'draft', basedOn: "v0.9.3#91629a33" } },
  "dep.modcat-linearmap": { note: { en: "The morphisms of a module category are linear maps.", status: 'draft', basedOn: "v0.9.3#e4eea3df" } },
  "dep.quotient-ringhom": { note: { en: "Both the quotient map and the universal property of a quotient ring are stated in terms of ring homomorphisms.", status: 'draft', basedOn: "v0.9.3#59161561" } },
  "dep.cat-sets-ex-ab-of-categories": { note: { en: "The statement uses the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-top-ex-ab-of-categories": { note: { en: "The statement uses the category of topological spaces $\\mathbf{Top}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#1502f8ff" } },
  "dep.lch-compact": { note: { en: "The discussion of compact subsets of locally compact spaces is based on compactness.", status: 'draft', basedOn: "v0.9.3#0792e1fc" } },
  "dep.sym-real-def-semi-normed-ab-group": { note: { en: "The statement concerns the real numbers $\\mathbb{R}$ (a notational dependency)", status: 'draft', basedOn: "v0.9.3#0453d27b" } },
  "dep.banach-realchaus-acyclic": { note: { en: "The theorem assumes that V is a real Banach space", status: 'draft', basedOn: "v0.9.3#43055434" } },
  "dep.banach-rhomdisc": { note: { en: "M is a finite-dimensional real Banach space", status: 'draft', basedOn: "v0.9.3#e958b0e9" } },
  "def-link.abhaus-topab": { note: { en: "The proposition concerns the category of topological abelian groups.", status: 'draft', basedOn: "v0.9.3#2f257f15" } },
  "def-link.zs-proj": { note: { en: "The key to the proof is that $\\mathbb{Z}[S]$ is projective on Stonean spaces.", status: 'draft', basedOn: "v0.9.3#17f06806" } },
  "def-link.zs-cond": { note: { en: "Both $N$ and $\\operatorname{RHom}$ belong to the category of condensed abelian groups.", status: 'draft', basedOn: "v0.9.3#353124bf" } },
  "def-link.kbfc-kbounded": { note: { en: "The proposition asserts that filtered colimits preserve “$K$-bounded exactness.”", status: 'draft', basedOn: "v0.9.3#34020f57" } },
  "def-link.kbfc-seminorm": { note: { en: "The objects under discussion are complexes of seminormed abelian groups, and isometry is with respect to the seminorms.", status: 'draft', basedOn: "v0.9.3#b184d63a" } },
  "def-link.cfn-banach": { note: { en: "Banach abelian groups appear in the conclusion (completeness of the coefficients passes to the space of continuous functions).", status: 'draft', basedOn: "v0.9.3#ddd9d62a" } },
  "def-link.cfn-seminorm": { note: { en: "The supremum norm is defined using the seminorm on the coefficients.", status: 'draft', basedOn: "v0.9.3#c7b2c2a9" } },
  "def-link.pcpu-normal": { note: { en: "The second statement concerns partitions of unity in normal spaces.", status: 'draft', basedOn: "v0.9.3#dc211de2" } },
  "def-link.kanadj-kan": { note: { en: "The proposition says that the existence of Kan extensions is equivalent to precomposition having an adjoint.", status: 'draft', basedOn: "v0.9.3#77468625" } },
  "def-link.kanadj-adj": { note: { en: "The other side is the definition of an adjunction.", status: 'draft', basedOn: "v0.9.3#29a1ab32" } },
  "def-link.pfcat-eval": { note: { en: "Computing “pointwise” refers to the evaluation functor $T \\mapsto T(X)$.", status: 'draft', basedOn: "v0.9.3#4e054e3a" } },
  "dep.cat-sets-thm-presheaf-limits-colimits": { note: { en: "The statement takes the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-top-cor-cond-ktop-finite-products": { note: { en: "The statement takes the category of topological spaces $\\mathbf{Top}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#1502f8ff" } },
  "def-link.cechhigher-cech": { note: { en: "The proposition says that the Čech cohomology of this presheaf vanishes.", status: 'draft', basedOn: "v0.9.3#a2616840" } },
  "def-link.ffinj-ff": { note: { en: "The proposition assumes full faithfulness.", status: 'draft', basedOn: "v0.9.3#a1c0b7ad" } },
  "def-link.adjdiag-adj": { note: { en: "The conclusion is the version of the adjunction on functor categories.", status: 'draft', basedOn: "v0.9.3#b87bc01a" } },
  "def-link.kanff-kan": { note: { en: "The proposition concerns left Kan extensions along fully faithful functors.", status: 'draft', basedOn: "v0.9.3#91ed2b16" } },
  "def-link.compactops-compact": { note: { en: "All three statements concern compactness.", status: 'draft', basedOn: "v0.9.3#6848471f" } },
  "def-link.tensoruniv-bilinear": { note: { en: "The tensor product is a construction on modules.", status: 'draft', basedOn: "v0.9.3#02726a0f" } },
  "def-link.adjcomp-adj": { note: { en: "The proposition gives the composition law for adjunctions.", status: 'draft', basedOn: "v0.9.3#63758ba8" } },
  "def-link.pontbanach-dual": { note: { en: "In the finite-dimensional case, the dual reduces to the vector space dual.", status: 'draft', basedOn: "v0.9.3#55e3dce8" } },
  "dep.banach-pontryagin-fd": { note: { en: "V is a finite-dimensional real Banach space", status: 'draft', basedOn: "v0.9.3#ced372c4" } },
  "def-link.disccoprod-condab": { note: { en: "The targets are all condensed abelian groups.", status: 'draft', basedOn: "v0.9.3#ea2320ba" } },
  "def-link.condquot-condab": { note: { en: "The proposition compares the topological quotient with the condensed quotient.", status: 'draft', basedOn: "v0.9.3#8e119b05" } },
  "dep.cat-sets-prop-topos-morphism-from-object": { note: { en: "The statement takes the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "def-link.fsections-section": { note: { en: "What is preserved is sections and retractions.", status: 'draft', basedOn: "v0.9.3#d780c6e3" } },
  "def-link.ffnotfull-ff": { note: { en: "The question is whether the functors are faithful and whether they are full.", status: 'draft', basedOn: "v0.9.3#cc11006d" } },
  "def-link.natisoinv-equiv": { note: { en: "Being an equivalence is invariant under natural isomorphism.", status: 'draft', basedOn: "v0.9.3#17c960a8" } },
  "def-link.matcat-cat": { note: { en: "The first thing to check is that this is a small category.", status: 'draft', basedOn: "v0.9.3#44f7ac79" } },
  "def-link.algcatlim-limit": { note: { en: "This explains how to compute limits and colimits in these categories.", status: 'draft', basedOn: "v0.9.3#1f5271a6" } },
  "def-link.adjnat-adjoint": { note: { en: "The naturality of the adjunction bijection is written as an explicit equation.", status: 'draft', basedOn: "v0.9.3#0746505b" } },
  "def-link.currying-adjoint": { note: { en: "Currying is an adjunction.", status: 'draft', basedOn: "v0.9.3#b5b30d24" } },
  "def-link.unitcounit-adjunit": { note: { en: "The unit and counit are computed in each example.", status: 'draft', basedOn: "v0.9.3#3af851a5" } },
  "def-link.copowers-adjoint": { note: { en: "Copowers give a left adjoint.", status: 'draft', basedOn: "v0.9.3#e92d8052" } },
  "def-link.forgetexact-exactfun": { note: { en: "The discussion concerns exactness.", status: 'draft', basedOn: "v0.9.3#94bde000" } },
  "dep.cat-sets-prop-free-objects-examples": { note: { en: "The statement takes the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-prop-forgetful-faithful-not-full": { note: { en: "The statement takes the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-prop-algebra-categories-limits": { note: { en: "The statement takes the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-prop-currying": { note: { en: "The statement takes the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-prop-copowers-give-adjoint": { note: { en: "The statement takes the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-sets-prop-forgetful-preserves-limits": { note: { en: "The statement takes the category of sets $\\mathbf{Set}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#45ea6a30" } },
  "dep.cat-top-prop-forgetful-faithful-not-full": { note: { en: "The statement takes the category of topological spaces $\\mathbf{Top}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#1502f8ff" } },
  "dep.cat-ab-prop-forgetful-faithful-not-full": { note: { en: "The statement takes the category of abelian groups $\\mathbf{Ab}$ as its ambient category", status: 'draft', basedOn: "v0.9.3#7dab3521" } },
  "def-link.numberfn-function": { note: { en: "A function is a map **taking values in a set of numbers**. The notion of a map comes first, so that we can single out the class called functions.", status: 'draft', basedOn: "v0.9.3#7f13e196" } },
  "def-link.numberfn-real": { note: { en: "Here “sets of numbers” are subsets of $\\mathbb{R}$ or $\\mathbb{C}$, so the real and complex numbers come first.", status: 'draft', basedOn: "v0.9.3#b939eda9" } },
  "def-link.sep-subset": { note: { en: "The $B = \\{ x \\in A : \\varphi (x, p) \\}$ given by the axiom schema of separation is precisely a **subset** of $A$. “Selecting elements only from $A$” is exactly what $\\subseteq$ means.", status: 'draft', basedOn: "v0.9.3#c54ca509" } },
  "def-link.power-subset": { note: { en: "The statement of the power set axiom explicitly uses the subset symbol $x \\in \\mathcal{P}(A) \\iff x \\subseteq A$.", status: 'draft', basedOn: "v0.9.3#adfd6bf2" } },
  "def-link.pair-pairing": { note: { en: "The **construction** of the ordered pair $(a, b) = \\{\\{a\\}, \\{a, b\\}\\}$ uses the **axiom of pairing** to make it a set.", status: 'draft', basedOn: "v0.9.3#01fb86fe" } },
  "def-link.pair-power": { note: { en: "The same construction also uses the **power set axiom**, since the power set of $\\{a, b\\}$ is what contains $\\{\\{a\\}, \\{a, b\\}\\}$.", status: 'draft', basedOn: "v0.9.3#de54386c" } },
  "def-link.rel-pair": { note: { en: "A relation is defined as a set of ordered pairs, and a function is a special kind of relation, so the entire definition rests on ordered pairs.", status: 'draft', basedOn: "v0.9.3#16e806fb" } },
  "def-link.product-pair": { note: { en: "The elements of $A \\times B = \\{ (a, b) : a \\in A, b \\in B \\}$ are ordered pairs.", status: 'draft', basedOn: "v0.9.3#0b76281e" } },
  "def-link.choicefn-rel": { note: { en: "A choice function is first of all a **function**. The definition explicitly requires that “$f$ is a function, $\\operatorname{dom} f = F$.”", status: 'draft', basedOn: "v0.9.3#973c0b14" } },
  "def-link.ac-choicefn": { note: { en: "The statement of the axiom of choice explicitly uses the term “choice function.” Every family of sets $\\emptyset \\notin F$ has a choice function.", status: 'draft', basedOn: "v0.9.3#f2d51e43" } },
  "def-link.chain-poset": { note: { en: "A chain is a subset of a partially ordered set. The definition uses the partial order $\\preceq$ and comparability.", status: 'draft', basedOn: "v0.9.3#95b684d7" } },
  "def-link.wellorder-poset": { note: { en: "A well-ordered set is a totally ordered set (hence a partially ordered set) with the additional requirement that every nonempty subset have a least element.", status: 'draft', basedOn: "v0.9.3#2c993ca8" } },
  "def-link.zorn-poset": { note: { en: "Zorn's lemma is a proposition **about partially ordered sets**. Both the hypothesis and the conclusion depend on $\\preceq$ and upper bounds.", status: 'draft', basedOn: "v0.9.3#8a7dc415" } },
  "def-link.zorn-chain": { note: { en: "“Every chain in $P$ has an upper bound” is the central hypothesis of Zorn's lemma.", status: 'draft', basedOn: "v0.9.3#4af8d2da" } },
  "def-link.hausdorff-poset": { note: { en: "The Hausdorff maximal principle is stated for a partially ordered set $(P, \\preceq )$.", status: 'draft', basedOn: "v0.9.3#2e53a657" } },
  "def-link.hausdorff-chain": { note: { en: "The whole principle says that a chain can be extended to a maximal chain.", status: 'draft', basedOn: "v0.9.3#083b1885" } },
  "def-link.wo-wellorder": { note: { en: "The well-ordering theorem asserts that every set can be well ordered, using precisely the notion of a well-ordered set.", status: 'draft', basedOn: "v0.9.3#3cff6be5" } },
  "def-link.basis-vs": { note: { en: "The “basis” in “every vector space has a basis” is defined by linear independence and spanning.", status: 'draft', basedOn: "v0.9.3#d5d7ea07" } },
  "def-link.ext-subset": { note: { en: "The most commonly used property of subsets, $A = B \\iff A \\subseteq B \\wedge B \\subseteq A$ (**mutual inclusion**), is a direct consequence of the **axiom of extensionality**.", status: 'draft', basedOn: "v0.9.3#837cea8f" } },
  "def-link.ext-empty": { note: { en: "The axiom schema of separation gives the existence of the empty set. The **axiom of extensionality** shows that there is **at most one** such set, which makes the notation $\\emptyset$ meaningful.", status: 'draft', basedOn: "v0.9.3#e4d70f4d" } },
  "def-link.integral-simple-props": { note: { en: "All four properties concern the **integral of a simple function** $\\int \\varphi \\, d\\mu$.", status: 'draft', basedOn: "v0.9.3#adab64a7" } },
  "def-link.simple-function-props": { note: { en: "The proposition concerns two simple functions, $\\varphi$ and $\\psi$.", status: 'draft', basedOn: "v0.9.3#0799ade1" } },
  "def-link.lplus-fatou-cor": { note: { en: "For $\\{f_n\\} \\subseteq L^+$ and $f \\in L^+$, the entire corollary concerns **nonnegative measurable functions**.", status: 'draft', basedOn: "v0.9.3#713e8643" } },
  "def-link.metric-covering": { note: { en: "The lemma selects a family of **open balls** $B_j$, and open balls are defined in metric spaces.", status: 'draft', basedOn: "v0.9.3#5c420d2f" } },
  "def-link.measure-covering": { note: { en: "In $m(U)$ and $\\sum m(B_j)$, $m$ is a **measure** (Lebesgue measure).", status: 'draft', basedOn: "v0.9.3#32bc9f74" } },
  "def-link.average-operator-continuous": { note: { en: "The lemma concerns the continuity of the **averaging operator** $A_r f(x)$ with respect to $(r, x)$.", status: 'draft', basedOn: "v0.9.3#9a54ae78" } },
  "def-link.nbv-derivative": { note: { en: "The hypothesis is precisely $F \\in NBV$.", status: 'draft', basedOn: "v0.9.3#6f963a8d" } },
  "def-link.ac-nbv-derivative": { note: { en: "The second conclusion, $\\mu_F \\ll m$, uses **absolute continuity**.", status: 'draft', basedOn: "v0.9.3#7e539e7d" } },
  "def-link.ac-function-subset-bv": { note: { en: "The left-hand side of the equality is the set $AC([a, b])$ of all **absolutely continuous functions**.", status: 'draft', basedOn: "v0.9.3#510ea717" } },
  "def-link.conjugate-young": { note: { en: "Taking $\\lambda$ to be $1/p$ makes $\\lambda$ and $1 - \\lambda$ a pair of **conjugate exponents**. Young's inequality is the arithmetic foundation of Hölder's inequality.", status: 'draft', basedOn: "v0.9.3#d0ccb9ba" } },
  "def-link.power-powerset": { note: { en: "The **power set axiom** is what guarantees that $\\mathcal{P}(X)$ is a set. This is exactly what the statement means by “By the power set axiom, $\\mathcal{P}(X)$ is indeed a set.”", status: 'draft', basedOn: "v0.9.3#db45adb4" } },
  "def-link.choice-cardinal-comparable": { note: { en: "The cardinal comparability theorem explicitly assumes the **axiom of choice**. Without it, two cardinals need not be comparable.", status: 'draft', basedOn: "v0.9.3#6b1b2b3a" } },
  "def-link.ae-integral-zero": { note: { en: "This is what a.e. means in the conclusion “$f = 0$ **almost everywhere**.”", status: 'draft', basedOn: "v0.9.3#593d617b" } },
  "def-link.ae-cauchy-in-measure": { note: { en: "The subsequence selected in the conclusion converges **almost everywhere**.", status: 'draft', basedOn: "v0.9.3#4c792b16" } },
  "def-link.ae-fatou": { note: { en: "The hypothesis “$f_n \\to f$ **a.e.**” is where this differs from Fatou's lemma.", status: 'draft', basedOn: "v0.9.3#c5a457dc" } },
  "def-link.integrable-integrals-equal": { note: { en: "The hypothesis $f, g \\in L^1(\\mu)$ says that both functions are **integrable**.", status: 'draft', basedOn: "v0.9.3#56daaed9" } },
  "def-link.integrable-nbv-derivative": { note: { en: "The conclusion $F' \\in L^1(m)$ asserts **integrability**.", status: 'draft', basedOn: "v0.9.3#576675ba" } },
  "def-link.limit-yoneda-embedding": { note: { en: "A limit in “$\\delta$ **preserves all limits**” is a **universal cone**.", status: 'draft', basedOn: "v0.9.3#ee786896" } },
  "def-link.ff-faithful-yoneda-embedding": { note: { en: "“$\\delta$ is a **fully faithful** functor” uses the definitions of faithful and full.", status: 'draft', basedOn: "v0.9.3#b5d6b572" } },
  "def-link.representable-yoneda": { note: { en: "The $h^{X} = \\operatorname{Hom}_{\\mathcal{C}}(X, -)$ in the lemma is precisely the **representable functor**.", status: 'draft', basedOn: "v0.9.3#ca88b75d" } },
  "def-link.adjoint-preserves-limits": { note: { en: "The theorem assumes a pair of **adjoint functors** $F \\dashv G$.", status: 'draft', basedOn: "v0.9.3#8a235ffe" } },
  "def-link.limit-preserves-limits": { note: { en: "The conclusion is $G(\\lim D) \\cong \\lim (G \\circ D)$, with **limits** on both sides.", status: 'draft', basedOn: "v0.9.3#e6a828e1" } },
  "def-link.representable-adjoint-criterion": { note: { en: "The right-hand side of the criterion says that $\\operatorname{Hom}_{\\mathcal{D}}(F(-), Y)$ is **representable**.", status: 'draft', basedOn: "v0.9.3#0797f761" } },
  "def-link.limit-adjoint-criterion": { note: { en: "The proposition equates “all **limits** exist” with “$\\Delta$ has a right adjoint.”", status: 'draft', basedOn: "v0.9.3#dd44c260" } },
  "def-link.limit-saft": { note: { en: "The hypotheses of completeness and **limit preservation**, and the limit used to construct $F(X)$.", status: 'draft', basedOn: "v0.9.3#5bb3d1a3" } },
  "def-link.comma-saft": { note: { en: "In the construction of $F(X)$, the index ranges over the **comma category** $X \\downarrow G$.", status: 'draft', basedOn: "v0.9.3#89f48460" } },
  "def-link.kan-ex": { note: { en: "Both examples identify something with a **left Kan extension**.", status: 'draft', basedOn: "v0.9.3#c81b57f2" } },
  "def-link.adjoint-kan-ex": { note: { en: "**(2)** says that the right adjoint is the Kan extension of $1_{\\mathcal{C}}$ along $F$. The right-hand side is an **adjoint**.", status: 'draft', basedOn: "v0.9.3#a03adc49" } },
  "def-link.limit-kan-ex": { note: { en: "**(1)** says that the colimit is a Kan extension along $I \\to \\mathbf{1}$.", status: 'draft', basedOn: "v0.9.3#23eb24ad" } },
  "def-link.compact-stonecech": { note: { en: "The Stone–Čech compactification is constructed inside a **Tychonoff cube**. Compactness is used both for the closure and for the cube.", status: 'draft', basedOn: "v0.9.3#9910d7df" } },
  "def-link.projective-gleason": { note: { en: "Gleason's theorem identifies the **projective objects** of $\\mathbf{CHaus}$.", status: 'draft', basedOn: "v0.9.3#83991e92" } },
  "def-link.stone-gleason": { note: { en: "The objects identified are **Stonean spaces**.", status: 'draft', basedOn: "v0.9.3#dcef7b45" } },
  "def-dep.nat-yoneda": { note: { en: "The lemma describes the set of all **natural transformations** from $h^{X}$ to $F$.", status: 'draft', basedOn: "v0.9.3#160dc020" } },
  "def-dep.functor-yoneda": { note: { en: "The lemma holds for **any functor** $F : \\mathcal{C} \\to \\mathbf{Set}$.", status: 'draft', basedOn: "v0.9.3#c0fdaf19" } },
  "def-dep.nat-yoneda-embedding": { note: { en: "Full faithfulness here means a bijection between the **set of natural transformations** $\\operatorname{Hom}_{\\widehat{\\mathcal{C}}}(h_{X}, h_{Y})$ and $\\operatorname{Hom}_{\\mathcal{C}}(X, Y)$.", status: 'draft', basedOn: "v0.9.3#ba4b803c" } },
  "def-dep.adjoint-criterion": { note: { en: "The criterion determines whether $F$ has a **right adjoint**.", status: 'draft', basedOn: "v0.9.3#648ac9cd" } },
  "def-dep.adjoint-ff": { note: { en: "The proposition concerns the functor that is the left (or right) adjoint in an **adjunction**.", status: 'draft', basedOn: "v0.9.3#5aba3979" } },
  "def-dep.ff-adjoint": { note: { en: "“$F$ is **fully faithful**” uses the definitions of faithful and full.", status: 'draft', basedOn: "v0.9.3#73e34c43" } },
  "def-dep.unit-adjoint-ff": { note: { en: "The other side of the proposition says that the **unit** $\\eta$ is an isomorphism.", status: 'draft', basedOn: "v0.9.3#bc7e0eba" } },
  "def-dep.diagram-limit-adjoint": { note: { en: "In the proposition, $\\Delta : \\mathcal{C} \\to \\mathcal{C}^{I}$ is the **constant diagram functor**, and $\\mathcal{C}^{I}$ is the category of diagrams.", status: 'draft', basedOn: "v0.9.3#26c77e68" } },
  "def-dep.adjoint-saft": { note: { en: "SAFT concludes that $G$ has a **left adjoint**.", status: 'draft', basedOn: "v0.9.3#c8c2767d" } },
  "def-dep.adjoint-chaus-reflective": { note: { en: "“$\\mathbf{CHaus}$ is a **reflective subcategory**” means that the inclusion functor has a left adjoint.", status: 'draft', basedOn: "v0.9.3#ee75b99c" } },
  "def-dep.hausdorff-stonecech": { note: { en: "The step showing that $e_{K}$ is injective uses the fact that **compact Hausdorff spaces are $T_{3.5}$**.", status: 'draft', basedOn: "v0.9.3#3cc0d076" } },
  "def-dep.cech-sheafification": { note: { en: "Sheafification is obtained by applying the **Čech construction** twice to the presheaf.", status: 'draft', basedOn: "v0.9.3#908df056" } },
  "def-dep.adjoint-cg-coreflective": { note: { en: "“Coreflective” means that the inclusion functor has a **right adjoint**.", status: 'draft', basedOn: "v0.9.3#bb634a3f" } },
  "def-dep.limit-condab-section": { note: { en: "The conclusion says that it preserves **all limits and colimits**.", status: 'draft', basedOn: "v0.9.3#27169524" } },
  "def-dep.condab-ab": { note: { en: "The theorem says that $\\mathrm{CondAb}$ (**condensed abelian groups**) satisfies AB6 and AB4*.", status: 'draft', basedOn: "v0.9.3#5e207a09" } },
  "def-dep.stonean-projective": { note: { en: "The lemma takes **Stonean spaces** as input.", status: 'draft', basedOn: "v0.9.3#824fc531" } },
  "def-dep.projective-stonean": { note: { en: "The conclusion says that $\\mathbb{Z}\\cdot F$ is a **projective** object.", status: 'draft', basedOn: "v0.9.3#b48b9c10" } },
  "def-dep.generator-condab-generated": { note: { en: "The proposition identifies the objects that **generate** $\\mathrm{CondAb}$.", status: 'draft', basedOn: "v0.9.3#55518996" } },
  "def-dep.projective-condab-generated": { note: { en: "The generators are **finitely presented projective** objects.", status: 'draft', basedOn: "v0.9.3#e0555748" } },
  "def-dep.triangle-rotation": { note: { en: "The proposition concerns a basic property of **derived triangles**.", status: 'draft', basedOn: "v0.9.3#e27bf68d" } },
  "def-dep.equalizer-long-exact": { note: { en: "An “exact sequence” is itself a statement about **kernels and images**.", status: 'draft', basedOn: "v0.9.3#121ad681" } },
  "def-dep.injective-criterion": { note: { en: "The proposition gives four equivalent characterizations of **injective objects**.", status: 'draft', basedOn: "v0.9.3#c49407b8" } },
  "def-dep.mono-injective-criterion": { note: { en: "“Every **monomorphism** has a retraction” is one of the equivalent conditions.", status: 'draft', basedOn: "v0.9.3#e25feb5b" } },
  "def-dep.adjoint-injective-criterion": { note: { en: "“$\\operatorname{Hom}(-, I)$ is **exact**” means that this functor preserves exact sequences. This is the characterization involving adjointness.", status: 'draft', basedOn: "v0.9.3#a29edf9a" } },
  "def-dep.generator-topos-ab": { note: { en: "Take $\\{\\mathbb{Z}\\cdot X : X \\in S\\}$ as the small generating set, where $S$ is a generating set for $\\mathcal{T}$.", status: 'draft', basedOn: "v0.9.3#7828e0a2" } },
  "def-dep.abeliancat-topos-ab": { note: { en: "Part of the conclusion is that $\\mathcal{T}(\\mathbf{Ab})$ is an **abelian** category.", status: 'draft', basedOn: "v0.9.3#2312eec6" } },
  "def-dep.cg-quotient-locally-compact": { note: { en: "The theorem concerns **quotient maps**, the surjections that define the quotient topology.", status: 'draft', basedOn: "v0.9.3#ff27318e" } },
  "def-dep.cg-product-top": { note: { en: "The conclusion concerns the **product space** $X \\times Z \\to Y \\times Z$.", status: 'draft', basedOn: "v0.9.3#95ee7c26" } },
  "def-dep.firstiso-quotient-group": { note: { en: "The $G/\\ker\\varphi$ on the left-hand side of the theorem is a **quotient group**.", status: 'draft', basedOn: "v0.9.3#ac903105" } },
  "def-dep.firstiso-normal": { note: { en: "The kernel is a **normal** subgroup, which is precisely why one can quotient by it.", status: 'draft', basedOn: "v0.9.3#024d6dd9" } },
  "def-dep.quotient-group-normal": { note: { en: "Quotient groups are defined only for **normal** subgroups.", status: 'draft', basedOn: "v0.9.3#c2e67779" } },
  "def-dep.grouphom-subgroup": { note: { en: "The kernel and image are both **subgroups**.", status: 'draft', basedOn: "v0.9.3#b80c076e" } },
  "ana.sep-container": { note: { en: "The two proofs have **exactly the same structure**, with different objects plugged into it.\n\n**Construction of $\\omega$**. The axiom of infinity gives an inductive set $I$ (this already provides a container, so **no power set is needed**). Then use the axiom schema of separation to **select** from $I$ the elements that belong to every inductive subset, yielding the smallest closed family.\n\n**Construction of $A \\times B$**. First use the power set axiom to construct $\\mathcal{P}(\\mathcal{P}(A \\cup B))$. Then **select** the elements of the form (a,b).\n\n**The shared technique**. In set theory, when you want to construct a set consisting of things of a certain kind, you can never simply write `$\\{ x : \\varphi (x) \\}$` (that leads to Russell's paradox). The correct approach has two steps.\n**First find a set large enough to contain everything you need, then use the axiom schema of separation to select from it**.\n\n💡 When you want to construct a set and are unsure where to start, think back to these two steps.", status: 'draft', basedOn: "v0.9.3#3dc0e900" } },
  "ana.sup-extension": { note: { en: "Both definitions or proofs hinge on **the same operation**.\n\n- **Series with nonnegative terms**. $\\sum_{n} a_n := \\sup_N s_N$. Take the supremum of the partial sums directly, bypassing the calculation of a limit.\n- **Monotone convergence theorem**. $\\int f = \\lim \\int f_n$. The proof writes both sides as $\\sup$ and interchanges the operations ($\\sup$ and $\\sup$ can be interchanged without any conditions).\n\n**The shared technique**. For anything **monotonically increasing**, there is no need to discuss whether the limit exists. The supremum always exists in $[0, +\\infty]$, so the step of taking a limit is bypassed. This is why the proof of MCT needs the fewest assumptions and is the easiest to use.\n\n**The converse situation**. Once monotonicity is lost (Fatou, dominated convergence), an extra condition such as integrable domination is needed, because $\\sup$ is then unavailable.\n\n💡 When the existence of a limit is unclear, first ask whether you can make the construction monotone and then take the supremum.", status: 'draft', basedOn: "v0.9.3#e5f1c30d" } },
  "ana.sup-vs-maximal": { note: { en: "The two propositions are very similar in spirit, and both are nonconstructive.\n\n- **Least upper bound property** (completeness of $\\mathbb{R}$). For a nonempty set bounded above, $\\sup S$ **exists outright**. There is no need to approximate it.\n- **Zorn's lemma**. In a partially ordered set where every chain has an upper bound, **a maximal element exists outright**. There is no need to climb step by step.\n\n**The shared technique** is to replace an infinite process with the existence of an object and then use that object directly. This lets you take a supremum in analysis, a maximal ideal in algebra, or a maximal chain in set theory.\n\n⚠ Keep the difference in mind too. The least upper bound property is the **completeness** of $\\mathbb{R}$, proved from the construction of $\\mathbb{R}$. Zorn's lemma is equivalent to the **axiom of choice**. The first works in a specific totally ordered set. The second works in arbitrary partially ordered sets at the cost of an additional axiom.\n\n💡 This also explains why completeness of the real numbers and the axiom of choice look alike in proofs. They are the same kind of existence tool.", status: 'draft', basedOn: "v0.9.3#f49e1f9a" } },
  "def-dep.subset-rel": { note: { en: "A relation is a **subset** of $A \\times B$, and its domain $\\operatorname{dom} R$ and range $\\operatorname{ran} R$ are also subsets.", status: 'draft', basedOn: "v0.9.3#33fe4590" } },
  "def-dep.rel-function": { note: { en: "A function is a **special kind of relation**, with the sole additional requirement that each input have a unique output.", status: 'draft', basedOn: "v0.9.3#05823ebb" } },
  "def-dep.rel-poset": { note: { en: "A partial order $\\preceq$ is a **binary relation** on $A$. The relation comes first, followed by the three requirements of reflexivity, antisymmetry, and transitivity.", status: 'draft', basedOn: "v0.9.3#a5be2a6c" } },
  "def-dep.subset-chain": { note: { en: "A chain is a **subset** of $P$ with the additional requirement of pairwise comparability.", status: 'draft', basedOn: "v0.9.3#211d38b2" } },
  "def-dep.subset-wellorder": { note: { en: "“Every nonempty **subset** of $W$ has a least element.” Well-ordering is expressed by quantifying over subsets.", status: 'draft', basedOn: "v0.9.3#222ea2eb" } },
  "def-dep.subset-vs": { note: { en: "“Every **finite subset** of $S$ is linearly independent.” Linear independence is defined by checking each finite subset.", status: 'draft', basedOn: "v0.9.3#8d8b938a" } },
  "def-dep.function-metric-space": { note: { en: "The metric $d : X \\times X \\to [0, +\\infty)$ is a **function**, and the notation $d(x, y)$ denotes a function value.", status: 'draft', basedOn: "v0.9.3#d56277b1" } },
  "def-dep.metric-complete": { note: { en: "Both Cauchy sequences and convergence are discussed **in the metric space** $(X, d)$.", status: 'draft', basedOn: "v0.9.3#985a48a6" } },
  "def-dep.metric-seq-compact": { note: { en: "In “a subsequence converges to a point in $X$,” convergence is with respect to $d$.", status: 'draft', basedOn: "v0.9.3#7b3c7c4e" } },
  "def-dep.metric-compact": { note: { en: "This statement is about the metric space $(X, d)$, and the open cover uses the open sets induced by $d$.", status: 'draft', basedOn: "v0.9.3#9d765613" } },
  "def-dep.function-product-sigma": { note: { en: "The projection $\\pi_\\alpha$ is a **function**, and the cylinder set $\\pi_\\alpha^{-1}(E_\\alpha)$ is defined using a preimage.", status: 'draft', basedOn: "v0.9.3#0537318f" } },
  "def-dep.sigma-algebra-measure": { note: { en: "A measure is a function defined on the **$\\sigma$-algebra** $\\mathcal{M}$, with notation $\\mu : \\mathcal{M} \\to [0, +\\infty]$.", status: 'draft', basedOn: "v0.9.3#9a4013e3" } },
  "def-dep.measure-premeasure": { note: { en: "“It still satisfies the **two conditions for a measure**.” A premeasure generalizes the domain of a measure from a $\\sigma$-algebra to a ring.", status: 'draft', basedOn: "v0.9.3#f3946073" } },
  "def-dep.measure-finitely-additive": { note: { en: "Replacing **countable** additivity of a measure with **finite** additivity gives a finitely additive measure.", status: 'draft', basedOn: "v0.9.3#b818156c" } },
  "def-dep.measure-null-set": { note: { en: "A $\\mu$-null set is “a measurable set with $\\mu(E) = 0$,” and both $E$ and $\\mu$ come from the **measure space**.", status: 'draft', basedOn: "v0.9.3#506cc9e6" } },
  "def-link.function-section": { note: { en: "For the **function** $f : X \\times Y \\to \\mathbb{C}$, the second half of the definition of sections defines $f_x(y) := f(x, y)$.", status: 'draft', basedOn: "v0.9.3#9b291cff" } },
  "def-link.skyscraper-sheaf": { note: { en: "At a point $x$ a skyscraper sheaf takes the value $A$ and is zero elsewhere, with the gluing conditions checked on open sets one by one.", status: 'draft', basedOn: "v0.9.3#65a37b3c" } },

  "eq.real-continuity-epsilon-delta": { note: { en: "Both directions simply rewrite $|\\cdot|$ as the metric $d$, with no substantive mathematical content. This formally connects, on $\\mathbb{R}$, the $\\varepsilon$-$\\delta$ criterion with continuity in general metric spaces.", status: 'draft', basedOn: "v0.9.3#056879f0" } },
  "dep.real-lp": { note: { en: "The essential supremum is “the infimum of the levels at which $\\mu(\\{|f| > a\\}) = 0$ holds, taken over thresholds $a \\ge 0$,” with $a$ a real number.", status: 'draft', basedOn: "v0.9.3#e535b4b5" } },
  "dep.abs-cauchy-null": { note: { en: "In the defining formula $|x_m - x_n| < \\varepsilon$ for a Cauchy sequence, the symbol $|\\cdot|$ is this absolute value, and $\\varepsilon$ ranges over the **positive rational numbers** so that the definition makes sense before $\\mathbb{R}$ is constructed.", status: 'draft', basedOn: "v0.9.3#cbf53f28" } },
  "ana.embed-better-world": { note: { en: "Neither construction mathematically implies the other (one is a categorical embedding and the other a topological compactification). Both use **the same technique**.\n**When the object you have lacks something, first embed it in a larger setting, do the work there, then return to the original setting.**\n\n**Yoneda embedding** $\\mathcal{C} \\hookrightarrow \\widehat{\\mathcal{C}}$.\nIn $\\mathcal{C}$, even the product of two objects may fail to exist. In $\\widehat{\\mathcal{C}}$, **all limits and colimits exist**.\nSo whatever cannot be constructed in $\\mathcal{C}$ is constructed in $\\widehat{\\mathcal{C}}$ (the density theorem expresses it as a colimit of $h_{X}$).\n\n**Stone–Čech compactification** $X \\hookrightarrow \\beta X$.\n$X$ may fail to be compact or Hausdorff and may have very few continuous functions.\n$\\beta X$ has **all the good properties of a compact Hausdorff space** (provided by the Tychonoff cube).\nSo move analysis that cannot be done on $X$ to $\\beta X$ (condensed sets use $\\beta X$ as probes).\n\n**The shared technique** is to avoid forcing a construction in the original setting. First find or construct a larger setting with everything you need, embed the object there, do the work, then pull the result back.\n💡 When you get stuck because “this category or space simply lacks the object I need,” think back to these two examples.", status: 'draft', basedOn: "v0.9.3#660cb36e" } },
  "dep.natarith-int": { note: { en: "On $\\mathbb{Z}$, inside the formula $[a,b] + [c,d] := [a+c, b+d]$, the $+$ is addition of natural numbers.", status: 'draft', basedOn: "v0.9.3#317ef0b8" } },
  "dep.mf-form-derham": { note: { en: "Each term of the chain is the space of $k$-forms $\\Omega^{k}(M)$; the words closed and exact are also terms from the theory of forms (`def.exterior-derivative`).\n\n⭐ 2026-11-01 retargeted to $\\Omega^{k}(M)$ on **manifolds** (it previously pointed at the coordinate model on a Euclidean open set, so there was nowhere in the graph to look up what $\\Omega^{k}(M)$ is).\n\nThe level number is **computed**: the de Rham complex depends on the formal definition of forms at level 18, so it sits at level 20 itself; one should not bend the level number by wiring the edge to something else.", status: 'draft', basedOn: "v0.9.3#23706120" } },
  "e60.definition": { note: { en: "The bijection $p^{-1}(b_{0}) \\leftrightarrow \\pi_{1}(B)/p_{*}\\pi_{1}(E)$ uses precisely the sheets of an evenly covered neighborhood: the sheet containing $\\tilde{\\alpha}(1)$ is a piece $V_{j}$, and it determines the coset containing $[\\alpha]$.", status: 'draft', basedOn: "v0.9.3#d468235b" } },
  "e108.definition": { note: { en: "The full domain of the fractional linear transformation is $\\widehat{\\mathbb{C}}$: at $z = -d/c$ it takes the value $\\infty$, and at $\\infty$ it takes the value $a/c$.", status: 'draft', basedOn: "v0.9.3#42425e45" } },
  "e178.analogy": { note: { en: "The name is shared, but the mechanisms differ. Topological compactness concerns finiteness for **open covers**, while logical compactness says that **finite satisfiability** implies satisfiability of the whole set.\n\n⚠ There is a connection. Using Stone spaces (`def.stone-space`), compactness for propositional logic follows from “$\\{0,1\\}^{\\text{formulas}}$ is compact.” The graph has yet to represent this path with nodes, so only the analogy is recorded here.\n\n⛔ A definition edge is ruled out because the existing path from `def.compact` to `def.formula` would make the reverse edge form a cycle.", status: 'draft', basedOn: "v0.9.3#781cec88" } },
};
